INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('izar/tm_skills/ctm', 'ctm', 'izar', 'tm_skills', 'community', 'ctm izar tm_skills community CTM AI智能体提供持续威胁建模功能，帮助开发人员提高安全性和合规性 CTM AIエージェントは連続的脅威モデリング機能を提供し、開発者がセキュリティとコンプライアンスを高めることができます CTM AI 에이전트는 연속적 위협 모델링 기능을 제공하여 개발자가 보안 및 규정 준수를 강화할 수 있습니다 El agente ctm ofrece habilidades para el modelado de amenazas continuo, mejorando la seguridad L''agent ctm propose des compétences pour la modélisation de menaces continues, améliorant la sécurité Der ctm-Agent bietet Fähigkeiten für die kontinuierliche Bedrohungsmodellierung, die Sicherheit verbessert O ctm é uma habilidade de agente que ajuda na modelagem de ameaças contínua, permitindo que os desenvolvedores identifiquem e mitiguem riscos de segurança ctm - это навык агента, который помогает в постоянном моделировании угроз, позволяя разработчикам выявлять и смягчать риски безопасности ctm هو مهارة وسيطة تساعد في نمذجة التهديدات المستمرة، مما يسمح للمطورين بالتعرف على ومعالجة مخاطر الأمان Agent skills to help with Continuous Threat Modeling CTM AI智能体 持续威胁建模 安全风险识别 合规性管理 如何使用CTM CTM安装指南 CTM替代品 Agent skills to help with Continuous Threat Modeling');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('heddxh/NeoDB-You/compose-preview', 'community', 'heddxh', 'NeoDB-You', 'heddxh/NeoDB-You', 'compose-preview', 0, 0, 25, '2026-03-04T13:07:01.705Z', '2026-03-04T13:41:56.495Z', '1a2abd151c0721e7ccc83065e200e6ae2113d986d9247e626a4a0dd57c69091a', '{"id":"heddxh/NeoDB-You/compose-preview","name":"compose-preview","description":{"zh":"Compose Preview是一款基于Jetpack Compose和Material 3的NeoDB原生Android应用，提供强大的UI组件和Material设计","ja":"Compose Previewは、Jetpack ComposeとMaterial 3を使用して開発されたNeoDBのネイティブAndroidアプリです。強力なUIコンポーネントとMaterialデザインを提供します","ko":"Compose Preview는 Jetpack Compose와 Material 3로 개발된 NeoDB의 네이티브 안드로이드 앱으로, 강력한 UI 컴포넌트와 Material 디자인을 제공합니다","es":"Compose Preview es una aplicación Android nativa para NeoDB, desarrollada con Jetpack Compose y Material 3","fr":"Compose Preview est une application Android native pour NeoDB, développée avec Jetpack Compose et Material 3","de":"Compose Preview ist eine native Android-App für NeoDB, entwickelt mit Jetpack Compose und Material 3","pt":"O Compose Preview é um aplicativo Android nativo para NeoDB, desenvolvido com Jetpack Compose e Material 3/You. Ele oferece uma pré-visualização de composição para desenvolvedores.","ru":"Compose Preview - родное Android-приложение для NeoDB, созданное с Jetpack Compose и Material 3/You. Оно предоставляет предварительный просмотр композиции для разработчиков.","ar":"Compose Preview هو تطبيق أندرويد أصلي ل NeoDB، تم إنشاؤه باستخدام Jetpack Compose و Material 3/You. يقدم معاينة تركيبية للمطورين.","en":"A native Android app for NeoDB, crafted with Jetpack Compose and Material 3/You."},"seo":{"title":{"zh":"AI工具Compose Preview - 基于Jetpack Compose的NeoDB应用","ja":"AIエージェント Compose Preview - Jetpack ComposeとMaterial 3によるN...","ko":"AI 에이전트 Compose Preview - Jetpack Compose와 Material 3로 만든...","es":"Herramientas de IA: Compose Preview para NeoDB","fr":"Outils d''IA: Compose Preview pour NeoDB","de":"KI-Tools: Compose Preview für NeoDB","pt":"Ferramentas de IA: Compose Preview para NeoDB","ru":"ИИ Агенты: Compose Preview для NeoDB","ar":"أدوات الذكاء الاصطناعي: Compose Preview ل NeoDB","en":"compose-preview"},"description":{"zh":"Compose Preview是一款基于Jetpack Compose和Material 3的NeoDB原生Android应用，提供强大的UI组件和Material设计","ja":"Compose Previewは、Jetpack ComposeとMaterial 3を使用して開発されたNeoDBのネイティブAndroidアプリです。強力なUIコンポーネントとMaterialデザインを提供します","ko":"Compose Preview는 Jetpack Compose와 Material 3로 개발된 NeoDB의 네이티브 안드로이드 앱으로, 강력한 UI 컴포넌트와 Material 디자인을 제공합니다","es":"Compose Preview es una aplicación Android nativa para NeoDB, desarrollada con Jetpack Compose y Material 3","fr":"Compose Preview est une application Android native pour NeoDB, développée avec Jetpack Compose et Material 3","de":"Compose Preview ist eine native Android-App für NeoDB, entwickelt mit Jetpack Compose und Material 3","pt":"O Compose Preview é um aplicativo Android nativo para NeoDB, desenvolvido com Jetpack Compose e Material 3/You. Ele oferece uma pré-visualização de composiçã...","ru":"Compose Preview - родное Android-приложение для NeoDB, созданное с Jetpack Compose и Material 3/You. Оно предоставляет предварительный просмотр композиции дл...","ar":"Compose Preview هو تطبيق أندرويد أصلي ل NeoDB، تم إنشاؤه باستخدام Jetpack Compose و Material 3/You. يقدم معاينة تركيبية للمطورين.","en":"A native Android app for NeoDB, crafted with Jetpack Compose and Material 3/You."},"definition":{"en":"A native Android app for NeoDB, crafted with Jetpack Compose and Material 3/You."},"features":{"zh":["基于Jetpack Compose的UI组件","Material 3设计","NeoDB原生Android应用","强大的UI预览功能","简单易用的API"],"ja":["Jetpack Composeを使用したUIコンポーネント","Material 3デザイン","NeoDBのネイティブAndroidアプリ","強力なUIプレビュー機能","シンプルで使いやすいAPI"],"ko":["Jetpack Compose로 개발된 UI 컴포넌트","Material 3 디자인","NeoDB의 네이티브 안드로이드 앱","강력한 UI 미리 보기 기능","간단하고 사용하기 쉬운 API"],"es":["Desarrollada con Jetpack Compose","Diseño de Material 3","Aplicación Android nativa para NeoDB","Integración con herramientas de IA","Interfaz de usuario personalizable"],"fr":["Développée avec Jetpack Compose","Conception de Material 3","Application Android native pour NeoDB","Intégration avec des outils d''IA","Interface utilisateur personnalisable"],"de":["Entwickelt mit Jetpack Compose","Design von Material 3","Native Android-App für NeoDB","Integration mit KI-Tools","Benutzeroberfläche anpassbar"],"pt":["Desenvolvido com Jetpack Compose","Integração com Material 3/You","Pré-visualização de composição para NeoDB","Aplicativo Android nativo","Fácil de usar e personalizar"],"ru":["Разработано с Jetpack Compose","Интеграция с Material 3/You","Предварительный просмотр композиции для NeoDB","Родное Android-приложение","Легко использовать и настраивать"],"ar":["تم إنشاؤه باستخدام Jetpack Compose","التكامل مع Material 3/You","معاينة تركيبية ل NeoDB","تطبيق أندرويد أصلي","سهل الاستخدام والتعديل"]},"keywords":{"zh":["如何使用Compose Preview","什么是Jetpack Compose","NeoDB应用开发","Compose Preview安装","Material 3设计教程","AI工具比较","Compose Preview vs 其他工具"],"ja":["Compose Previewの使い方","Jetpack Composeとは","NeoDBアプリ開発","Compose Previewのインストール","Material 3デザインチュートリアル","AIエージェントの比較","Compose Previewと他のツールの比較"],"ko":["Compose Preview 사용법","Jetpack Compose란","NeoDB 애플리케이션 개발","Compose Preview 설치","Material 3 디자인 튜토리얼","AI 에이전트 비교","Compose Preview와 다른 도구 비교"],"es":["herramientas de IA para Android","cómo utilizar Compose Preview","NeoDB vs otras bases de datos","instalación de Compose Preview","guía de configuración de Compose Preview","alternativas a Compose Preview"],"fr":["outils d''IA pour Android","comment utiliser Compose Preview","NeoDB vs autres bases de données","installation de Compose Preview","guide de configuration de Compose Preview","alternatives à Compose Preview"],"de":["KI-Tools für Android","wie man Compose Preview verwendet","NeoDB vs andere Datenbanken","Installation von Compose Preview","Konfigurationsanleitung für Compose Preview","Alternativen zu Compose Preview"],"pt":["ferramentas de ia","como usar compose preview","o que é compose preview","compose preview vs outros","instalar compose preview","guia de configuração do compose preview","desenvolvimento de aplicativos android","jetpack compose tutorial"],"ru":["ИИ агенты","как использовать compose preview","что такое compose preview","compose preview vs другие","установить compose preview","руководство по настройке compose preview","разработка android-приложений","урок jetpack compose"],"ar":["أدوات الذكاء الاصطناعي","كيفية استخدام compose preview","ما هو compose preview","compose preview مقابل autres","تثبيت compose preview","دليل إعداد compose preview","تطوير تطبيقات أندرويد","دورة jetpack compose"]}},"owner":"heddxh","repo":"NeoDB-You","repoPath":"heddxh/NeoDB-You","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.705Z","topics":[],"category":"community","skillMd":{"name":"compose-preview","description":"Creates Compose Preview functions for composables. Use when asked to add preview, create preview, or generate @Preview for Compose UI.","bodyPreview":"# Compose Preview\n\n为 Jetpack Compose 函数创建预览。\n\n## 基本用法\n\n```kotlin\n@Preview\n@Composable\nprivate fun XxxPreview() {\n    AppTheme {\n        Xxx()\n    }\n}\n```\n\n## @Preview 注解参数\n\n| 参数                | 说明              | 示例                                                         |\n|-------------------|-----------------|------------------------------------------------------------|\n| `name`            | 预览名称            | `@Preview(name = \"Dark Mode\")`                             |\n| `group`           | 分组","body":"# Compose Preview\n\n为 Jetpack Compose 函数创建预览。\n\n## 基本用法\n\n```kotlin\n@Preview\n@Composable\nprivate fun XxxPreview() {\n    AppTheme {\n        Xxx()\n    }\n}\n```\n\n## @Preview 注解参数\n\n| 参数                | 说明              | 示例                                                         |\n|-------------------|-----------------|------------------------------------------------------------|\n| `name`            | 预览名称            | `@Preview(name = \"Dark Mode\")`                             |\n| `group`           | 分组名称            | `@Preview(group = \"Buttons\")`                              |\n| `widthDp`         | 宽度 (dp)         | `@Preview(widthDp = 320)`                                  |\n| `heightDp`        | 高度 (dp)         | `@Preview(heightDp = 640)`                                 |\n| `showBackground`  | 显示背景            | `@Preview(showBackground = true)`                          |\n| `backgroundColor` | 背景色 (ARGB Long) | `@Preview(backgroundColor = 0xFFFFFFFF)`                   |\n| `showSystemUi`    | 显示系统 UI         | `@Preview(showSystemUi = true)`                            |\n| `device`          | 设备规格            | `@Preview(device = \"id:pixel_5\")`                          |\n| `uiMode`          | UI 模式           | `@Preview(uiMode = Configuration.UI_MODE_NIGHT_YES)`       |\n| `locale`          | 语言              | `@Preview(locale = \"zh-rCN\")`                              |\n| `fontScale`       | 字体缩放            | `@Preview(fontScale = 1.5f)`                               |\n| `wallpaper`       | 壁纸              | `@Preview(wallpaper = Wallpapers.GREEN_DOMINATED_EXAMPLE)` |\n\n## Multipreview 注解\n\n创建自定义多预览注解以复用配置：\n\n```kotlin\n@Preview(name = \"Light\", uiMode = Configuration.UI_MODE_NIGHT_NO)\n@Preview(name = \"Dark\", uiMode = Configuration.UI_MODE_NIGHT_YES)\nannotation class ThemePreviews\n\n@Preview(name = \"Phone\", device = \"spec:width=411dp,height=891dp\")\n@Preview(name = \"Tablet\", device = \"spec:width=1280dp,height=800dp,dpi=240\")\nannotation class DevicePreviews\n```\n\n使用：\n\n```kotlin\n@ThemePreviews\n@DevicePreviews\n@Composable\nprivate fun MyComponentPreview() {\n    AppTheme {\n        MyComponent()\n    }\n}\n```\n\n## 设备规格\n\n### 预定义设备\n\n- `id:pixel_5`, `id:pixel_fold`, `id:pixel_tablet`\n- `id:wearos_small_round`, `id:wearos_large_round`\n\n### 自定义规格\n\n```kotlin\n@Preview(device = \"spec:width=411dp,height=891dp,dpi=420\")\n@Preview(device = \"spec:width=1280dp,height=800dp,orientation=landscape\")\n```\n\n## 项目约定\n\n1. **Preview 函数命名**: `XxxPreview` 或 `PreviewXxx`\n2. **使用 AppTheme**: 始终用 `AppTheme { }` 包裹预览内容\n3. **私有函数**: Preview 函数应为 `private`\n4. **Mock 数据**: 使用假数据填充预览，不依赖 ViewModel\n5. **放置位置**: 在同一文件中，放在被预览组件下方\n\n## 工作流程\n\n1. 找到需要预览的 Composable 函数\n2. 分析其参数，确定需要的 mock 数据\n3. 在函数下方创建 Preview 函数\n4. 用 `NeoDBYouTheme` 包裹\n5. 根据需要添加多个 `@Preview` 变体（亮/暗主题、不同尺寸等）,大多数情况下Preview不需要参数。\n\n## 示例\n\n### 简单组件预览\n\n```kotlin\n@Composable\nfun Greeting(name: String, modifier: Modifier = Modifier) {\n    Text(text = \"Hello $name!\", modifier = modifier)\n}\n\n@Preview(showBackground = true)\n@Composable\nprivate fun GreetingPreview() {\n    AppTheme {\n        Greeting(\"Android\")\n    }\n}\n```\n\n### 状态变体预览\n\n```kotlin\n@Preview(name = \"Empty\")\n@Preview(name = \"Loading\")\n@Preview(name = \"Content\")\n@Composable\nprivate fun MyScreenPreview() {\n    AppTheme {\n        // 根据需要展示不同状态\n    }\n}\n```\n\n### 亮暗主题预览\n\n```kotlin\n@PreviewLightDark\n@Composable\nprivate fun CardPreview() {\n    AppTheme {\n        MyCard(title = \"Sample\", content = \"Preview content\")\n    }\n}\n```\n"},"lastSynced":"2026-03-04T13:41:56.495Z","agentAnalysis":{"suitability":{"en":"Perfect for Android Development Agents utilizing Jetpack Compose and Material 3 for native app creation.","zh":"非常适合使用 Jetpack Compose 和 Material 3 进行原生应用开发的 Android 开发代理。","ja":"Jetpack Compose と Material 3 を使用したネイティブアプリの作成に最適な Android 開発エージェントに適しています。","ko":"Jetpack Compose와 Material 3를 사용하여 네이티브 애플리케이션을 개발하는 안드로이드 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo de Android que utilizan Jetpack Compose y Material 3 para la creación de aplicaciones nativas.","fr":"Parfait pour les agents de développement Android utilisant Jetpack Compose et Material 3 pour la création d''applications natives.","de":"Perfekt für Android-Entwicklungsagenten, die Jetpack Compose und Material 3 für die Erstellung von nativen Apps verwenden.","pt":"Perfeito para Agentes de Desenvolvimento Android que utilizam Jetpack Compose e Material 3 para criação de aplicativos nativos.","ru":"Идеально подходит для агентов разработки Android, использующих Jetpack Compose и Material 3 для создания родных приложений.","ar":"مثالي للوكلاء الذين يطورون تطبيقات أندرويد باستخدام Jetpack Compose و Material 3 لإنشاء تطبيقات أصلية."},"recommendation":{"en":"Empowers agents to create interactive previews for Jetpack Compose functions, leveraging annotations like @Preview for customized preview setups, and integrating with Material 3 for enhanced UI design.","zh":"赋予代理创建交互式预览的能力，用于 Jetpack Compose 函数，利用注释如 @Preview 进行自定义预览设置，并集成 Material 3 进行增强的 UI 设计。","ja":"Jetpack Compose 関数のインタラクティブなプレビューを作成する機能をエージェントに与え、@Preview などの注釈を使用してカスタマイズされたプレビュー設定を行い、Material 3 と統合して UI デザインを強化します。","ko":"에이전트가 Jetpack Compose 함수에 대한 대화형 미리 보기를 생성할 수 있도록 하여 @Preview와 같은 주석을 사용하여 사용자 지정 미리 보기 설정을 수행하며, Material 3와 통합하여 UI 디자인을 강화합니다.","es":"Habilita a los agentes a crear vistas previas interactivas para las funciones de Jetpack Compose, aprovechando anotaciones como @Preview para configuraciones de vista previa personalizadas, e integrándose con Material 3 para un diseño de UI mejorado.","fr":"Permet aux agents de créer des aperçus interactifs pour les fonctions de Jetpack Compose, en exploitant des annotations telles que @Preview pour des configurations d''aperçu personnalisées, et en s''intégrant à Material 3 pour un design d''UI amélioré.","de":"Ermächtigt die Agenten, interaktive Vorschauen für Jetpack Compose-Funktionen zu erstellen, indem sie Annotationen wie @Preview für benutzerdefinierte Vorschau-Einrichtungen nutzen und sich in Material 3 für ein verbessertes UI-Design integrieren.","pt":"Habilita os agentes a criar pré-visualizações interativas para funções do Jetpack Compose, utilizando anotações como @Preview para configurações de pré-visualização personalizadas e integrando com Material 3 para design de UI aprimorado.","ru":"Наделяет агентов возможностью создавать интерактивные предварительные просмотры для функций Jetpack Compose, используя аннотации như @Preview для настроек предварительного просмотра, и интегрируя с Material 3 для улучшения дизайна пользовательского интерфейса.","ar":"يمنح الوكلاء القدرة على إنشاء معاينة تفاعلية للوظائف التي تقدمها Jetpack Compose، باستخدام التعليقات مثل @Preview لإعدادات المعاينة المخصصة، وتكاملها مع Material 3 لتصميم واجهة المستخدم المحسّن."},"useCases":{"en":["Generating previews for dark mode and light mode themes","Debugging UI components with interactive previews","Creating customized preview groups for organized development"],"zh":["为暗黑模式和浅色模式主题生成预览","使用交互式预览调试 UI 组件","创建自定义预览组以进行有序开发"],"ja":["ダークモードとライトモードのテーマのプレビューを生成する","インタラクティブなプレビューを使用して UI コンポーネントをデバッグする","開発を整理するためにカスタマイズされたプレビュー グループを作成する"],"ko":["다크 모드 및 라이트 모드 테마를 위한 미리 보기 생성","대화형 미리 보기를 사용하여 UI 구성 요소를 디버깅하는 것","개발을 조직화하기 위해 사용자 지정 미리 보기 그룹을 생성"],"es":["Generar vistas previas para temas de modo oscuro y modo claro","Depurar componentes de UI con vistas previas interactivas","Crear grupos de vistas previas personalizadas para un desarrollo organizado"],"fr":["Générer des aperçus pour les thèmes de mode sombre et de mode clair","Déboguer les composants d''UI avec des aperçus interactifs","Créer des groupes d''aperçus personnalisés pour un développement organisé"],"de":["Vorschauen für dunkles und helles Modethema generieren","UI-Komponenten mit interaktiven Vorschauen debuggen","Benutzerdefinierte Vorschau-Gruppen für eine organisierte Entwicklung erstellen"],"pt":["Gerar pré-visualizações para temas de modo escuro e modo claro","Depurar componentes de UI com pré-visualizações interativas","Criar grupos de pré-visualização personalizados para desenvolvimento organizado"],"ru":["Генерировать предварительные просмотры для тем темного и светлого режима","Отлаживать компоненты пользовательского интерфейса с помощью интерактивных предварительных просмотров","Создавать настраиваемые группы предварительного просмотра для организованного развития"],"ar":["إنشاء معاينة لمواضيع الوضع الداكن والوضع الفاتح","تصحيح أخطاء مكونات واجهة المستخدم باستخدام معاينة تفاعلية","إنشاء مجموعات معاينة مخصصة لتطوير منظم"]},"limitations":{"en":["Requires Android development environment","Jetpack Compose and Material 3 compatibility necessary"],"zh":["需要 Android 开发环境","Jetpack Compose 和 Material 3 兼容性必要"],"ja":["Android 開発環境が必要","Jetpack Compose と Material 3 の互換性が必要"],"ko":["Android 개발 환경이 필요","Jetpack Compose 및 Material 3 호환성이 필요"],"es":["Requiere un entorno de desarrollo de Android","Compatibilidad con Jetpack Compose y Material 3 necesaria"],"fr":["Nécessite un environnement de développement Android","Compatibilité avec Jetpack Compose et Material 3 nécessaire"],"de":["Benötigt eine Android-Entwicklungsumgebung","Kompatibilität mit Jetpack Compose und Material 3 erforderlich"],"pt":["Requer ambiente de desenvolvimento Android","Compatibilidade com Jetpack Compose e Material 3 necessária"],"ru":["Требуется среда разработки Android","Необходимо совместимость с Jetpack Compose и Material 3"],"ar":["يتطلب بيئة تطوير أندرويد","التوافق مع Jetpack Compose و Material 3 ضروري"]},"version":3},"contentHash":"1a2abd151c0721e7ccc83065e200e6ae2113d986d9247e626a4a0dd57c69091a","qualityScore":25}');
