INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('heddxh/NeoDB-You/compose-preview', 'compose-preview', 'heddxh', 'NeoDB-You', 'community', 'compose-preview heddxh NeoDB-You community Compose Preview是一款基于Jetpack Compose和Material 3的NeoDB原生Android应用，提供强大的UI组件和Material设计 Compose Previewは、Jetpack ComposeとMaterial 3を使用して開発されたNeoDBのネイティブAndroidアプリです。強力なUIコンポーネントとMaterialデザインを提供します Compose Preview는 Jetpack Compose와 Material 3로 개발된 NeoDB의 네이티브 안드로이드 앱으로, 강력한 UI 컴포넌트와 Material 디자인을 제공합니다 Compose Preview es una aplicación Android nativa para NeoDB, desarrollada con Jetpack Compose y Material 3 Compose Preview est une application Android native pour NeoDB, développée avec Jetpack Compose et Material 3 Compose Preview ist eine native Android-App für NeoDB, entwickelt mit Jetpack Compose und Material 3 O Compose Preview é um aplicativo Android nativo para NeoDB, desenvolvido com Jetpack Compose e Material 3/You. Ele oferece uma pré-visualização de composição para desenvolvedores. Compose Preview - родное Android-приложение для NeoDB, созданное с Jetpack Compose и Material 3/You. Оно предоставляет предварительный просмотр композиции для разработчиков. Compose Preview هو تطبيق أندرويد أصلي ل NeoDB، تم إنشاؤه باستخدام Jetpack Compose و Material 3/You. يقدم معاينة تركيبية للمطورين. A native Android app for NeoDB, crafted with Jetpack Compose and Material 3/You. 如何使用Compose Preview 什么是Jetpack Compose NeoDB应用开发 Compose Preview安装 Material 3设计教程 AI工具比较 Compose Preview vs 其他工具 A native Android app for NeoDB, crafted with Jetpack Compose and Material 3/You.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('WHITS-ISLAND/inspirehub-mobile/retro', 'community', 'WHITS-ISLAND', 'inspirehub-mobile', 'WHITS-ISLAND/inspirehub-mobile', 'retro', 0, 0, 25, '2026-03-04T13:07:01.719Z', '2026-03-04T13:50:28.273Z', '8319a10e00954c03febe742344a78c0fb8df3ccec17130ec12463f5888e80985', '{"id":"WHITS-ISLAND/inspirehub-mobile/retro","name":"retro","description":{"zh":"Retro AI智能工具是一个用于构建原生应用的idea共享平台，用于开发者快速构建和分享应用","ja":"Retro AIエージェントは、ネイティブアプリのアイデア共有プラットフォームを構築するためのツールです","ko":"Retro AI 에이전트는 네이티브 앱의 아이디어 공유 플랫폼을 구축하기 위한 도구입니다","es":"Retro es una plataforma de intercambio de ideas para aplicaciones nativas, diseñada para potenciar la colaboración y la innovación","fr":"Retro est une plateforme d''échange d''idées pour applications natives, conçue pour stimuler la collaboration et l''innovation","de":"Retro ist eine Ideenplattform für native Apps, entwickelt um die Zusammenarbeit und Innovation zu fördern","pt":"O Retro é uma plataforma de compartilhamento de ideias para aplicativos nativos, permitindo a colaboração e inovação","ru":"Retro - это платформа для обмена идеями в родных приложениях, позволяющая сотрудничать и инновировать","ar":"ريترو هي منصة لمشاركة الأفكار في التطبيقات الأصلية، مما يسمح بالتعاون والابتكار","en":"アイデア共有プラットフォームアプリのネイティブアプリ用のリポジトリ"},"seo":{"title":{"zh":"Retro AI智能工具","ja":"Retro AIエージェント","ko":"Retro AI 에이전트","es":"Herramientas de AI: Retro, plataforma de idea para aplica...","fr":"Outils d''IA : Retro, plateforme d''idée pour applications ...","de":"KI-Tools: Retro, Ideenplattform für native Apps","pt":"Ferramentas de IA: Retro - Plataforma de Compartilhamento...","ru":"ИИ Агенты: Retro - Приложение для Обмена Идеями","ar":"أدوات الذكاء الاصطناعي: ريترو - منصة لمشاركة الأفكار","en":"retro"},"description":{"zh":"Retro AI智能工具是一个用于构建原生应用的idea共享平台，用于开发者快速构建和分享应用","ja":"Retro AIエージェントは、ネイティブアプリのアイデア共有プラットフォームを構築するためのツールです","ko":"Retro AI 에이전트는 네이티브 앱의 아이디어 공유 플랫폼을 구축하기 위한 도구입니다","es":"Retro es una plataforma de intercambio de ideas para aplicaciones nativas, diseñada para potenciar la colaboración y la innovación","fr":"Retro est une plateforme d''échange d''idées pour applications natives, conçue pour stimuler la collaboration et l''innovation","de":"Retro ist eine Ideenplattform für native Apps, entwickelt um die Zusammenarbeit und Innovation zu fördern","pt":"O Retro é uma plataforma de compartilhamento de ideias para aplicativos nativos, permitindo a colaboração e inovação","ru":"Retro - это платформа для обмена идеями в родных приложениях, позволяющая сотрудничать и инновировать","ar":"ريترو هي منصة لمشاركة الأفكار في التطبيقات الأصلية، مما يسمح بالتعاون والابتكار","en":"アイデア共有プラットフォームアプリのネイティブアプリ用のリポジトリ"},"definition":{"en":"アイデア共有プラットフォームアプリのネイティブアプリ用のリポジトリ"},"features":{"zh":["原生应用构建","idea共享平台","快速开发","AI智能工具"],"ja":["ネイティブアプリの構築","アイデア共有プラットフォーム","迅速な開発","AIエージェント"],"ko":["네이티브 앱 구축","아이디어 공유 플랫폼","迅速한 개발","AI 에이전트"],"es":["Plataforma de intercambio de ideas para aplicaciones nativas","Funcionalidades de colaboración y innovación","Diseño intuitivo y fácil de usar","Integración con herramientas de desarrollo populares","Soporte para múltiples plataformas"],"fr":["Plateforme d''échange d''idées pour applications natives","Fonctionnalités de collaboration et d''innovation","Conception intuitive et facile à utiliser","Intégration avec des outils de développement populaires","Prise en charge de plusieurs plateformes"],"de":["Ideenplattform für native Apps","Funktionen für Zusammenarbeit und Innovation","Intuitives und benutzerfreundliches Design","Integration mit beliebten Entwicklungstools","Unterstützung für mehrere Plattformen"],"pt":["Plataforma de compartilhamento de ideias","Aplicativos nativos para colaboração","Ferramenta de IA para inovação","Integração com React, Python e Node.js","CLI para facilitar o uso","Agent para automação de tarefas"],"ru":["Платформа для обмена идеями","Родные приложения для сотрудничества","ИИ инструмент для инноваций","Интеграция с React, Python и Node.js","CLI для упрощения использования","Агент для автоматизации задач"],"ar":["منصة لمشاركة الأفكار","تطبيقات أصلية للتعاون","أداة ذكاء اصطناعي للابتكار","دمج مع React، Python و Node.js","CLI لتسهيل الاستخدام","وكيل لتحسين المهام"]},"keywords":{"zh":["Retro AI智能工具","原生应用构建","idea共享平台","如何使用Retro AI","Retro AI教程","Retro AI替代品"],"ja":["Retro AIエージェント","ネイティブアプリの構築","アイデア共有プラットフォーム","Retro AIの使い方","Retro AIのチュートリアル","Retro AIの代替"],"ko":["Retro AI 에이전트","네이티브 앱 구축","아이디어 공유 플랫폼","Retro AI 사용법","Retro AI 튜토리얼","Retro AI 대안"],"es":["herramientas de AI","plataforma de intercambio de ideas","aplicaciones nativas","colaboración y innovación","cómo usar Retro","Retro vs otras herramientas de AI","instalación de Retro","guía de configuración de Retro"],"fr":["outils d''IA","plateforme d''échange d''idées","applications natives","collaboration et innovation","comment utiliser Retro","Retro vs d''autres outils d''IA","installation de Retro","guide de configuration de Retro"],"de":["KI-Tools","Ideenplattform","native Apps","Zusammenarbeit und Innovation","wie man Retro verwendet","Retro im Vergleich zu anderen KI-Tools","Installation von Retro","Konfigurationsanleitung für Retro"],"pt":["como usar o Retro","o que é Retro","Retro vs outras ferramentas","instalar Retro","guia de configuração do Retro","ferramentas de IA para desenvolvedores","plataformas de compartilhamento de ideias","aplicativos nativos para colaboração","Retro alternative"],"ru":["как использовать Retro","что такое Retro","Retro vs другие инструменты","установить Retro","руководство по настройке Retro","ИИ инструменты для разработчиков","платформы для обмена идеями","родные приложения для сотрудничества","Retro альтернатива"],"ar":["كيفية استخدام ريترو","ما هي ريترو","ريترو مقابل أدوات أخرى","تثبيت ريترو","دليل إعداد ريترو","أدوات الذكاء الاصطناعي للمطورين","منصات لمشاركة الأفكار","تطبيقات أصلية للتعاون","ريترو بديل"]}},"owner":"WHITS-ISLAND","repo":"inspirehub-mobile","repoPath":"WHITS-ISLAND/inspirehub-mobile","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.719Z","topics":[],"category":"community","skillMd":{"name":"retro","description":"エージェントの振り返りを実行し、スキル化候補・サブエージェント増設提案・コンテキスト肥大化チェックをレポートする","bodyPreview":"# 振り返り・効率化スキル\r\n\r\nエージェントのメモリを分析し、効率化のための提案を行う。\r\n\r\n## 処理フロー\r\n\r\n### 1. エージェントメモリ分析\r\n\r\n- `.claude/agent-memory/*/MEMORY.md` を全て読み込み\r\n- 各ファイルの行数をチェック（200行超 → コンテキスト肥大化警告）\r\n- 「Repeated Patterns」セクションから繰り返しパターンを集約\r\n\r\n### 2. スキル化候補の検出\r\n\r\n- 繰り返しパターンを分析し、スキル化で自動化できるものを提案\r\n- 既存スキル（`.claude/skills/*/SKILL.md`）と重複しないか確認\r\n\r\n### 3. サブエージェント増設の判断\r\n\r\n- 「Pain Points」セクションから、既存エージェントではカバーできない領域を検出\r\n- 新エージェント作成の提案（役割・ツール・スコープ）\r\n\r\n### 4. コンテキスト肥大化チェック\r\n\r\n- MEMORY.mdの行数 > 200行: 整理推奨\r\n- 同じ知見が複数エージェントに重複: 共有ルール化を提案","body":"# 振り返り・効率化スキル\r\n\r\nエージェントのメモリを分析し、効率化のための提案を行う。\r\n\r\n## 処理フロー\r\n\r\n### 1. エージェントメモリ分析\r\n\r\n- `.claude/agent-memory/*/MEMORY.md` を全て読み込み\r\n- 各ファイルの行数をチェック（200行超 → コンテキスト肥大化警告）\r\n- 「Repeated Patterns」セクションから繰り返しパターンを集約\r\n\r\n### 2. スキル化候補の検出\r\n\r\n- 繰り返しパターンを分析し、スキル化で自動化できるものを提案\r\n- 既存スキル（`.claude/skills/*/SKILL.md`）と重複しないか確認\r\n\r\n### 3. サブエージェント増設の判断\r\n\r\n- 「Pain Points」セクションから、既存エージェントではカバーできない領域を検出\r\n- 新エージェント作成の提案（役割・ツール・スコープ）\r\n\r\n### 4. コンテキスト肥大化チェック\r\n\r\n- MEMORY.mdの行数 > 200行: 整理推奨\r\n- 同じ知見が複数エージェントに重複: 共有ルール化を提案\r\n\r\n### 5. レポート出力\r\n\r\n## 出力フォーマット\r\n\r\n```markdown\r\n## 振り返りレポート\r\n\r\n### コンテキスト状況\r\n| エージェント | MEMORY.md行数 | ステータス |\r\n|-------------|--------------|-----------|\r\n| kotlin-dev  | 45行         | 正常      |\r\n| ios-dev     | 210行        | 要整理    |\r\n\r\n### スキル化候補\r\n- [ ] (パターン名)（(エージェント名)で(N)回以上実施）\r\n\r\n### サブエージェント増設提案\r\n- (提案またはなし)\r\n\r\n### ルール追加提案\r\n- [ ] (提案)\r\n```\r\n\r\n## エージェントメモリ規約\r\n\r\n各エージェントのMEMORY.mdに以下のセクションを維持する:\r\n\r\n- **Repeated Patterns**: 繰り返し行った作業パターン\r\n- **Pain Points**: 既存の仕組みでは解決しにくかった課題\r\n- **Lessons Learned**: 学んだ知見・ベストプラクティス\r\n"},"lastSynced":"2026-03-04T13:50:28.273Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Claude, AutoGPT, or LangChain needing efficient memory analysis and automation capabilities.","zh":"非常适合像 Claude、AutoGPT 或 LangChain 这样的 AI Agents，它们需要高效的内存分析和自动化能力。","ja":"Claude、AutoGPT、または LangChain のような AI エージェントに適しています。効率的なメモリ分析と自動化能力が必要です。","ko":"Claude, AutoGPT, 또는 LangChain 같은 AI 에이전트에게 적합합니다. 효율적인 메모리 분석과 자동화 능력이 필요합니다.","es":"Perfecto para agentes de IA como Claude, AutoGPT o LangChain que necesitan un análisis de memoria eficiente y capacidades de automatización.","fr":"Parfait pour les agents IA comme Claude, AutoGPT ou LangChain qui ont besoin d''une analyse de mémoire efficace et de capacités d''automatisation.","de":"Perfekt für KI-Agents wie Claude, AutoGPT oder LangChain, die eine effiziente Speicheranalyse und Automatisierungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de IA como Claude, AutoGPT ou LangChain que necessitam de análise de memória eficiente e capacidades de automação.","ru":"Идеально подходит для агентов ИИ, таких как Claude, AutoGPT или LangChain, требующих эффективного анализа памяти и возможностей автоматизации.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Claude، AutoGPT أو LangChain الذين يحتاجون إلى تحليل ذاكرة فعال ووسائل автомatisation."},"recommendation":{"en":"Empowers agents to analyze their memory, detect repeated patterns, and propose automation opportunities using MEMORY.md files, while also identifying areas for sub-agent expansion and context optimization, leveraging file formats like .md and directories like .claude/agent-memory.","zh":"赋予代理分析其内存、检测重复模式并提出自动化机会的能力，使用 MEMORY.md 文件，同时也能确定子代理扩展和上下文优化的区域，利用文件格式如 .md 和目录如 .claude/agent-memory。","ja":"エージェントがメモリを分析し、繰り返しのパターンを検出して自動化の機会を提案する能力を与え、MEMORY.md ファイルを使用しながら、子エージェントの拡張とコンテキスト最適化のための領域を特定する。ファイル形式 .md やディレクトリ .claude/agent-memory を利用する。","ko":"에이전트가 메모리를 분석하고, 반복되는 패턴을 발견하여 자동화 기회를 제안할 수 있는 능력을 부여합니다. MEMORY.md 파일을 사용하며, 하위 에이전트 확장 및 컨텍스트 최적화 영역을 식별합니다. 파일 형식 .md 및 디렉토리 .claude/agent-memory를 활용합니다.","es":"Habilita a los agentes a analizar su memoria, detectar patrones repetidos y proponer oportunidades de automatización utilizando archivos MEMORY.md, al mismo tiempo que identifica áreas para la expansión de subagentes y la optimización del contexto, aprovechando formatos de archivo como .md y directorios como .claude/agent-memory.","fr":"Permet aux agents d''analyser leur mémoire, de détecter des modèles répétitifs et de proposer des opportunités d''automatisation en utilisant des fichiers MEMORY.md, tout en identifiant des domaines pour l''expansion de sous-agents et l''optimisation du contexte, en exploitant des formats de fichiers comme .md et des répertoires comme .claude/agent-memory.","de":"Ermöglicht es Agents, ihre Speicher zu analysieren, wiederholte Muster zu erkennen und Automatisierungsmöglichkeiten unter Verwendung von MEMORY.md-Dateien vorzuschlagen, während gleichzeitig Bereiche für die Erweiterung von Sub-Agents und die Kontextoptimierung identifiziert werden, indem Dateiformate wie .md und Verzeichnisse wie .claude/agent-memory genutzt werden.","pt":"Habilita os agentes a analisar sua memória, detectar padrões repetidos e propor oportunidades de automação usando arquivos MEMORY.md, além de identificar áreas para expansão de sub-agentes e otimização de contexto, utilizando formatos de arquivo como .md e diretórios como .claude/agent-memory.","ru":"Позволяет агентам анализировать свою память, обнаруживать повторяющиеся закономерности и предлагать возможности автоматизации с помощью файлов MEMORY.md, а также определять области для расширения субагентов и оптимизации контекста, используя форматы файлов, такие как .md, и директории, такие как .claude/agent-memory.","ar":"تمكّن الوكيل من تحليل ذاكرته، وكشف الأنماط المتكررة، واقتراح فرص للتutomatisation باستخدام ملفات MEMORY.md، بالإضافة إلى تحديد المجالات لتوسيع الوكيل الفرعي وتحسين السياق، مستخدماً تنسيقات الملفات مثل .md والملفات الموجودة في الدلائل مثل .claude/agent-memory."},"useCases":{"en":["Automating routine tasks by identifying repeated patterns in agent memory","Optimizing agent performance by detecting context bloat in MEMORY.md files","Proposing new sub-agents to cover uncovered areas based on Pain Points analysis"],"zh":["通过在代理内存中识别重复模式来自动执行常规任务","通过在 MEMORY.md 文件中检测上下文膨胀来优化代理性能","根据 Pain Points 分析提出新的子代理以覆盖未覆盖的区域"],"ja":["エージェントのメモリ内で繰り返しのパターンを検出してルーチンタスクを自動化する","MEMORY.md ファイル内でコンテキストブロートを検出してエージェントのパフォーマンスを最適化する","Pain Points 分析に基づいて未カバーの領域をカバーするための新しい子エージェントを提案する"],"ko":["에이전트 메모리에서 반복되는 패턴을 식별하여 루틴 작업을 자동화합니다","MEMORY.md 파일에서 컨텍스트 블로트를 감지하여 에이전트 성능을 최적화합니다","페인 포인트 분석을 기반으로 커버되지 않은 영역을 커버하는 새로운 하위 에이전트를 제안합니다"],"es":["Automatizar tareas rutinarias identificando patrones repetidos en la memoria del agente","Optimizar el rendimiento del agente detectando la inflación del contexto en archivos MEMORY.md","Proponer nuevos subagentes para cubrir áreas no cubiertas en función del análisis de Puntos de Dolor"],"fr":["Automatiser des tâches routinières en identifiant des modèles répétitifs dans la mémoire de l''agent","Optimiser les performances de l''agent en détectant l''inflation du contexte dans les fichiers MEMORY.md","Proposer de nouveaux sous-agents pour couvrir des domaines non couverts sur la base de l''analyse des Points de Douleur"],"de":["Routineaufgaben automatisieren, indem wiederholte Muster im Speicher des Agents erkannt werden","Die Leistung des Agents optimieren, indem Kontextaufblähung in MEMORY.md-Dateien erkannt wird","Vorschlagen neuer Sub-Agents, um nicht abgedeckte Bereiche auf der Grundlage der Schmerzpunkte-Analyse abzudecken"],"pt":["Automatizar tarefas rotineiras identificando padrões repetidos na memória do agente","Otimizar o desempenho do agente detectando inflação de contexto em arquivos MEMORY.md","Propor novos sub-agentes para cobrir áreas não abordadas com base na análise de Pontos de Dor"],"ru":["Автоматизировать рутинные задачи, выявляя повторяющиеся закономерности в памяти агента","Оптимизировать производительность агента, обнаруживая контекстный бloat в файлах MEMORY.md","Предлагать новых субагентов для покрытия непокрытых областей на основе анализа Болевых точек"],"ar":["التautomatisation المهام الروتينية عن طريق كشف الأنماط المتكررة في ذاكرة الوكيل","تحسين أداء الوكيل عن طريق كشف التضخم السياقي في ملفات MEMORY.md","اقتراح وكلاء فرعيين جدد لتغطية المجالات غير المغطاة استناداً إلى تحليل نقاط الألم"]},"limitations":{"en":["Requires access to .claude/agent-memory and .claude/skills directories","Limited to agents with MEMORY.md files","May require manual review of proposed automation opportunities"],"zh":["需要访问 .claude/agent-memory 和 .claude/skills 目录","仅限具有 MEMORY.md 文件的代理","可能需要手动审查提出的自动化机会"],"ja":[".claude/agent-memory と .claude/skills ディレクトリへのアクセスが必要","MEMORY.md ファイルを持つエージェントに限定される","提案された自動化の機会の手動レビューが必要になる場合がある"],"ko":[".claude/agent-memory 및 .claude/skills 디렉토리에 액세스해야 함","MEMORY.md 파일을 가진 에이전트로 제한됨","제안된 자동화 기회의 수동 검토가 필요할 수 있음"],"es":["Requiere acceso a los directorios .claude/agent-memory y .claude/skills","Limitado a agentes con archivos MEMORY.md","Puede requerir una revisión manual de las oportunidades de automatización propuestas"],"fr":["Nécessite l''accès aux répertoires .claude/agent-memory et .claude/skills","Limité aux agents disposant de fichiers MEMORY.md","Peut nécessiter une révision manuelle des opportunités d''automatisation proposées"],"de":["Erfordert Zugriff auf die Verzeichnisse .claude/agent-memory und .claude/skills","Begrenzt auf Agents mit MEMORY.md-Dateien","Kann eine manuelle Überprüfung der vorgeschlagenen Automatisierungsmöglichkeiten erfordern"],"pt":["Exige acesso aos diretórios .claude/agent-memory e .claude/skills","Limitado a agentes com arquivos MEMORY.md","Pode exigir revisão manual das oportunidades de automação propostas"],"ru":["Требует доступа к директориям .claude/agent-memory и .claude/skills","Ограничен агентами с файлами MEMORY.md","Может потребовать ручного обзора предложенных возможностей автоматизации"],"ar":["يتطلب الوصول إلى الدلائل .claude/agent-memory و .claude/skills","محدود بالوكلاء الذين لديهم ملفات MEMORY.md","يمكن أن يتطلب مراجعة يدوية للفرص التautomatisation المقترحة"]},"version":3},"contentHash":"8319a10e00954c03febe742344a78c0fb8df3ccec17130ec12463f5888e80985","qualityScore":25}');
