INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('WHITS-ISLAND/inspirehub-mobile/retro', 'retro', 'WHITS-ISLAND', 'inspirehub-mobile', 'community', 'retro WHITS-ISLAND inspirehub-mobile community Retro AI智能工具是一个用于构建原生应用的idea共享平台，用于开发者快速构建和分享应用 Retro AIエージェントは、ネイティブアプリのアイデア共有プラットフォームを構築するためのツールです Retro AI 에이전트는 네이티브 앱의 아이디어 공유 플랫폼을 구축하기 위한 도구입니다 Retro es una plataforma de intercambio de ideas para aplicaciones nativas, diseñada para potenciar la colaboración y la innovación Retro est une plateforme d''échange d''idées pour applications natives, conçue pour stimuler la collaboration et l''innovation Retro ist eine Ideenplattform für native Apps, entwickelt um die Zusammenarbeit und Innovation zu fördern O Retro é uma plataforma de compartilhamento de ideias para aplicativos nativos, permitindo a colaboração e inovação Retro - это платформа для обмена идеями в родных приложениях, позволяющая сотрудничать и инновировать ريترو هي منصة لمشاركة الأفكار في التطبيقات الأصلية، مما يسمح بالتعاون والابتكار アイデア共有プラットフォームアプリのネイティブアプリ用のリポジトリ Retro AI智能工具 原生应用构建 idea共享平台 如何使用Retro AI Retro AI教程 Retro AI替代品 アイデア共有プラットフォームアプリのネイティブアプリ用のリポジトリ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('z3z1ma/vibe-pipe/loom-workspace', 'community', 'z3z1ma', 'vibe-pipe', 'z3z1ma/vibe-pipe', 'loom-workspace', 0, 0, 25, '2026-03-04T13:07:01.723Z', '2026-03-04T13:53:34.020Z', '559b475f8a9bb98c8b4ae3a9530ad6609289250a78e681c77652aceedeffb09f', '{"id":"z3z1ma/vibe-pipe/loom-workspace","name":"loom-workspace","description":{"zh":"Loom Workspace是一个用于管理多个终端用户界面的测试工具，用于您的最爱TUI","ja":"Loom Workspaceは、好きなTUIのホルドを管理するためのツールのテストベッドです","ko":"Loom Workspace는 좋아하는 TUI의 호드를 관리하기 위한 도구의 테스트베드입니다","es":"Loom Workspace es una herramienta para gestionar múltiples interfaces de usuario de línea de comandos","fr":"Loom Workspace est un outil pour gérer plusieurs interfaces utilisateur en ligne de commande","de":"Loom Workspace ist ein Tool zur Verwaltung mehrerer Kommandozeilen-Oberflächen","pt":"O Loom Workspace é uma ferramenta para gerenciar TUIs, permitindo que os desenvolvedores trabalhem de forma eficiente","ru":"Loom Workspace - это инструмент для управления TUI, позволяющий разработчикам работать эффективно","ar":"Loom Workspace هو أداة لإدارة واجهات المستخدم التفاعلية، تمكن المطورين من العمل بفعالية","en":"Just a testbed for loom, a tool for managing a horde of your favorite TUIs"},"seo":{"title":{"zh":"AI工具：Loom Workspace终端用户界面管理","ja":"AIエージェント：Loom Workspace TUI管理ツール","ko":"AI 에이전트: Loom Workspace 터미널 사용자 인터페이스 관리","es":"Herramientas de Agente de IA: Loom Workspace","fr":"Outils d''Agent IA: Loom Workspace","de":"KI-Tools: Loom Workspace","pt":"Ferramentas de IA: Loom Workspace","ru":"ИИ Агенты: Loom Workspace","ar":"أدوات الذكاء الاصطناعي: Loom Workspace","en":"loom-workspace"},"description":{"zh":"Loom Workspace是一个用于管理多个终端用户界面的测试工具，用于您的最爱TUI","ja":"Loom Workspaceは、好きなTUIのホルドを管理するためのツールのテストベッドです","ko":"Loom Workspace는 좋아하는 TUI의 호드를 관리하기 위한 도구의 테스트베드입니다","es":"Loom Workspace es una herramienta para gestionar múltiples interfaces de usuario de línea de comandos","fr":"Loom Workspace est un outil pour gérer plusieurs interfaces utilisateur en ligne de commande","de":"Loom Workspace ist ein Tool zur Verwaltung mehrerer Kommandozeilen-Oberflächen","pt":"O Loom Workspace é uma ferramenta para gerenciar TUIs, permitindo que os desenvolvedores trabalhem de forma eficiente","ru":"Loom Workspace - это инструмент для управления TUI, позволяющий разработчикам работать эффективно","ar":"Loom Workspace هو أداة لإدارة واجهات المستخدم التفاعلية، تمكن المطورين من العمل بفعالية","en":"Just a testbed for loom, a tool for managing a horde of your favorite TUIs"},"definition":{"en":"Just a testbed for loom, a tool for managing a horde of your favorite TUIs"},"features":{"zh":["终端用户界面管理","TUI管理","AI工具集成","命令行界面","多窗口支持"],"ja":["TUI管理","AIエージェントとの統合","コマンドラインインターフェース","複数ウィンドウサポート"],"ko":["터미널 사용자 인터페이스 관리","TUI 관리","AI 에이전트 통합","명령줄 인터페이스","다중 창 지원"],"es":["Gestión de múltiples interfaces de usuario","Soporte para herramientas de línea de comandos","Personalización de la interfaz de usuario","Integración con otras herramientas de desarrollo","Gestión de proyectos y tareas"],"fr":["Gestion de plusieurs interfaces utilisateur","Prise en charge des outils de ligne de commande","Personnalisation de l''interface utilisateur","Intégration avec d''autres outils de développement","Gestion de projets et de tâches"],"de":["Verwaltung mehrerer Benutzeroberflächen","Unterstützung für Kommandozeilen-Tools","Anpassung der Benutzeroberfläche","Integration mit anderen Entwicklungstools","Verwaltung von Projekten und Aufgaben"],"pt":["Gerenciamento de TUIs","Integração com ferramentas de desenvolvimento","Interface de usuário personalizável","Suporte a múltiplos ambientes de desenvolvimento","Fácil instalação e configuração"],"ru":["Управление TUI","Интеграция с инструментами разработки","Настраиваемый интерфейс пользователя","Поддержка нескольких сред разработки","Легкая установка и настройка"],"ar":["إدارة واجهات المستخدم التفاعلية","التكامل مع أدوات التطوير","واجهة مستخدم قابلة للتعديل","دعم بيئات متعددة للتطوير","تثبيت وتهيئة سهلة"]},"keywords":{"zh":["Loom Workspace教程","TUI管理工具","AI工具比较","Loom Workspace安装","终端用户界面设计"],"ja":["Loom Workspaceチュートリアル","TUI管理ツール","AIエージェント比較","Loom Workspaceインストール","TUIデザイン"],"ko":["Loom Workspace 튜토리얼","TUI 관리 도구","AI 에이전트 비교","Loom Workspace 설치","터미널 사용자 인터페이스 디자인"],"es":["cómo usar Loom Workspace","qué es un Agente de IA","Loom Workspace alternativa","Loom Workspace vs otros herramientas","instalación de Loom Workspace","guía de configuración de Loom Workspace","herramientas de desarrollo de software","gestión de proyectos de software"],"fr":["comment utiliser Loom Workspace","qu''est-ce qu''un Agent IA","Loom Workspace alternative","Loom Workspace vs autres outils","installation de Loom Workspace","guide de configuration de Loom Workspace","outils de développement de logiciels","gestion de projets de logiciels"],"de":["wie man Loom Workspace verwendet","was ist ein KI-Tool","Loom Workspace Alternative","Loom Workspace vs andere Tools","Installation von Loom Workspace","Einrichtungsanleitung für Loom Workspace","Software-Entwicklungstools","Projektmanagement-Software"],"pt":["ferramentas de ia","loom workspace","gerenciamento de tuis","desenvolvimento de software","ferramentas de desenvolvimento","como usar loom workspace","alternativas ao loom workspace","loom workspace vs outras ferramentas"],"ru":["ии агенты","loom workspace","управление tuis","разработка программного обеспечения","инструменты разработки","как использовать loom workspace","альтернативы loom workspace","loom workspace vs другие инструменты"],"ar":["أدوات الذكاء الاصطناعي","loom workspace","إدارة واجهات المستخدم التفاعلية","تطوير البرمجيات","أدوات التطوير","كيفية استخدام loom workspace","بديلات ل loom workspace","loom workspace مقابل أدوات أخرى"]}},"owner":"z3z1ma","repo":"vibe-pipe","repoPath":"z3z1ma/vibe-pipe","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.723Z","topics":[],"category":"community","skillMd":{"name":"loom-workspace","description":"Use loom workspace to create/manage worktrees for isolated execution of tickets.","version":"1","tags":"git,workflow","bodyPreview":"<!-- BEGIN:compound:skill-managed -->\n## Worktree basics (repo model)\n\nEnsure a worktree exists for a branch:\n\n- `compound_workspace(argv=[\"repo\", \"worktree\", \"add\", \"<branch>\"])`\n\nList worktrees:\n\n- `compound_workspace(argv=[\"repo\", \"worktree\", \"ls\"])`\n\nRemove a worktree:\n\n- `compound_workspace(argv=[\"repo\", \"worktree\", \"rm\", \"<branch>\"])`\n\nRepo status:\n\n- `compound_workspace(argv=[\"repo\", \"status\"])`\n\n## Branch naming\n\nRecommended:\n\n- `ticket-<ticket-id>-<short-slug>`\n\nExample:\n\n- `ticket-42-s","body":"<!-- BEGIN:compound:skill-managed -->\n## Worktree basics (repo model)\n\nEnsure a worktree exists for a branch:\n\n- `compound_workspace(argv=[\"repo\", \"worktree\", \"add\", \"<branch>\"])`\n\nList worktrees:\n\n- `compound_workspace(argv=[\"repo\", \"worktree\", \"ls\"])`\n\nRemove a worktree:\n\n- `compound_workspace(argv=[\"repo\", \"worktree\", \"rm\", \"<branch>\"])`\n\nRepo status:\n\n- `compound_workspace(argv=[\"repo\", \"status\"])`\n\n## Branch naming\n\nRecommended:\n\n- `ticket-<ticket-id>-<short-slug>`\n\nExample:\n\n- `ticket-42-streaming-chunking`\n\n## Practical note\n\nOpenCode runs inside *one* working directory. Typically, this is the main branch worktree.\n`loom workspace` creates the worktree path (usually under `.loom-repo/worktrees/<branch>`).\nDo the code changes in that worktree.\n<!-- END:compound:skill-managed -->\n\n## Manual notes\n\n_This section is preserved when the skill is updated. Put human notes, caveats, and exceptions here._\n"},"lastSynced":"2026-03-04T13:53:34.020Z","agentAnalysis":{"suitability":{"en":"Ideal for Git-based AI Agents requiring efficient repository management and worktree operations","zh":"适用于需要高效仓库管理和工作树操作的基于Git的AI代理","ja":"GitベースのAIエージェントが効率的なリポジトリ管理とワークツリー操作を必要とする場合に最適","ko":"효율적인 저장소 관리 및 워크트리 작업이 필요한 Git 기반 AI 에이전트에 적합","es":"Ideal para agentes de IA basados en Git que requieren un manejo de repositorio eficiente y operaciones de worktree","fr":"Idéal pour les agents d''IA basés sur Git nécessitant une gestion de référentiel efficiente et des opérations de worktree","de":"Ideal für Git-basierte KI-Agents, die eine effiziente Repository-Verwaltung und Worktree-Operationen erfordern","pt":"Ideal para Agentes de IA baseados em Git que exigem gerenciamento de repositório eficiente e operações de worktree","ru":"Идеально для агентов ИИ, основанных на Git, требующих эффективного управления репозиторием и операций worktree","ar":"مثالي للوكلاء الذكية القائمة على Git التي تتطلب إدارة مستودع فعالة وتشغيلات شجرة العمل"},"recommendation":{"en":"Empowers agents to manage a horde of TUIs with loom, enabling seamless worktree addition, listing, and removal, as well as repository status checks, all while adhering to a standardized branch naming convention like ''ticket-<ticket-id>-<short-slug>''","zh":"赋予代理管理大量TUI的能力，使用loom实现无缝的工作树添加、列出和删除，以及仓库状态检查，同时遵循标准化的分支命名约定，如''ticket-<ticket-id>-<short-slug>''","ja":"エージェントがloomを使用して大量のTUIを管理する能力を付与し、ワークツリーの追加、リスト、削除、およびリポジトリ状態の確認をシームレスに行い、''ticket-<ticket-id>-<short-slug>''のような標準化されたブランチ命名規則に従う","ko":"에이전트가 loom을 사용하여大量의 TUI를 관리할 수 있는 기능을 제공하여 워크트리 추가, 목록, 삭제 및 저장소 상태 확인을 원활하게 수행하며 ''ticket-<ticket-id>-<short-slug>''과 같은 표준화된 분기 이름 규칙을 따름","es":"Habilita a los agentes a gestionar un enjambre de TUIs con loom, permitiendo una adición, lista y eliminación de worktree sin problemas, así como comprobaciones de estado de repositorio, todo mientras se adhiere a una convención de nombre de rama estandarizada como ''ticket-<ticket-id>-<short-slug>''","fr":"Permet aux agents de gérer un essaim de TUIs avec loom, permettant ainsi une ajout, une liste et une suppression de worktree sans problème, ainsi que des vérifications d''état de référentiel, tout en respectant une convention de nom de branche standardisée comme ''ticket-<ticket-id>-<short-slug>''","de":"Ermöglicht es Agents, einen Schwarm von TUIs mit loom zu verwalten, wodurch eine nahtlose Hinzufügung, Auflistung und Entfernung von Worktrees sowie Repository-Statusprüfungen ermöglicht werden, und zwar unter Einhaltung einer standardisierten Branch-Namenskonvention wie ''ticket-<ticket-id>-<short-slug>''","pt":"Habilita os agentes a gerenciar uma horda de TUIs com loom, permitindo adição, listagem e remoção de worktree sem problemas, bem como verificações de status do repositório, tudo enquanto adere a uma convenção de nomenclatura de branch padronizada como ''ticket-<ticket-id>-<short-slug>''","ru":"Наделяет агентов возможностью управлять ордой TUI с помощью loom, обеспечивая бесперебойное добавление, перечисление и удаление worktree, а также проверку состояния репозитория, все это при соблюдении стандартизированной конвенции именования веток, например ''ticket-<ticket-id>-<short-slug>''","ar":"تمكّن الوكلاء من إدارة مجموعة من واجهات المستخدم النصية مع loom، مما يسمح بإضافة وترقية وازالة شجرة العمل بسلاسة، بالإضافة إلى فحص حالة المستودع، مع التزام بمعيار مسمى فرع معياري مثل ''ticket-<ticket-id>-<short-slug>''"},"useCases":{"en":["Automating worktree setup for new branches","Listing and managing existing worktrees","Removing unused worktrees to maintain repository organization"],"zh":["为新分支自动设置工作树","列出和管理现有的工作树","删除未使用的工作树以维护仓库组织"],"ja":["新しいブランチのためのワークツリーの自動設定","既存のワークツリーのリストと管理","未使用のワークツリーの削除によるリポジトリの整理"],"ko":["새로운 브랜치에 대한 워크트리 자동 설정","기존 워크트리 목록 및 관리","저장소 구성 유지하기 위한 사용하지 않는 워크트리 삭제"],"es":["Automatización de la configuración de worktree para nuevas ramas","Lista y administración de worktrees existentes","Eliminación de worktrees no utilizados para mantener la organización del repositorio"],"fr":["Automatisation de la configuration de worktree pour de nouvelles branches","Liste et gestion de worktrees existants","Suppression de worktrees inutilisés pour maintenir l''organisation du référentiel"],"de":["Automatisierung der Worktree-Konfiguration für neue Branches","Auflistung und Verwaltung bestehender Worktrees","Entfernen nicht verwendeter Worktrees zur Aufrechterhaltung der Repository-Organisation"],"pt":["Automatizar configuração de worktree para novos branches","Listar e gerenciar worktrees existentes","Remover worktrees não utilizados para manter a organização do repositório"],"ru":["Автоматизировать настройку worktree для новых веток","Перечислять и управлять существующими worktree","Удалять неиспользуемые worktree для поддержания организации репозитория"],"ar":["توفير تكوين شجرة العمل آليا لفرع جديد","استعراض وإدارة شجرات العمل الحالية","إزالة شجرات العمل غير المستخدمة للحفاظ على تنظيم المستودع"]},"limitations":{"en":["Requires Git repository setup","Limited to TUI management within loom"],"zh":["需要Git仓库设置","仅限于loom中的TUI管理"],"ja":["Gitリポジトリの設定が必要","loom内のTUI管理に限定"],"ko":["Git 저장소 설정이 필요","loom 내의 TUI 관리에限定"],"es":["Requiere configuración de repositorio Git","Limitado a la gestión de TUI dentro de loom"],"fr":["Nécessite une configuration de référentiel Git","Limité à la gestion de TUI à l''intérieur de loom"],"de":["Erfordert Git-Repository-Konfiguration","Begrenzt auf TUI-Verwaltung innerhalb von loom"],"pt":["Exige configuração do repositório Git","Limitado ao gerenciamento de TUI dentro do loom"],"ru":["Требует настройки репозитория Git","Ограничен управлением TUI внутри loom"],"ar":["يتطلب إعداد مستودع Git","محدود بإدارة واجهات المستخدم النصية داخل loom"]},"version":3},"contentHash":"559b475f8a9bb98c8b4ae3a9530ad6609289250a78e681c77652aceedeffb09f","qualityScore":25}');
