INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Umisyo/Lorepedia/codex', 'codex', 'Umisyo', 'Lorepedia', 'community', 'codex Umisyo Lorepedia community Codex是一个共享世界创作支援工具，帮助开发者提高效率和生产力 Codexはシェアード・ワールド創作支援ツールで、開発者の効率と生産性を向上させます Codex는 공유 세계 창작 지원 도구로 개발자의 효율과 생산성을 향상시킵니다 Codex es una herramienta de AI para la creación de mundos compartidos, diseñada para mejorar la colaboración y el desarrollo de proyectos Codex est un outil d''IA pour la création de mondes partagés, conçu pour améliorer la collaboration et le développement de projets Codex ist ein KI-Tool für die gemeinsame Weltgestaltung, entwickelt um die Zusammenarbeit und die Entwicklung von Projekten zu verbessern O Codex é uma ferramenta de suporte à criação de mundos compartilhados, permitindo que desenvolvedores criem experiências imersivas com tecnologias como React e Node.js Codex - это инструмент поддержки создания общих миров, позволяющий разработчикам создавать иммерсивные trải nghiệm с использованием технологий như React и Node.js Codex هو أداة دعم لإنشاء عوالم مشتركة، تمكن المطورين من إنشاء تجارب غامرة باستخدام تقنيات مثل React و Node.js シェアード・ワールド創作支援ツール 如何使用Codex 什么是共享世界创作 Codex替代品 Codex与其他工具的比较 Codex安装指南 Codex设置教程 AI工具 开发效率 生产力 シェアード・ワールド創作支援ツール');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('amyodov/pytest-claude-agent-sdk/complete-checkpoint', 'community', 'amyodov', 'pytest-claude-agent-sdk', 'amyodov/pytest-claude-agent-sdk', 'complete-checkpoint', 0, 0, 25, '2026-03-04T13:07:01.731Z', '2026-03-04T13:59:51.881Z', '373826b80b4b1b7654114a0fd84c6941a791596389a3d939046694c2c285bd08', '{"id":"amyodov/pytest-claude-agent-sdk/complete-checkpoint","name":"complete-checkpoint","description":{"zh":"complete-checkpoint技能，用于优化pytest测试，提高开发效率","ja":"complete-checkpointスキルは、pytestテストの最適化と開発効率の向上に役立ちます","ko":"complete-checkpoint 기능은 pytest 테스트 최적화 및 개발 효율성 향상을 지원합니다","es":"Complete-checkpoint permite a los desarrolladores utilizar Claude Code en pytests o probar sus propios agentes de Claude Code","fr":"Complete-checkpoint permet aux développeurs d''utiliser Claude Code dans des tests pytests ou de tester leurs propres agents Claude Code","de":"Complete-checkpoint ermöglicht es Entwicklern, Claude Code in pytests zu verwenden oder ihre eigenen Claude Code-Agents zu testen","pt":"O complete-checkpoint é uma habilidade que permite usar Claude Code em pytests, melhorando a eficiência do desenvolvimento","ru":"ИИ Агент complete-checkpoint позволяет использовать Claude Code в pytests,提高 эффективность разработки","ar":"الوظيفة complete-checkpoint تسمح باستخدام Claude Code في pytests، مما ي提高 كفاءة التطوير","en":"Use Claude Code in your pytests, or pytest your own Claude Code agents — or both"},"seo":{"title":{"zh":"AI智能工具：complete-checkpoint","ja":"AIエージェント：complete-checkpoint","ko":"AI 에이전트: complete-checkpoint","es":"Herramientas de AI: complete-checkpoint para Pytests","fr":"Outils d''IA : complete-checkpoint pour Pytests","de":"KI-Tools: complete-checkpoint für Pytests","pt":"Ferramentas de AI: complete-checkpoint com Claude Code","ru":"ИИ Агенты: complete-checkpoint с Claude Code","ar":"أدوات الذكاء الاصطناعي: complete-checkpoint مع Claude Code","en":"complete-checkpoint"},"description":{"zh":"complete-checkpoint技能，用于优化pytest测试，提高开发效率","ja":"complete-checkpointスキルは、pytestテストの最適化と開発効率の向上に役立ちます","ko":"complete-checkpoint 기능은 pytest 테스트 최적화 및 개발 효율성 향상을 지원합니다","es":"Complete-checkpoint permite a los desarrolladores utilizar Claude Code en pytests o probar sus propios agentes de Claude Code","fr":"Complete-checkpoint permet aux développeurs d''utiliser Claude Code dans des tests pytests ou de tester leurs propres agents Claude Code","de":"Complete-checkpoint ermöglicht es Entwicklern, Claude Code in pytests zu verwenden oder ihre eigenen Claude Code-Agents zu testen","pt":"O complete-checkpoint é uma habilidade que permite usar Claude Code em pytests, melhorando a eficiência do desenvolvimento","ru":"ИИ Агент complete-checkpoint позволяет использовать Claude Code в pytests,提高 эффективность разработки","ar":"الوظيفة complete-checkpoint تسمح باستخدام Claude Code في pytests، مما ي提高 كفاءة التطوير","en":"Use Claude Code in your pytests, or pytest your own Claude Code agents — or both"},"definition":{"en":"Use Claude Code in your pytests, or pytest your own Claude Code agents — or both"},"features":{"zh":["使用Claude Code优化pytest测试","支持pytest测试和Claude Code代理","提高开发效率和测试质量","易于集成和使用","支持多种测试场景"],"ja":["Claude Codeを使用してpytestテストを最適化","pytestテストとClaude Codeエージェントの両方をサポート","開発効率とテスト品質の向上","簡単な統合と使用","多種多様なテストシナリオのサポート"],"ko":["Claude Code로 pytest 테스트 최적화","pytest 테스트와 Claude Code 에이전트 모두 지원","개발 효율성과 테스트 품질 향상","쉬운 통합 및 사용","다양한 테스트 시나리오 지원"],"es":["Integración de Claude Code en pytests","Pruebas de agentes de Claude Code personalizados","Mejora de la eficiencia en las pruebas","Compatibilidad con pytests","Flexibilidad para desarrolladores"],"fr":["Intégration de Claude Code dans des tests pytests","Tests d''agents Claude Code personnalisés","Amélioration de l''efficacité des tests","Compatibilité avec pytests","Flexibilité pour les développeurs"],"de":["Integration von Claude Code in pytests","Tests von benutzerdefinierten Claude Code-Agents","Verbesserung der Effizienz bei Tests","Kompatibilität mit pytests","Flexibilität für Entwickler"],"pt":["Integração com Claude Code","Melhoria da eficiência do desenvolvimento","Pytest personalizável","Desenvolvimento de habilidades de AI","Suporte a desenvolvedores"],"ru":["Интеграция с Claude Code","Повышение эффективности разработки","Настройка pytests","Разработка навыков ИИ","Поддержка разработчиков"],"ar":["التكامل مع Claude Code","تحسين كفاءة التطوير","pytest قابل للتعديل","تطوير مهارات الذكاء الاصطناعي","دعم المطورين"]},"keywords":{"zh":["AI智能工具","pytest测试","Claude Code","开发效率","测试优化","如何使用Claude Code","pytestalternative","Claude Code安装"],"ja":["AIエージェント","pytestテスト","Claude Code","開発効率","テスト最適化","Claude Codeの使用方法","pytest代替","Claude Codeのセットアップガイド"],"ko":["AI 에이전트","pytest 테스트","Claude Code","개발 효율성","테스트 최적화","Claude Code 사용법","pytest 대안","Claude Code 설치 가이드"],"es":["cómo utilizar Claude Code en pytests","complete-checkpoint vs pytest","herramientas de AI para pruebas","instalación de complete-checkpoint","guía de configuración de Claude Code","alternativas a pytests","mejores prácticas para pruebas de AI","desarrollo de agentes de AI"],"fr":["comment utiliser Claude Code dans des tests pytests","complete-checkpoint vs pytest","outils d''IA pour les tests","installation de complete-checkpoint","guide de configuration de Claude Code","alternatives à pytests","meilleures pratiques pour les tests d''IA","développement d''agents d''IA"],"de":["wie man Claude Code in pytests verwendet","complete-checkpoint vs pytest","KI-Tools für Tests","Installation von complete-checkpoint","Konfigurationsanleitung für Claude Code","Alternativen zu pytests","beste Praktiken für KI-Tests","Entwicklung von KI-Agents"],"pt":["como usar complete-checkpoint","o que é complete-checkpoint","complete-checkpoint vs pytest","instalar complete-checkpoint","guia de configuração do complete-checkpoint","desenvolvimento de habilidades de AI","ferramentas de AI para desenvolvedores","complete-checkpoint alternative"],"ru":["как использовать complete-checkpoint","что такое complete-checkpoint","complete-checkpoint vs pytest","установить complete-checkpoint","руководство по настройке complete-checkpoint","разработка навыков ИИ","инструменты ИИ для разработчиков","альтернатива complete-checkpoint"],"ar":["كيفية استخدام complete-checkpoint","ما هي complete-checkpoint","complete-checkpoint vs pytest","تثبيت complete-checkpoint","دليل إعداد complete-checkpoint","تطوير مهارات الذكاء الاصطناعي","أدوات الذكاء الاصطناعي للمطورين","بديل complete-checkpoint"]}},"owner":"amyodov","repo":"pytest-claude-agent-sdk","repoPath":"amyodov/pytest-claude-agent-sdk","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.731Z","topics":[],"category":"community","skillMd":{"name":"complete-checkpoint","description":"Run after completing significant work — implementing a feature, fixing a bug, refactoring, or any substantial code changes. Proactively ensure code quality before reporting work as done.","bodyPreview":"# Complete Checkpoint\n\nAfter finishing a significant piece of work, run these checks:\n\n## 1. Lint and Format\n\n```bash\nuv run ruff check --fix && uv run ruff format\n```\n\n## 2. Run Tests\n\n```bash\nuv run pytest -v\n```\n\n## One-Liner\n\n```bash\nuv run ruff check --fix && uv run ruff format && uv run pytest -v\n```\n\n## Behavior\n\n1. Run the checks without asking permission\n2. If everything passes: briefly report success, continue with summary\n3. If anything fails: fix the issues, then re-run checks\n4. Don","body":"# Complete Checkpoint\n\nAfter finishing a significant piece of work, run these checks:\n\n## 1. Lint and Format\n\n```bash\nuv run ruff check --fix && uv run ruff format\n```\n\n## 2. Run Tests\n\n```bash\nuv run pytest -v\n```\n\n## One-Liner\n\n```bash\nuv run ruff check --fix && uv run ruff format && uv run pytest -v\n```\n\n## Behavior\n\n1. Run the checks without asking permission\n2. If everything passes: briefly report success, continue with summary\n3. If anything fails: fix the issues, then re-run checks\n4. Don''t report work as \"done\" until checks pass\n"},"lastSynced":"2026-03-04T13:59:51.881Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Development Agents needing automated code quality checks and test validation.","zh":"适用于需要自动代码质量检查和测试验证的Python开发代理。","ja":"Python開発エージェントが自動コード品質チェックとテスト検証を必要とする場合に適しています。","ko":"자동 코드 품질 검사 및 테스트 검증이 필요한 Python 개발 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollo de Python que necesitan comprobaciones automáticas de calidad de código y validación de pruebas.","fr":"Parfait pour les Agents de Développement Python ayant besoin de vérifications automatiques de qualité de code et de validation de tests.","de":"Perfekt für Python-Entwicklungsagenten, die automatisierte Code-Qualitätsprüfungen und Testvalidierungen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Python que necessitam de verificações automatizadas de qualidade de código e validação de testes.","ru":"Идеально подходит для агентов разработки Python, которым необходимы автоматические проверки качества кода и тестовая валидация.","ar":"مثالي لعمليات وكيل تطوير بايثون التي تحتاج إلى فحص جودة التعليمات البرمجية التلقائي وتحقق صحة الاختبار."},"recommendation":{"en":"Empowers agents to ensure code integrity by running ruff checks for linting and formatting, and pytest for test validation, streamlining the development process with uv-run commands.","zh":"通过运行ruff检查来进行linting和格式化，并使用pytest进行测试验证，通过uv-run命令简化开发流程，从而赋予代理确保代码完整性的能力。","ja":"ruffを使用してlintingとフォーマットを行い、pytestを使用してテスト検証を行うことで、uv-runコマンドを使用して開発プロセスを合理化し、コードの完全性を確保するエージェントの能力を提供します。","ko":"ruff를 사용하여 린팅과 포맷팅을 수행하고, pytest를 사용하여 테스트 검증을 수행하여 uv-run 명령어를 통해 개발 프로세스를 간소화함으로써 코드의 完全性을 보장하는 에이전트의 능력을 제공합니다.","es":"Permite a los agentes garantizar la integridad del código ejecutando comprobaciones ruff para el análisis de código y el formato, y pytest para la validación de pruebas, racionalizando el proceso de desarrollo con comandos uv-run.","fr":"Permet aux agents de garantir l''intégrité du code en exécutant des vérifications ruff pour le linting et le formatage, et pytest pour la validation des tests, rationalisant le processus de développement avec des commandes uv-run.","de":"Ermöglicht es den Agenten, die Code-Integrität zu gewährleisten, indem sie ruff-Prüfungen für das Linting und das Formatieren und pytest für die Testvalidierung ausführen, den Entwicklungsprozess mit uv-run-Befehlen zu rationalisieren.","pt":"Habilita os agentes a garantir a integridade do código executando verificações ruff para análise de linting e formatação, e pytest para validação de testes, otimizando o processo de desenvolvimento com comandos uv-run.","ru":"Наделяет агентов возможностью обеспечить целостность кода путем выполнения проверок ruff для линтинга и форматирования, и pytest для валидации тестов, оптимизируя процесс разработки с помощью команд uv-run.","ar":"يمنح الوكالات القدرة على ضمان سلامة التعليمات البرمجية من خلال تشغيل عمليات فحص ruff للتنسيق وتنسيق الشفرة، وpytest لتحقق صحة الاختبار، وتبسيط عملية التطوير باستخدام أوامر uv-run."},"useCases":{"en":["Automating code review with ruff and pytest","Validating Claude Code agents with pytest","Streamlining development workflows with one-liner checks"],"zh":["使用ruff和pytest进行自动代码审查","使用pytest验证Claude Code代理","使用一行命令检查简化开发工作流"],"ja":["ruffとpytestを使用した自動コードレビュー","pytestを使用したClaude Codeエージェントの検証","一行のコマンドチェックを使用した開発ワークフローの合理化"],"ko":["ruff와 pytest를 사용한 자동 코드 리뷰","pytest를 사용한 Claude Code 에이전트의 검증","원라인 명령어 체크를 사용한 개발 워크플로우의 간소화"],"es":["Automatizar la revisión de código con ruff y pytest","Validar agentes de código Claude con pytest","Racionalizar flujos de trabajo de desarrollo con comprobaciones de una sola línea"],"fr":["Automatiser la revue de code avec ruff et pytest","Valider les agents de code Claude avec pytest","Rationaliser les flux de travail de développement avec des vérifications en une seule ligne"],"de":["Automatisieren von Code-Reviews mit ruff und pytest","Validieren von Claude-Code-Agenten mit pytest","Rationalisieren von Entwicklungsworkflows mit einzeiligen Prüfungen"],"pt":["Automatizar revisão de código com ruff e pytest","Validar agentes Claude Code com pytest","Otimizar fluxos de trabalho de desenvolvimento com verificações de uma linha"],"ru":["Автоматизировать проверку кода с помощью ruff и pytest","Проверить агентов Claude Code с помощью pytest","Оптимизировать рабочие процессы разработки с помощью однострочных проверок"],"ar":["التحكم الآلي في استعراض التعليمات البرمجية مع ruff وpytest","تحقق صحة وكيلات Claude Code مع pytest","تبسيط سير عمل التطوير مع فحوصات السطر الواحد"]},"limitations":{"en":["Requires uv-run and ruff installation","Python environment required","Limited to pytest and ruff checks"],"zh":["需要uv-run和ruff安装","需要Python环境","仅限于pytest和ruff检查"],"ja":["uv-runとruffのインストールが必要","Python環境が必要","pytestとruffのチェックのみに限定"],"ko":["uv-run 및 ruff 설치가 필요","Python 환경이 필요","pytest 및 ruff 체크만으로 제한"],"es":["Requiere la instalación de uv-run y ruff","Entorno de Python requerido","Limitado a comprobaciones de pytest y ruff"],"fr":["Nécessite l''installation de uv-run et ruff","Environnement Python requis","Limité aux vérifications de pytest et ruff"],"de":["Benötigt die Installation von uv-run und ruff","Python-Umgebung erforderlich","Begrenzt auf pytest- und ruff-Prüfungen"],"pt":["Requer instalação do uv-run e ruff","Ambiente Python necessário","Limitado a verificações ruff e pytest"],"ru":["Требует установки uv-run и ruff","Требуется среда Python","Ограничен проверками ruff и pytest"],"ar":["يتطلب تثبيت uv-run و ruff","مطلوب بيئة بايثون","محدود بالفحص ruff وpytest"]},"version":3},"contentHash":"373826b80b4b1b7654114a0fd84c6941a791596389a3d939046694c2c285bd08","qualityScore":25}');
