INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('amyodov/pytest-claude-agent-sdk/complete-checkpoint', 'complete-checkpoint', 'amyodov', 'pytest-claude-agent-sdk', 'community', 'complete-checkpoint amyodov pytest-claude-agent-sdk community complete-checkpoint技能，用于优化pytest测试，提高开发效率 complete-checkpointスキルは、pytestテストの最適化と開発効率の向上に役立ちます complete-checkpoint 기능은 pytest 테스트 최적화 및 개발 효율성 향상을 지원합니다 Complete-checkpoint permite a los desarrolladores utilizar Claude Code en pytests o probar sus propios agentes de Claude Code Complete-checkpoint permet aux développeurs d''utiliser Claude Code dans des tests pytests ou de tester leurs propres agents Claude Code Complete-checkpoint ermöglicht es Entwicklern, Claude Code in pytests zu verwenden oder ihre eigenen Claude Code-Agents zu testen O complete-checkpoint é uma habilidade que permite usar Claude Code em pytests, melhorando a eficiência do desenvolvimento ИИ Агент complete-checkpoint позволяет использовать Claude Code в pytests,提高 эффективность разработки الوظيفة complete-checkpoint تسمح باستخدام Claude Code في pytests، مما ي提高 كفاءة التطوير Use Claude Code in your pytests, or pytest your own Claude Code agents — or both AI智能工具 pytest测试 Claude Code 开发效率 测试优化 如何使用Claude Code pytestalternative Claude Code安装 Use Claude Code in your pytests, or pytest your own Claude Code agents — or both');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('moonbit-community/fastcc/moonbit-lang', 'community', 'moonbit-community', 'fastcc', 'moonbit-community/fastcc', 'moonbit-lang', 0, 0, 25, '2026-03-04T13:07:01.738Z', '2026-03-04T14:03:35.720Z', '7513df6b34bcf22dfd694441fa6c59d539e200e475f97f8c6d393925fa81c536', '{"id":"moonbit-community/fastcc/moonbit-lang","name":"moonbit-lang","description":{"zh":"MoonBit 语言 AI 工具是一种速度优化的 C 编译器，用于提高开发效率","ja":"MoonBit言語 AIエージェントは、速度最適化のCコンパイラであり、開発効率を向上させるために使用","ko":"MoonBit 언어 AI 에이전트는 속도 최적화된 C 컴파일러로 개발 효율성을 향상시키기 위해 사용","es":"Moonbit-lang es un compilador C optimizado para velocidad escrito en MoonBit, ideal para desarrolladores que buscan mejorar el rendimiento de sus proyectos","fr":"Moonbit-lang est un compilateur C optimisé pour la vitesse écrit en MoonBit, idéal pour les développeurs qui cherchent à améliorer les performances de leurs projets","de":"Moonbit-lang ist ein C-Compiler optimiert für Geschwindigkeit geschrieben in MoonBit, ideal für Entwickler, die die Leistung ihrer Projekte verbessern möchten","pt":"O moonbit-lang é um compilador C otimizado para velocidade, escrito em MoonBit, permitindo ao desenvolvedor criar códigos mais eficientes.","ru":"ИИ Агенты: moonbit-lang - это компилятор С, оптимизированный для скорости, написанный на MoonBit, который позволяет разработчикам создавать более эффективный код.","ar":"أدوات الذكاء الاصطناعي: moonbit-lang هو مُجمع سي مُحسّن للسرعة، مكتوب بلغة MoonBit، مما يسمح للمطورين بإنشاء رموز أكثر كفاءة.","en":"The c compiler optimized for speed written in MoonBit"},"seo":{"title":{"zh":"MoonBit 语言 AI 工具 - 速度优化的 C 编译器","ja":"MoonBit言語 AIエージェント - 速度最適化のCコンパイラ","ko":"MoonBit 언어 AI 에이전트 - 속도 최적화된 C 컴파일러","es":"Herramientas de AI: Compilador moonbit-lang optimizado","fr":"Outils d''IA: Compilateur moonbit-lang pour la vitesse","de":"KI-Tools: Moonbit-lang Compiler für Geschw