INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('banteg/crimson/crimson-release', 'crimson-release', 'banteg', 'crimson', 'community', 'crimson-release banteg crimson community Crimson Release是一个忠实的Crimsonland 1.9.93重写，具有AI工具和技术特点 Crimson Releaseは2003年のCrimsonland 1.9.93の忠実なリライトであり、AIエージェントと技術的特徴を備えています 크림슨 릴리스는 2003년 크림슨랜드 1.9.93의忠実한 리메이크로, AI 에이전트 및 기술적 특징이 있습니다 crimson-release es una réplica fiel de Crimsonland 1.9.93 desde 2003, diseñada para desarrolladores que buscan una experiencia de juego clásica crimson-release est une refonte fidèle de Crimsonland 1.9.93 depuis 2003, conçue pour les développeurs qui recherchent une expérience de jeu classique crimson-release ist eine treue Nachbildung von Crimsonland 1.9.93 seit 2003, entwickelt für Entwickler, die eine klassische Spielereahrung suchen O Crimson Release é uma reescrita fiel do Crimsonland 1.9.93 de 2003, oferecendo funcionalidades avançadas Crimson Release - это верная переписка Crimsonland 1.9.93 от 2003 года, предлагающая расширенные возможности Crimson Release هو إعادة كتابة忠实 لبرنامج Crimsonland 1.9.93 من عام 2003، يوفر ميزات متقدمة a faithful rewrite of crimsonland 1.9.93 from 2003 如何使用Crimson Release 什么是AIエージェント Crimson Release替代品 Crimson Release vs 其他游戏 Crimson Release安装 Crimson Release设置指南 AIエージェント游戏开发 Crimsonland 1.9.93重写 a faithful rewrite of crimsonland 1.9.93 from 2003');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wannysim/mumak-www/ci-preflight', 'community', 'wannysim', 'mumak-www', 'wannysim/mumak-www', 'ci-preflight', 0, 0, 25, '2026-03-04T13:07:01.817Z', '2026-03-04T14:36:48.837Z', 'ac2a15503e7271965d51898d6b7656a2522442beb1bdd9c89dc756a9d488c06d', '{"id":"wannysim/mumak-www/ci-preflight","name":"ci-preflight","description":{"zh":"CI Preflight是一种AI工具，用于优化开发流程，提高效率","ja":"CI Preflightは開発プロセスを最適化し、効率を高めるAIエージェントです","ko":"CI Preflight는 개발 프로세스를 최적화하고 효율을 높이는 AI 에이전트입니다","es":"ci-preflight es una herramienta de AI que ayuda a los desarrolladores a automatizar y mejorar sus flujos de trabajo","fr":"ci-preflight est un outil d''AI qui aide les développeurs à automatiser et améliorer leurs flux de travail","de":"ci-preflight ist ein KI-Tool, das Entwicklern hilft, ihre Arbeitsabläufe zu automatisieren und zu verbessern","pt":"O ci-preflight é uma ferramenta de AI que ajuda nos testes de integração contínua, permitindo que os desenvolvedores trabalhem de forma mais eficiente.","ru":"ИИ Агент ci-preflight помогает в тестировании непрерывной интеграции, позволяя разработчикам работать более эффективно.","ar":"أداة الذكاء الاصطناعي ci-preflight تساعد في اختبارات التكامل المستمر، مما يسمح للمطورين بالعمل بطريقة أكثر كفاءة.","en":"Mumak on the WWW"},"seo":{"title":{"zh":"CI Preflight AI工具：Mumak on the WWW","ja":"CI Preflight AIエージェント：Mumak on the WWW","ko":"CI Preflight AI 에이전트：Mumak on the WWW","es":"Herramientas de AI: ci-preflight para Desarrolladores","fr":"Outils d''AI: ci-preflight pour les Développeurs","de":"KI-Tools: ci-preflight für Entwickler","pt":"Ferramentas de AI: ci-preflight para Desenvolvedores","ru":"ИИ Агенты: ci-preflight для Разработчиков","ar":"أدوات الذكاء الاصطناعي: ci-preflight للמطورين","en":"ci-preflight"},"description":{"zh":"CI Preflight是一种AI工具，用于优化开发流程，提高效率","ja":"CI Preflightは開発プロセスを最適化し、効率を高めるAIエージェントです","ko":"CI Preflight는 개발 프로세스를 최적화하고 효율을 높이는 AI 에이전트입니다","es":"ci-preflight es una herramienta de AI que ayuda a los desarrolladores a automatizar y mejorar sus flujos de trabajo","fr":"ci-preflight est un outil d''AI qui aide les développeurs à automatiser et améliorer leurs flux de travail","de":"ci-preflight ist ein KI-Tool, das Entwicklern hilft, ihre Arbeitsabläufe zu automatisieren und zu verbessern","pt":"O ci-preflight é uma ferramenta de AI que ajuda nos testes de integração contínua, permitindo que os desenvolvedores trabalhem de forma mais eficiente.","ru":"ИИ Агент ci-preflight помогает в тестировании непрерывной интеграции, позволяя разработчикам работать более эффективно.","ar":"أداة الذكاء الاصطناعي ci-preflight تساعد في اختبارات التكامل المستمر، مما يسمح للمطورين بالعمل بطريقة أكثر كفاءة.","en":"Mumak on the WWW"},"definition":{"en":"Mumak on the WWW"},"features":{"zh":["自动化测试和验证","支持多种开发语言","集成CI/CD流程","提高开发效率","减少错误和漏洞"],"ja":["自動テストと検証","複数の開発言語をサポート","CI/CDプロセスとの統合","開発効率の向上","エラーと脆弱性の削減"],"ko":["자동 테스트와 검증","다중 개발 언어 지원","CI/CD 프로세스 통합","개발 효율성 향상","오류와 취약점 감소"],"es":["Automatización de flujos de trabajo","Integración con herramientas de desarrollo","Análisis de código y depuración","Soporte para múltiples lenguajes de programación","Interfaz de línea de comandos (CLI) personalizable"],"fr":["Automatisation des flux de travail","Intégration avec des outils de développement","Analyse de code et débogage","Prise en charge de plusieurs langages de programmation","Interface de ligne de commande (CLI) personnalisable"],"de":["Automatisierung von Arbeitsabläufen","Integration mit Entwicklungstools","Code-Analyse und Fehlerbehebung","Unterstützung für mehrere Programmiersprachen","Benutzerdefinierte Kommandozeilen-Schnittstelle (CLI)"],"pt":["Automação de testes de integração contínua","Integração com ferramentas de desenvolvimento populares","Análise de código e detecção de erros","Otimização de desempenho e eficiência","Suporte a múltiplas linguagens de programação"],"ru":["Автоматизация тестирования непрерывной интеграции","Интеграция с популярными инструментами разработки","Анализ кода и обнаружение ошибок","Оптимизация производительности и эффективности","Поддержка нескольких языков программирования"],"ar":["أتمتة اختبارات التكامل المستمر","التكامل مع أدوات تطوير شعبية","تحليل الكود واكتشاف الأخطاء","تحسين الأداء والكفاءة","دعم لغات برمجة متعددة"]},"keywords":{"zh":["CI Preflight AI工具","如何使用CI Preflight","CI Preflight教程","CI Preflight替代品","CI Preflight安装","CI Preflight setup guide","CI Preflight vs Jenkins","CI Preflight和Gitlab CI"],"ja":["CI Preflight AIエージェント","CI Preflightの使い方","CI Preflightチュートリアル","CI Preflightの代替","CI Preflightのインストール","CI Preflight setup guide","CI Preflight vs Jenkins","CI PreflightとGitlab CI"],"ko":["CI Preflight AI 에이전트","CI Preflight 사용법","CI Preflight 튜토리얼","CI Preflight 대안","CI Preflight 설치","CI Preflight setup guide","CI Preflight vs Jenkins","CI Preflight와 Gitlab CI"],"es":["herramientas de AI para desarrolladores","ci-preflight tutorial","automatización de desarrollo","integración con GitHub","alternativas a Jenkins","guias de instalación de ci-preflight","mejores prácticas para ci-preflight","ci-preflight vs GitLab CI"],"fr":["outils d''AI pour les développeurs","tutoriel ci-preflight","automatisation de développement","intégration avec GitHub","alternatives à Jenkins","guides d''installation de ci-preflight","meilleures pratiques pour ci-preflight","ci-preflight vs GitLab CI"],"de":["KI-Tools für Entwickler","ci-preflight-Tutorial","Automatisierung von Entwicklung","Integration mit GitHub","Alternativen zu Jenkins","Installationsanleitungen für ci-preflight","Best Practices für ci-preflight","ci-preflight vs GitLab CI"],"pt":["como usar ci-preflight","o que é ci-preflight","ferramentas de AI para desenvolvedores","ci-preflight vs jenkins","guia de instalação do ci-preflight","ci-preflight para python","ci-preflight para react","ci-preflight para nodejs"],"ru":["как использовать ci-preflight","что такое ci-preflight","инструменты ИИ для разработчиков","ci-preflight vs jenkins","руководство по установке ci-preflight","ci-preflight для python","ci-preflight для react","ci-preflight для nodejs"],"ar":["كيفية استخدام ci-preflight","ما هي ci-preflight","أدوات الذكاء الاصطناعي للمطورين","ci-preflight مقابل jenkins","دليل تثبيت ci-preflight","ci-preflight لغة python","ci-preflight لغة react","ci-preflight لغة nodejs"]}},"owner":"wannysim","repo":"mumak-www","repoPath":"wannysim/mumak-www","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.817Z","topics":[],"category":"community","skillMd":{"name":"ci-preflight","description":"코드 작성 완료 후 CI 검증을 로컬에서 수행합니다. 코드 변경 완료 시, 커밋 요청 시, PR 생성 요청 시 자동으로 적용됩니다.","bodyPreview":"# CI Preflight 검증\n\n코드 변경 후 커밋/PR 전에 CI에서 실행되는 검증을 로컬에서 먼저 수행합니다.\n\n## 필수: 코드 변경 완료 시 검증\n\n코드 작성을 완료하면 **반드시** 아래 검증을 순서대로 실행합니다.\n\n### 1. 변경된 앱 확인\n\n```bash\n# 현재 브랜치에서 변경된 파일 확인\ngit diff --name-only origin/develop...HEAD\n\n# 변경된 앱 파악 (apps/ 또는 packages/ 하위)\n```\n\n### 2. 검증 실행 (순서 중요)\n\n```bash\n# 1) Type Check - 가장 먼저 (타입 오류가 다른 검증에 영향)\npnpm turbo run check-types --filter=<app>\n\n# 2) Lint\npnpm turbo run lint --filter=<app>\n\n# 3) Format Check\npnpm turbo run format:check --filter=<app>\n\n# 4) Test\npnpm tur","body":"# CI Preflight 검증\n\n코드 변경 후 커밋/PR 전에 CI에서 실행되는 검증을 로컬에서 먼저 수행합니다.\n\n## 필수: 코드 변경 완료 시 검증\n\n코드 작성을 완료하면 **반드시** 아래 검증을 순서대로 실행합니다.\n\n### 1. 변경된 앱 확인\n\n```bash\n# 현재 브랜치에서 변경된 파일 확인\ngit diff --name-only origin/develop...HEAD\n\n# 변경된 앱 파악 (apps/ 또는 packages/ 하위)\n```\n\n### 2. 검증 실행 (순서 중요)\n\n```bash\n# 1) Type Check - 가장 먼저 (타입 오류가 다른 검증에 영향)\npnpm turbo run check-types --filter=<app>\n\n# 2) Lint\npnpm turbo run lint --filter=<app>\n\n# 3) Format Check\npnpm turbo run format:check --filter=<app>\n\n# 4) Test\npnpm turbo run test:ci --filter=<app>\n\n# 5) Build (선택적 - PR 전 권장)\npnpm turbo run build --filter=<app>\n```\n\n### 3. 빠른 전체 검증\n\n변경된 부분만 한번에 검증:\n\n```bash\n# develop 브랜치 대비 변경된 부분 검증\n# 주의: zsh에서는 반드시 따옴표로 감싸야 함 (bracket이 glob으로 해석됨)\npnpm turbo run check-types lint format:check test:ci --filter=''[origin/develop...HEAD]''\n```\n\n## Turbo 필터 팁\n\n### 자주 사용하는 패턴\n\n```bash\n# 특정 앱만\n--filter=blog\n--filter=mumak-next\n\n# 변경된 부분만 (CI와 동일)\n# zsh에서는 따옴표 필수\n--filter=''[origin/develop...HEAD]''\n\n# 특정 앱 + 의존성\n--filter=...blog\n```\n\n### 캐시 관련\n\n```bash\n# 캐시 무시 (이상한 동작 시)\npnpm turbo run check-types --force\n\n# 전체 캐시 삭제\npnpm turbo:clean && pnpm install\n```\n\n## 자주 발생하는 오류와 해결\n\n### Type Check 실패\n\n| 오류 유형            | 원인             | 해결                                                |\n| -------------------- | ---------------- | --------------------------------------------------- |\n| `Cannot find module` | 빌드 순서 문제   | `pnpm turbo run build --filter=@mumak/ui` 먼저 실행 |\n| 타입 불일치          | 의존 패키지 변경 | 해당 패키지 `check-types` 먼저 확인                 |\n| `.d.ts` 없음         | 빌드 미실행      | 의존 패키지 빌드 후 재시도                          |\n\n### Lint 실패\n\n```bash\n# 자동 수정 가능한 것들\npnpm turbo run lint:fix --filter=<app>\n```\n\n### Format 실패\n\n```bash\n# 포맷 자동 적용\npnpm turbo run format --filter=<app>\n```\n\n## 검증 체크리스트\n\n코드 변경 완료 시 확인:\n\n- [ ] `check-types` 통과\n- [ ] `lint` 통과 (또는 `lint:fix` 실행)\n- [ ] `format:check` 통과 (또는 `format` 실행)\n- [ ] `test:ci` 통과\n- [ ] (PR 전) `build` 통과\n\n## 빠른 검증 스크립트\n\n전체 검증을 한번에 실행하려면:\n\n```bash\n./scripts/preflight.sh [app-name]\n```\n\n스크립트 없이 한줄로:\n\n```bash\npnpm turbo run check-types lint format:check test:ci --filter=''[origin/develop...HEAD]''\n```\n"},"lastSynced":"2026-03-04T14:36:48.837Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing automated CI validation and testing capabilities.","zh":"非常适合需要自动化CI验证和测试功能的代码审查代理。","ja":"コードレビューエージェントが自動化されたCIバリデーションとテスト機能を必要とする場合に最適です。","ko":"코드 검토 에이전트가 자동화된 CI 유효성 검사 및 테스트 기능을 필요로 할 때 완벽합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan capacidades de validación y prueba de CI automatizadas.","fr":"Parfait pour les agents de révision de code nécessitant une validation et des tests de CI automatisés.","de":"Perfekt für Code-Review-Agents, die automatisierte CI-Validierungs- und Testfunktionen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que precisam de validação e capacidades de teste de CI automatizadas.","ru":"Идеально подходит для агентов обзора кода, требующих автоматизированной проверки и тестирования CI.","ar":"مثالي للوكلاء المراجعة الكود الذين يحتاجون إلى التحقق والاختبار التلقائي ل CI."},"recommendation":{"en":"Empowers agents to execute crucial checks like Type Check, Lint, Format Check, and Test using pnpm turbo run, ensuring code integrity and reducing CI pipeline failures by validating changes before commit or PR.","zh":"赋予代理执行重要检查的能力，例如类型检查、Lint、格式检查和使用pnpm turbo run进行测试，确保代码完整性并通过验证更改来减少CI管道故障。","ja":"エージェントに重要なチェックを実行する能力を与えます。例えば、型チェック、Lint、フォーマットチェック、およびpnpm turbo runを使用したテストを行い、コードの完全性を確保し、変更を検証することでCIパイプラインの故障を減らすことができます。","ko":"에이전트가 중요한 확인을 수행할 수 있는 능력을 부여합니다. 예를 들어, 유형 확인, Lint, 형식 확인 및 pnpm 터보 런을 사용한 테스트를 통해 코드의 무결성을 보장하고 변경 사항을 확인하여 CI 파이프라인 오류를 줄일 수 있습니다.","es":"Habilita a los agentes a ejecutar controles cruciales como Type Check, Lint, Format Check y Test utilizando pnpm turbo run, lo que garantiza la integridad del código y reduce los errores de la tubería de CI validando los cambios antes de comprometer o PR.","fr":"Permet aux agents d''exécuter des vérifications cruciales comme Type Check, Lint, Format Check et Test en utilisant pnpm turbo run, garantissant ainsi l''intégrité du code et réduisant les erreurs de la pipeline de CI en validant les modifications avant de les valider ou de les envoyer.","de":"Ermächtigt Agenten, wichtige Prüfungen wie Type Check, Lint, Format Check und Test mit pnpm turbo run auszuführen, um die Code-Integrität sicherzustellen und die Fehler in der CI-Pipeline zu reduzieren, indem Änderungen vor dem Commit oder PR validiert werden.","pt":"Habilita os agentes a executar verificações cruciais como Type Check, Lint, Format Check e Teste usando pnpm turbo run, garantindo a integridade do código e reduzindo falhas no pipeline de CI, validando alterações antes do commit ou PR.","ru":"Наделяет агентов возможностью выполнять важные проверки, такие как Type Check, Lint, Format Check и Test, используя pnpm turbo run, обеспечивая целостность кода и уменьшая количество сбоев в конвейере CI, проверяя изменения перед фиксацией или запросом на вытягивание.","ar":"يُمكّن الوكلاء من تشغيل التحقق الحرج مثل Type Check و Lint و Format Check و Test باستخدام pnpm turbo run، مما يضمن سلامة الكود ويقلل من فشل خط أنابيب CI من خلال التحقق من التغييرات قبل الالتزام أو طلب السحب."},"useCases":{"en":["Automating code validation before commit or PR","Running Type Check to catch type-related errors","Executing Lint and Format Check for code consistency and quality"],"zh":["在提交或PR之前自动化代码验证","运行类型检查以捕获类型相关错误","执行Lint和格式检查以确保代码的一致性和质量"],"ja":["コミットまたはPRの前にコードの検証を自動化する","型チェックを実行して型関連のエラーをキャッチする","Lintとフォーマットチェックを実行してコードの整合性と品質を確保する"],"ko":["커밋 또는 PR 이전에 코드 검증 자동화","타입 확인을 실행하여 타입 관련 오류를 잡는 것","린트 및 형식 확인 실행하여 코드 일관성 및 품질 보장"],"es":["Automatizar la validación de código antes de comprometer o PR","Ejecutar Type Check para detectar errores relacionados con tipos","Ejecutar Lint y Format Check para la coherencia y calidad del código"],"fr":["Automatiser la validation du code avant de valider ou d''envoyer","Exécuter Type Check pour détecter les erreurs liées aux types","Exécuter Lint et Format Check pour la cohérence et la qualité du code"],"de":["Automatisierung der Code-Validierung vor dem Commit oder PR","Ausführen von Type Check, um typbezogene Fehler zu erkennen","Ausführen von Lint und Format Check für die Konsistenz und Qualität des Codes"],"pt":["Automatizar a validação de código antes do commit ou PR","Executar Type Check para capturar erros relacionados a tipos","Executar Lint e Format Check para consistência e qualidade do código"],"ru":["Автоматизировать проверку кода перед фиксацией или запросом на вытягивание","Выполнить Type Check для поиска ошибок, связанных с типами","Выполнить Lint и Format Check для согласованности и качества кода"],"ar":["تأتمة التحقق من الكود قبل الالتزام أو طلب السحب","تشغيل Type Check للقبض على الأخطاء المتعلقة بالأنواع","تشغيل Lint و Format Check من أجل اتساق ونوعية الكود"]},"limitations":{"en":["Requires pnpm and turbo setup","Limited to specific app or package validation","Dependent on correct filter configuration for targeted validation"],"zh":["需要pnpm和turbo设置","仅限于特定应用或包验证","依赖于正确的过滤器配置以实现目标验证"],"ja":["pnpmとturboの設定が必要","特定のアプリまたはパッケージの検証のみ","目標の検証を実現するために正しいフィルタの設定に依存"],"ko":["pnpm 및 터보 설정이 필요","특정 애플리케이션 또는 패키지 유효성 검사만","목표 유효성 검사를 달성하기 위해 올바른 필터 구성에 의존"],"es":["Requiere configuración de pnpm y turbo","Limitado a la validación de aplicaciones o paquetes específicos","Dependiente de la configuración de filtros correcta para la validación dirigida"],"fr":["Nécessite une configuration pnpm et turbo","Limité à la validation d''applications ou de packages spécifiques","Dépend de la configuration correcte des filtres pour la validation ciblée"],"de":["Benötigt pnpm- und Turbo-Setup","Begrenzt auf die Validierung spezifischer Apps oder Pakete","Abhängig von der korrekten Filterkonfiguration für die gezielte Validierung"],"pt":["Requer pnpm e configuração turbo","Limitado à validação de aplicativos ou pacotes específicos","Dependente da configuração correta do filtro para validação direcionada"],"ru":["Требует настройки pnpm и turbo","Ограничен проверкой конкретных приложений или пакетов","Зависит от правильной конфигурации фильтра для целевой проверки"],"ar":["يتطلب إعداد pnpm و turbo","محدود بالتحقق من التطبيقات أو الحزم المحددة","يعتمد على إعداد مرشح صحيح للتحقق المستهدَف"]},"version":3},"contentHash":"ac2a15503e7271965d51898d6b7656a2522442beb1bdd9c89dc756a9d488c06d","qualityScore":25}');
