INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wannysim/mumak-www/ci-preflight', 'ci-preflight', 'wannysim', 'mumak-www', 'community', 'ci-preflight wannysim mumak-www community CI Preflight是一种AI工具，用于优化开发流程，提高效率 CI Preflightは開発プロセスを最適化し、効率を高めるAIエージェントです CI Preflight는 개발 프로세스를 최적화하고 효율을 높이는 AI 에이전트입니다 ci-preflight es una herramienta de AI que ayuda a los desarrolladores a automatizar y mejorar sus flujos de trabajo ci-preflight est un outil d''AI qui aide les développeurs à automatiser et améliorer leurs flux de travail ci-preflight ist ein KI-Tool, das Entwicklern hilft, ihre Arbeitsabläufe zu automatisieren und zu verbessern O ci-preflight é uma ferramenta de AI que ajuda nos testes de integração contínua, permitindo que os desenvolvedores trabalhem de forma mais eficiente. ИИ Агент ci-preflight помогает в тестировании непрерывной интеграции, позволяя разработчикам работать более эффективно. أداة الذكاء الاصطناعي ci-preflight تساعد في اختبارات التكامل المستمر، مما يسمح للمطورين بالعمل بطريقة أكثر كفاءة. Mumak on the WWW CI Preflight AI工具 如何使用CI Preflight CI Preflight教程 CI Preflight替代品 CI Preflight安装 CI Preflight setup guide CI Preflight vs Jenkins CI Preflight和Gitlab CI Mumak on the WWW');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sf-bcca/ChoreWars/gamification-sim', 'community', 'sf-bcca', 'ChoreWars', 'sf-bcca/ChoreWars', 'gamification-sim', 0, 0, 25, '2026-03-04T13:07:01.894Z', '2026-03-04T14:55:22.805Z', '165e341de597ae82aaceae7f6d4117235a0aee9e4bc01359234a545def0c8907', '{"id":"sf-bcca/ChoreWars/gamification-sim","name":"gamification-sim","description":{"zh":"gamification-sim是一个用于家庭任务管理的AI智能工具，帮助您轻松完成任务","ja":"gamification-simは、家族みんなで家事を完了させるための楽しいAIエージェントです","ko":"gamification-sim은 家庭任务을 완수하기 위한 재미있는 AI 에이전트입니다","es":"La aplicación gamification-sim es una herramienta de código abierto que utiliza Agentes de IA para hacer que las tareas domésticas sean más divertidas","fr":"L''application gamification-sim est un outil open source qui utilise des Agents d''IA pour rendre les tâches ménagères plus amusantes","de":"Die Anwendung gamification-sim ist ein Open-Source-Tool, das KI-Agents verwendet, um Haushaltsaufgaben unterhaltsamer zu gestalten","pt":"A aplicação gamification-sim é uma ferramenta de IA amigável para ajudar famílias a realizar tarefas domésticas de forma divertida","ru":"Приложение gamification-sim - это дружественный ИИ инструмент для помощи семьям в выполнении домашних задач в веселой форме","ar":"التطبيق gamification-sim هو أداة ذكاء اصطناعي友ية لمساعدة العائلات على إنجاز المهمات المنزلية بطريقة ممتعة","en":"Fun and friendly application for the family to get household tasks done."},"seo":{"title":{"zh":"AI智能工具：gamification-sim","ja":"AIエージェント：gamification-sim","ko":"AI 에이전트: gamification-sim","es":"Herramientas de gamificación para tareas domésticas con A...","fr":"Outils de gamification pour tâches ménagères avec Agents ...","de":"Gamifizierungstools für Haushaltsaufgaben mit KI-Agents","pt":"gamification-sim: Ferramenta de IA para Tarefas Domésticas","ru":"ИИ Агенты: gamification-sim для домашних задач","ar":"gamification-sim: أداة ذكاء اصطناعي لل任务 المنزلية","en":"gamification-sim"},"description":{"zh":"gamification-sim是一个用于家庭任务管理的AI智能工具，帮助您轻松完成任务","ja":"gamification-simは、家族みんなで家事を完了させるための楽しいAIエージェントです","ko":"gamification-sim은 家庭任务을 완수하기 위한 재미있는 AI 에이전트입니다","es":"La aplicación gamification-sim es una herramienta de código abierto que utiliza Agentes de IA para hacer que las tareas domésticas sean más divertidas","fr":"L''application gamification-sim est un outil open source qui utilise des Agents d''IA pour rendre les tâches ménagères plus amusantes","de":"Die Anwendung gamification-sim ist ein Open-Source-Tool, das KI-Agents verwendet, um Haushaltsaufgaben unterhaltsamer zu gestalten","pt":"A aplicação gamification-sim é uma ferramenta de IA amigável para ajudar famílias a realizar tarefas domésticas de forma divertida","ru":"Приложение gamification-sim - это дружественный ИИ инструмент для помощи семьям в выполнении домашних задач в веселой форме","ar":"التطبيق gamification-sim هو أداة ذكاء اصطناعي友ية لمساعدة العائلات على إنجاز المهمات المنزلية بطريقة ممتعة","en":"Fun and friendly application for the family to get household tasks done."},"definition":{"en":"Fun and friendly application for the family to get household tasks done."},"features":{"zh":["使用React和Node.js构建","支持CLI命令","提供任务管理和跟踪功能","具有用户友好的界面","支持多语言"],"ja":["ReactとNode.jsで構築","CLIコマンドをサポート","タスク管理と追跡機能を提供","ユーザーフレンドリーなインターフェース","多言語対応"],"ko":["React와 Node.js로 구축","CLI 명령어 지원","작업 관리 및 추적 기능 제공","사용자 친화적인 인터페이스","다국어 지원"],"es":["Integración con Agentes de IA para automatizar tareas","Interfaz de usuario amigable para una experiencia de usuario óptima","Compatibilidad con múltiples plataformas para una mayor flexibilidad","Código abierto para una personalización y extensión fácil","Soporte para múltiples idiomas para una mayor accesibilidad"],"fr":["Intégration avec des Agents d''IA pour automatiser des tâches","Interface utilisateur conviviale pour une expérience utilisateur optimale","Compatibilité avec plusieurs plateformes pour une plus grande flexibilité","Code open source pour une personnalisation et une extension faciles","Support pour plusieurs langues pour une plus grande accessibilité"],"de":["Integration mit KI-Agents zur Automatisierung von Aufgaben","Benutzerfreundliche Oberfläche für eine optimale Benutzererfahrung","Kompatibilität mit mehreren Plattformen für eine größere Flexibilität","Open-Source-Code für eine einfache Anpassung und Erweiterung","Unterstützung für mehrere Sprachen für eine größere Zugänglichkeit"],"pt":["Interface amigável para famílias","Técnicas de gamificação para tarefas domésticas","Integração com dispositivos móveis","Desenvolvido com React e Node.js","CLI para configuração fácil","Compatível com múltiplos sistemas operacionais"],"ru":["Дружественный интерфейс для семей","Методы геймификации для домашних задач","Интеграция с мобильными устройствами","Разработан на React и Node.js","CLI для легкой настройки","Совместим с несколькими операционными системами"],"ar":["واجهة مستخدم友ية للعائلات","تقنيات اللعبة للمهمات المنزلية","التكامل مع الأجهزة المحمولة","تم تطويره باستخدام React و Node.js","CLI للتهيئة السهلة","متوافق مع أنظمة تشغيل متعددة"]},"keywords":{"zh":["如何使用gamification-sim","什么是AI智能工具","gamification-sim替代品","gamification-sim安装","gamification-sim设置指南","React和Node.js开发"],"ja":["gamification-simの使い方","AIエージェントとは","gamification-simの代替","gamification-simのインストール","gamification-simの設定ガイド","ReactとNode.jsの開発"],"ko":["gamification-sim 사용법","AI 에이전트란","gamification-sim 대체","gamification-sim 설치","gamification-sim 설정 가이드","React와 Node.js 개발"],"es":["cómo usar Agentes de IA","qué es gamificación","alternativas a gamification-sim","gamification-sim vs otros Agentes de IA","instalación de gamification-sim","guía de configuración de gamification-sim","desarrollo de aplicaciones con Agentes de IA"],"fr":["comment utiliser des Agents d''IA","qu''est-ce que la gamification","alternatives à gamification-sim","gamification-sim vs d''autres Agents d''IA","installation de gamification-sim","guide de configuration de gamification-sim","développement d''applications avec des Agents d''IA"],"de":["wie man KI-Agents verwendet","was ist Gamifizierung","Alternativen zu gamification-sim","gamification-sim vs andere KI-Agents","Installation von gamification-sim","Konfigurationsanleitung für gamification-sim","Entwicklung von Anwendungen mit KI-Agents"],"pt":["como usar gamification-sim","o que é gamification-sim","gamification-sim alternative","gamification-sim vs outros","instalar gamification-sim","guia de configuração do gamification-sim","desenvolvimento de aplicativos com React","utilizando Node.js para desenvolvimento de aplicativos","CLI para desenvolvedores"],"ru":["как использовать gamification-sim","что такое gamification-sim","альтернативы gamification-sim","gamification-sim vs другие","установка gamification-sim","руководство по настройке gamification-sim","разработка приложений с использованием React","использование Node.js для разработки приложений","CLI для разработчиков"],"ar":["كيفية استخدام gamification-sim","ما هي gamification-sim","بديل gamification-sim","gamification-sim مقابل أخرى","تثبيت gamification-sim","دليل إعداد gamification-sim","تطوير التطبيقات باستخدام React","استخدام Node.js لتطوير التطبيقات","CLI للمطورين"]}},"owner":"sf-bcca","repo":"ChoreWars","repoPath":"sf-bcca/ChoreWars","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.894Z","topics":[],"category":"community","skillMd":{"name":"gamification-sim","description":"Tools for simulating gamification scenarios in ChoreWars. Use this to reset the database and inject specific test data (points, streaks, chores) to verify leaderboard, analytics, or UI behavior.","bodyPreview":"# Gamification Simulator\n\nThis skill helps you test gamification features by injecting specific data states into the database.\n\n## Quick Start\n\nTo inject a specific scenario (e.g., `competitive-family`):\n```bash\nnode gamification-sim/scripts/run_scenario.cjs competitive-family\n```\n\nTo reset to a clean state:\n```bash\nnode gamification-sim/scripts/run_scenario.cjs clean-slate\n```\n\n## Available Scenarios\n\nSee [scenarios.md](./references/scenarios.md) for details on:\n- `clean-slate`: Wipes all data","body":"# Gamification Simulator\n\nThis skill helps you test gamification features by injecting specific data states into the database.\n\n## Quick Start\n\nTo inject a specific scenario (e.g., `competitive-family`):\n```bash\nnode gamification-sim/scripts/run_scenario.cjs competitive-family\n```\n\nTo reset to a clean state:\n```bash\nnode gamification-sim/scripts/run_scenario.cjs clean-slate\n```\n\n## Available Scenarios\n\nSee [scenarios.md](./references/scenarios.md) for details on:\n- `clean-slate`: Wipes all data and creates a single Admin (\"Dad\").\n- `competitive-family`: Adds multiple members with high points and streaks.\n- `overdue-crisis`: Injects several overdue chores for a specific member.\n- `analytics-rich`: Creates 30 days of historical logs for chart testing.\n\n## Workflows\n\n### Testing Leaderboard\n1. Run: `node gamification-sim/scripts/run_scenario.cjs competitive-family`\n2. Open the frontend and navigate to `/leaderboard`.\n3. Verify members are ranked correctly by XP.\n\n### Testing Analytics\n1. Run: `node gamification-sim/scripts/run_scenario.cjs analytics-rich`\n2. Navigate to `/admin/reports`.\n3. Verify charts show data trends over the last month.\n\n## Customization\nTo add new scenarios, edit `gamification-sim/scripts/inject_scenario.ts`. The `run_scenario.cjs` wrapper will automatically pick up your changes.\n"},"lastSynced":"2026-03-04T14:55:22.805Z","agentAnalysis":{"suitability":{"en":"Perfect for Family-Oriented AI Agents needing interactive household task management through gamification features.","zh":"适合需要通过游戏化功能进行交互式家庭任务管理的面向家庭的AI代理。","ja":"家族向けのAIエージェントがインタラクティブな家庭のタスク管理をゲーム化機能を通じて行う必要がある場合に最適です。","ko":"가정용 AI 에이전트가 게임화 기능을 통해 상호 작용형 가사 관리를 필요로 할 때 적합합니다.","es":"Perfecto para Agentes de Inteligencia Artificial orientados a la familia que necesitan una gestión interactiva de tareas del hogar a través de características de gamificación.","fr":"Parfait pour les Agents d''Intelligence Artificielle axés sur la famille ayant besoin d''une gestion interactive des tâches ménagères grâce à des fonctionnalités de gamification.","de":"Perfekt für familienorientierte KI-Agents, die eine interaktive Haushaltsaufgabenverwaltung durch Gamification-Features benötigen.","pt":"Perfeito para Agentes de IA orientados para família que necessitam de gerenciamento de tarefas domésticas interativas por meio de recursos de gamificação.","ru":"Идеально подходит для семейных агентов ИИ, которым необходим интерактивный менеджер домашних задач через функции геймификации.","ar":"مثالي للوكلاء الذكاء الاصطناعي المناسبين للعائلات التي تحتاج إلى إدارة مهام منزلية تفاعلية من خلال ميزات اللعبة."},"recommendation":{"en":"Empowers agents to test and simulate various gamification scenarios by injecting specific data states into the database using Node.js, enabling the creation of fun and friendly applications for family engagement, and supports scenarios like ''competitive-family'' and ''clean-slate'' through scripts like ''run_scenario.cjs''.","zh":"赋予代理测试和模拟各种游戏化场景的能力，方法是使用Node.js将特定的数据状态注入数据库，使得能够创建有趣和友好的家庭参与应用，并通过脚本如''run_scenario.cjs''支持诸如''竞争性家庭''和''干净的状态''的场景。","ja":"エージェントがさまざまなゲーム化シナリオをテストおよびシミュレートできるようにし、Node.jsを使用してデータベースに特定のデータ状態を挿入して、家族の関与のための楽しく親しみやすいアプリケーションを作成し、''run_scenario.cjs''などのスクリプトを使用して''競争家族''や''クリーンな状態''などのシナリオをサポートします。","ko":"에이전트가 다양한 게임화 시나리오를 테스트하고 시뮬레이션할 수 있도록 하여 Node.js를 사용하여 데이터베이스에 특정 데이터 상태를 삽입하여 가족 참여를 위한趣味 있고 친근한 애플리케이션을 만들고 ''run_scenario.cjs''와 같은 스크립트를 사용하여 ''경쟁 가족'' 및 ''깨끗한 상태''와 같은 시나리오를 지원합니다.","es":"Habilita a los agentes a probar y simular varios escenarios de gamificación al inyectar estados de datos específicos en la base de datos utilizando Node.js, lo que permite la creación de aplicaciones divertidas y amigables para el compromiso familiar, y admite escenarios como ''competitive-family'' y ''clean-slate'' a través de scripts como ''run_scenario.cjs''.","fr":"Permet aux agents de tester et de simuler différents scénarios de gamification en injectant des états de données spécifiques dans la base de données en utilisant Node.js, ce qui permet de créer des applications amusantes et conviviales pour l''engagement familial, et prend en charge des scénarios tels que ''competitive-family'' et ''clean-slate'' via des scripts tels que ''run_scenario.cjs''.","de":"Ermöglicht es Agents, verschiedene Gamification-Szenarien zu testen und zu simulieren, indem spezifische Datenzustände in die Datenbank mithilfe von Node.js injiziert werden, wodurch die Erstellung von unterhaltsamen und benutzerfreundlichen Anwendungen für die Familienbeteiligung ermöglicht wird und Szenarien wie ''competitive-family'' und ''clean-slate'' durch Skripte wie ''run_scenario.cjs'' unterstützt werden.","pt":"Habilita os agentes a testar e simular vários cenários de gamificação injetando estados de dados específicos no banco de dados usando Node.js, permitindo a criação de aplicações divertidas e amigáveis para engajamento familiar, e suporta cenários como ''competitive-family'' e ''clean-slate'' por meio de scripts como ''run_scenario.cjs''.","ru":"Наделяет агентов возможностью тестировать и模улировать различные сценарии геймификации, впрыскивая определенные состояния данных в базу данных с помощью Node.js, что позволяет создавать веселые и дружественные приложения для семейного взаимодействия, и поддерживает сценарии типа ''competitive-family'' и ''clean-slate'' посредством скриптов типа ''run_scenario.cjs''.","ar":"يمكن للوكلاء اختبار ومحاكاة سيناريوهات مختلفة من اللعبة عن طريق حقن حالات بيانات محددة في قاعدة البيانات باستخدام Node.js، مما يسمح بإنشاء تطبيقات ممتعة وودية للمشاركة العائلية، ودعم السيناريوهات مثل ''competitive-family'' و ''clean-slate'' من خلال سكريبتات مثل ''run_scenario.cjs''."},"useCases":{"en":["Simulating competitive family scenarios to encourage household task completion","Resetting to a clean state for new family engagements","Testing different gamification features for optimal family interaction"],"zh":["模拟竞争性家庭场景以鼓励完成家庭任务","将状态重置为新的家庭参与的干净状态","测试不同的游戏化功能以实现最优的家庭互动"],"ja":["家庭タスクの完了を促進するための競争家族シナリオのシミュレーション","新しい家族の関与のためのクリーンな状態へのリセット","最適な家族のやり取りのためのさまざまなゲーム化機能のテスト"],"ko":["가정 과제 완수를 촉진하기 위한 경쟁 가족 시나리오의 시뮬레이션","새로운 가족 참여를 위한 깨끗한 상태로의 리셋","최적의 가족 상호 작용을 위한 다양한 게임화 기능의 테스트"],"es":["Simulación de escenarios de familia competitiva para fomentar la finalización de tareas del hogar","Reinicialización a un estado limpio para nuevos compromisos familiares","Pruebas de diferentes características de gamificación para una interacción familiar óptima"],"fr":["Simulation de scénarios de famille compétitive pour encourager l''achèvement des tâches ménagères","Réinitialisation à un état propre pour de nouveaux engagements familiaux","Tests de différentes fonctionnalités de gamification pour une interaction familiale optimale"],"de":["Simulieren von Szenarien für eine wettbewerbsorientierte Familie, um die Erledigung von Haushaltsaufgaben zu fördern","Zurücksetzen auf einen sauberen Zustand für neue Familienbeteiligungen","Testen verschiedener Gamification-Features für eine optimale Familieninteraktion"],"pt":["Simular cenários competitivos de família para incentivar a conclusão de tarefas domésticas","Reiniciar para um estado limpo para novos envolvimentos familiares","Testar diferentes recursos de gamificação para interação familiar ótima"],"ru":["Моделировать конкурентные семейные сценарии для поощрения выполнения домашних задач","Сбросить в чистое состояние для новых семейных взаимодействий","Тестировать различные функции геймификации для оптимального семейного взаимодействия"],"ar":["محاكاة سيناريوهات عائلية تنافسية لتشجيع إكمال المهام المنزلية","إعادة تعيين إلى حالة نظيفة لالتزامات عائلية جديدة","اختبار ميزات اللعبة المختلفة للتفاعل العائلي الأمثل"]},"limitations":{"en":["Requires Node.js environment","Specific scenarios must be predefined in the ''scenarios.md'' file"],"zh":["需要Node.js环境","特定场景必须预先定义在''scenarios.md''文件中"],"ja":["Node.js環境が必要","特定のシナリオは''scenarios.md''ファイルに事前に定義する必要がある"],"ko":["Node.js 환경이 필요함","특정 시나리오는 ''scenarios.md'' 파일에事前に 정의해야 함"],"es":["Requiere un entorno Node.js","Escenarios específicos deben estar predefinidos en el archivo ''scenarios.md''"],"fr":["Nécessite un environnement Node.js","Des scénarios spécifiques doivent être préalablement définis dans le fichier ''scenarios.md''"],"de":["Benötigt eine Node.js-Umgebung","Spezifische Szenarien müssen im ''scenarios.md''-File vordefiniert sein"],"pt":["Exige ambiente Node.js","Cenários específicos devem ser pré-definidos no arquivo ''scenarios.md''"],"ru":["Требуется среда Node.js","Конкретные сценарии должны быть предварительно определены в файле ''scenarios.md''"],"ar":["يتطلب بيئة Node.js","يجب تحديد السيناريوهات المحددة مسبقًا في ملف ''scenarios.md''"]},"version":3},"contentHash":"165e341de597ae82aaceae7f6d4117235a0aee9e4bc01359234a545def0c8907","qualityScore":25}');
