INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sf-bcca/ChoreWars/gamification-sim', 'gamification-sim', 'sf-bcca', 'ChoreWars', 'community', 'gamification-sim sf-bcca ChoreWars community gamification-sim是一个用于家庭任务管理的AI智能工具，帮助您轻松完成任务 gamification-simは、家族みんなで家事を完了させるための楽しいAIエージェントです gamification-sim은 家庭任务을 완수하기 위한 재미있는 AI 에이전트입니다 La aplicación gamification-sim es una herramienta de código abierto que utiliza Agentes de IA para hacer que las tareas domésticas sean más divertidas L''application gamification-sim est un outil open source qui utilise des Agents d''IA pour rendre les tâches ménagères plus amusantes Die Anwendung gamification-sim ist ein Open-Source-Tool, das KI-Agents verwendet, um Haushaltsaufgaben unterhaltsamer zu gestalten A aplicação gamification-sim é uma ferramenta de IA amigável para ajudar famílias a realizar tarefas domésticas de forma divertida Приложение gamification-sim - это дружественный ИИ инструмент для помощи семьям в выполнении домашних задач в веселой форме التطبيق gamification-sim هو أداة ذكاء اصطناعي友ية لمساعدة العائلات على إنجاز المهمات المنزلية بطريقة ممتعة Fun and friendly application for the family to get household tasks done. 如何使用gamification-sim 什么是AI智能工具 gamification-sim替代品 gamification-sim安装 gamification-sim设置指南 React和Node.js开发 Fun and friendly application for the family to get household tasks done.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Junghyun99/StockAsset/code-analysis', 'community', 'Junghyun99', 'StockAsset', 'Junghyun99/StockAsset', 'code-analysis', 0, 0, 25, '2026-03-04T13:07:01.930Z', '2026-03-04T15:06:50.927Z', '9139c25a1bd33c4972ac1304ca539f1eba580fd97e6d1579026119de6f41f52f', '{"id":"Junghyun99/StockAsset/code-analysis","name":"code-analysis","description":{"zh":"StockAsset是Google AI Studio中的代码分析工具，帮助开发者优化代码","ja":"StockAssetはGoogle AI Studioのコード分析ツールで、開発者がコードを最適化するのに役立ちます","ko":"StockAsset는 Google AI Studio의 코드 분석 도구로 개발자가 코드를 최적화하는 데 도움이 됩니다","es":"StockAsset de Google AI Studio ofrece análisis de código avanzado con Agentes de IA para desarrolladores","fr":"StockAsset de Google AI Studio propose une analyse de code avancée avec les Outils d''IA pour les développeurs","de":"StockAsset von Google AI Studio bietet eine erweiterte Code-Analyse mit KI-Agents für Entwickler","pt":"O code-analysis é um agente de IA especializado para análise automatizada do projeto StockAsset no Google AI Studio. Ele realiza auditoria de código, identificação de vulnerabilidades e sugestões de otimização para desenvolvedores.","ru":"Code-analysis — это специализированный ИИ агент для автоматизированного анализа проекта StockAsset в Google AI Studio. Он выполняет аудит кода, идентификацию уязвимостей и предоставляет рекомендации по оптимизации для разработчиков.","ar":"code-analysis هي أداة ذكاء اصطناعي متخصصة للتحليل الآلي لمشروع StockAsset في Google AI Studio. تقوم بإجراء مراجعة للتعليمات البرمجية، وتحديد الثغرات الأمنية، وتقديم اقتراحات التحسين للمطورين.","en":"StockAsset - google ai studio"},"seo":{"title":{"zh":"AI工具 - 代码分析","ja":"AIエージェント - コード分析","ko":"AI 에이전트 - 코드 분석","es":"Análisis de código con Agentes de IA","fr":"Analyse de code avec les Outils d''IA","de":"Code-Analyse mit KI-Agents","pt":"Code Analysis AI Agent: StockAsset Google AI St