INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Junghyun99/StockAsset/code-analysis', 'code-analysis', 'Junghyun99', 'StockAsset', 'community', 'code-analysis Junghyun99 StockAsset community StockAsset是Google AI Studio中的代码分析工具，帮助开发者优化代码 StockAssetはGoogle AI Studioのコード分析ツールで、開発者がコードを最適化するのに役立ちます StockAsset는 Google AI Studio의 코드 분석 도구로 개발자가 코드를 최적화하는 데 도움이 됩니다 StockAsset de Google AI Studio ofrece análisis de código avanzado con Agentes de IA para desarrolladores StockAsset de Google AI Studio propose une analyse de code avancée avec les Outils d''IA pour les développeurs StockAsset von Google AI Studio bietet eine erweiterte Code-Analyse mit KI-Agents für Entwickler O code-analysis é um agente de IA especializado para análise automatizada do projeto StockAsset no Google AI Studio. Ele realiza auditoria de código, identificação de vulnerabilidades e sugestões de otimização para desenvolvedores. Code-analysis — это специализированный ИИ агент для автоматизированного анализа проекта StockAsset в Google AI Studio. Он выполняет аудит кода, идентификацию уязвимостей и предоставляет рекомендации по оптимизации для разработчиков. code-analysis هي أداة ذكاء اصطناعي متخصصة للتحليل الآلي لمشروع StockAsset في Google AI Studio. تقوم بإجراء مراجعة للتعليمات البرمجية، وتحديد الثغرات الأمنية، وتقديم اقتراحات التحسين للمطورين. StockAsset - google ai studio 如何使用StockAsset 什么是代码分析 StockAsset替代品 代码分析工具 代码优化技巧 Google AI Studio教程 StockAsset - google ai studio');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shaul1991/shaul-agents-plugin/qa-tester', 'community', 'shaul1991', 'shaul-agents-plugin', 'shaul1991/shaul-agents-plugin', 'qa-tester', 0, 0, 25, '2026-03-04T13:07:01.958Z', '2026-03-04T15:13:26.432Z', '366cc2396a8cad3ec2045594d12798ddde26a881981e34179aacaf16fe657e4c', '{"id":"shaul1991/shaul-agents-plugin/qa-tester","name":"qa-tester","description":{"zh":"qa-tester是Shaul Corporation的Claude Code插件，提供多智能体协作系统，用于提高代码质量","ja":"qa-testerはShaul CorporationのClaude Codeプラグインで、マルチエージェントコラボレーションシステムを提供し、コードの品質を高めます","ko":"qa-tester는 Shaul Corporation의 Claude Code 플러그인으로, 멀티에이전트 협업 시스템을 제공하여 코드 품질을 높입니다","es":"El plugin Claude Code es una herramienta de pruebas de QA para el sistema de colaboración de múltiples agentes de Shaul Corporation","fr":"Le plugin Claude Code est un outil de test QA pour le système de collaboration de multiples agents de Shaul Corporation","de":"Das Claude-Code-Plugin ist ein QA-Test-Tool für das Multiagenten-Kollaborationssystem von Shaul Corporation","pt":"O testador de QA da Shaul Corporation é um plugin Claude Code para sistemas de colaboração de multiagentes, projetado para ajudar os desenvolvedores a melhorar a qualidade do seu código.","ru":"Тестировщик QA от Shaul Corporation - это плагин Claude Code для систем сотрудничества мультиагентов, предназначенный для помощи разработчикам в улучшении качества их кода.","ar":"أداة اختبار الجودة من Shaul Corporation هي إضافة Claude Code لأنظمة التعاون المتعددة الوكلاء، مصممة للمساعدة المطورين على تحسين جودة كودهم.","en":"Shaul Corporation 멀티에이전트 협업 시스템 - Claude Code 플러그인"},"seo":{"title":{"zh":"AI智能工具 - qa-tester测试工具","ja":"AIエージェント - qa-testerテストツール","ko":"AI 에이전트 - qa-tester 테스트 도구","es":"Herramientas de pruebas de QA con Agentes de IA","fr":"Outils de test QA avec Agents d''IA","de":"QA-Test-Tools mit KI-Agents","pt":"Ferramentas de QA: T