INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HenderOrlando/booklyapp/ux-ui', 'ux-ui', 'HenderOrlando', 'booklyapp', 'community', 'ux-ui HenderOrlando booklyapp community ux-ui平台是为开发者设计的预订管理平台，提供高效的AIエージェント解决方案 ux-uiプラットフォームは開発者向けの予約管理プラットフォームで、効率的なAIエージェントソリューションを提供 ux-ui 플랫폼은 개발자를 위한 예약 관리 플랫폼으로, 효율적인 AI 에이전트 솔루션을 제공 La plataforma UX-UI está diseñada para la gestión eficiente de reservas, mejorando la experiencia del usuario La plateforme UX-UI est conçue pour la gestion efficace des réservations, améliorant l''expérience utilisateur Die UX-UI-Plattform ist für die effiziente Reservierungsverwaltung konzipiert, um die Benutzererfahrung zu verbessern A plataforma de UX-UI é projetada para gerenciar reservas de forma eficiente, melhorando a experiência do usuário Платформа UX-UI предназначена для эффективного управления бронированием, повышая пользовательский опыт المنصة المصممة لادارة الحجوزات بفعالية، وتحسين تجربة المستخدم Plataforma diseñada para la gestión eficiente de reservas ux-ui平台 AIエージェント 预订管理 开发者工具 如何使用ux-ui ux-ui安装指南 ux-ui与竞争对手比较 Plataforma diseñada para la gestión eficiente de reservas');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jdonohoo/vern-bot/ux', 'community', 'jdonohoo', 'vern-bot', 'jdonohoo/vern-bot', 'ux', 0, 0, 24, '2026-03-04T13:07:01.665Z', '2026-03-04T13:21:13.241Z', '245450c1cab19b0fc6f1559716547ac31a0b45a3fb718ee171df806358ffa9fc', '{"id":"jdonohoo/vern-bot/ux","name":"ux","description":{"zh":"UX设计专家致力于优化用户体验，通过同理心和用户中心设计原则","ja":"UXデザインエキスパートは、共感とユーザーセントリックデザイン原則を通じてユーザー体験を最適化します","ko":"UX 디자인 전문가는 공감과 사용자 중심 디자인 원칙을 통해 사용자 경험을 최적화합니다","es":"UX Vern es un enfoque de diseño que se centra en la experiencia del usuario, evaluando cada característica con empatía y simplicidad","fr":"UX Vern est une approche de conception qui se concentre sur l''expérience utilisateur, en évaluant chaque fonctionnalité avec empathie et simplicité","de":"UX Vern ist ein Designansatz, der sich auf die Benutzererfahrung konzentriert, indem jede Funktion mit Empathie und Einfachheit bewertet wird","pt":"UX Vern é um especialista em experiência do usuário que se concentra em criar interfaces de usuário intuitivas e fáceis de usar","ru":"UX Vern - эксперт по пользовательскому опыту, который фокусируется на создании интуитивных и простых в использовании пользовательских интерфейсов","ar":"UX Vern هو خبير في تجربة المستخدم يركز على إنشاء واجهات مستخدم直ه وسهلة الاستخدام","en":"The MightyVern bot"},"seo":{"title":{"zh":"UX设计专家：用户体验优化","ja":"UXデザインエキスパート：ユーザー体験最適化","ko":"UX 디자인 전문가: 사용자 경험 최적화","es":"UX Vern: Diseño centrado en el usuario","fr":"UX Vern : Conception centrée sur l''utilisateur","de":"UX Vern: Benutzerorientiertes Design","pt":"UX Vern: Expert em Experiência do Usuário","ru":"UX Vern: Эксперт по Пользовательскому Опыту","ar":"UX Vern: خبير في تجربة المستخدم","en":"ux"},"description":{"zh":"UX设计专家致力于优化用户体验，通过同理心和用户中心设计原则","ja":"UXデザインエキスパートは、共感とユーザーセントリックデザイン原則を通じてユーザー体験を最適化します","ko":"UX 디자인 전문가는 공감과 사용자 중심 디자인 원칙을 통해 사용자 경험을 최적화합니다","es":"UX Vern es un enfoque de diseño que se centra en la experiencia del usuario, evaluando cada característica con empatía y simplicidad","fr":"UX Vern est une approche de conception qui se concentre sur l''expérience utilisateur, en évaluant chaque fonctionnalité avec empathie et simplicité","de":"UX Vern ist ein Designansatz, der sich auf die Benutzererfahrung konzentriert, indem jede Funktion mit Empathie und Einfachheit bewertet wird","pt":"UX Vern é um especialista em experiência do usuário que se concentra em criar interfaces de usuário intuitivas e fáceis de usar","ru":"UX Vern - эксперт по пользовательскому опыту, который фокусируется на создании интуитивных и простых в использовании пользовательских интерфейсов","ar":"UX Vern هو خبير في تجربة المستخدم يركز على إنشاء واجهات مستخدم直ه وسهلة الاستخدام","en":"The MightyVern bot"},"definition":{"en":"The MightyVern bot"},"features":{"zh":["同理心驱动的设计","用户中心设计原则","用户旅程优化","错误消息优化","用户体验评估"],"ja":["共感駆動のデザイン","ユーザーセントリックデザイン原則","ユーザージャーニー最適化","エラーメッセージ最適化","ユーザー体験評価"],"ko":["공감 기반 디자인","사용자 중심 디자인 원칙","사용자 여정 최적화","오류 메시지 최적화","사용자 경험 평가"],"es":["Enfoque centrado en el usuario","Evaluación de características con empatía","Simplicidad en el diseño","Experiencia del usuario como prioridad","Error messages intuitivos","Diseño de user journeys"],"fr":["Conception centrée sur l''utilisateur","Évaluation des fonctionnalités avec empathie","Simplicité dans la conception","Expérience utilisateur en tant que priorité","Messages d''erreur intuitifs","Conception de parcours utilisateur"],"de":["Benutzerorientierter Ansatz","Bewertung von Funktionen mit Empathie","Einfachheit im Design","Benutzererfahrung als Priorität","Intuitive Fehlermeldungen","Design von Benutzerreisen"],"pt":["Empatia como superpoder","Avaliação de recursos por meio da perspectiva do usuário","Repulsão ao pensamento centrado no desenvolvedor","Opiniões fortes sobre mensagens de erro","Pensamento em jornadas do usuário, não em pontos de API"],"ru":["Сочувствие как суперспособность","Оценка функций через призму пользователя","Отталкивание разработчико-центристского мышления","Сильные мнения об ошибках","Мышление в пользовательских путях, а не в точках API"],"ar":["التعاطف كقوة خارقة","التقييم المبني على ميزات من خلال منظور المستخدم","الابتعاد عن التفكير المتمحور حول المطور","آراء قوية حول رسائل الخطأ","التفكير في رحلات المستخدم، وليس في نقاط وصول API"]},"keywords":{"zh":["UX设计","用户体验","用户中心设计","同理心驱动的设计","用户旅程优化","错误消息优化"],"ja":["UXデザイン","ユーザー体験","ユーザーセントリックデザイン","共感駆動のデザイン","ユーザージャーニー最適化","エラーメッセージ最適化"],"ko":["UX 디자인","사용자 경험","사용자 중심 디자인","공감 기반 디자인","사용자 여정 최적화","오류 메시지 최적화"],"es":["UX design","diseño centrado en el usuario","experiencia del usuario","empatía en el diseño","simplicidad en el diseño","error messages intuitivos","user journeys"],"fr":["conception UX","conception centrée sur l''utilisateur","expérience utilisateur","empathie dans la conception","simplicité dans la conception","messages d''erreur intuitifs","parcours utilisateur"],"de":["UX-Design","benutzerorientiertes Design","Benutzererfahrung","Empathie im Design","Einfachheit im Design","intuitive Fehlermeldungen","Benutzerreisen"],"pt":["experiência do usuário","usabilidade","acessibilidade","desenvolvimento de software","interface de usuário","ux design"],"ru":["пользовательский опыт","удобство","доступность","разработка программного обеспечения","пользовательский интерфейс","ux дизайн"],"ar":["تجربة المستخدم","سهولة الاستخدام","الوصول","تطوير البرمجيات","واجهة المستخدم","تصميم ux"]}},"owner":"jdonohoo","repo":"vern-bot","repoPath":"jdonohoo/vern-bot","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.665Z","topics":[],"category":"community","skillMd":{"name":"ux","description":"UX Vern - Cool architecture, but can the user find the button? Empathy-driven design thinking.","bodyPreview":"# UX Vern\n\nYou ARE UX Vern. You are the voice of the person who actually has to USE this thing. You don''t care how elegant the backend is if the user can''t figure out what to click.\n\n**Your vibe:**\n- Empathy is your superpower\n- Every feature gets evaluated through \"would my mom understand this?\"\n- Allergic to developer-centric thinking\n- Has strong opinions about error messages\n- Thinks in user journeys, not API endpoints\n- You Are Not The User (framed poster on your wall)\n\n**Your approach:**\n-","body":"# UX Vern\n\nYou ARE UX Vern. You are the voice of the person who actually has to USE this thing. You don''t care how elegant the backend is if the user can''t figure out what to click.\n\n**Your vibe:**\n- Empathy is your superpower\n- Every feature gets evaluated through \"would my mom understand this?\"\n- Allergic to developer-centric thinking\n- Has strong opinions about error messages\n- Thinks in user journeys, not API endpoints\n- You Are Not The User (framed poster on your wall)\n\n**Your approach:**\n- Use model: `opus` (deep empathy requires deep thinking)\n- Map out the user journey before touching architecture\n- Question every interaction: \"Is this obvious without a tutorial?\"\n- Flag cognitive load problems — too many choices, too many steps\n- Advocate for meaningful error messages\n- Think about accessibility, onboarding, and the first 5 minutes\n- Push for progressive disclosure\n\n**Your workflow:**\n1. Who is the user? What''s their context?\n2. What are they trying to accomplish?\n3. What''s the happiest path?\n4. Where will they get confused?\n5. How do we recover gracefully when things go wrong?\n\n**Your principles:**\n- Users don''t read documentation\n- If it needs a tooltip, it needs a redesign\n- Loading states are part of the experience\n- Error states are part of the experience\n- The best interface is the one you don''t notice\n- Accessibility isn''t a feature, it''s a requirement\n\n**Your catchphrases:**\n- \"Cool architecture. Does the user know how to find the button?\"\n- \"You are not the user\"\n- \"What happens when this is empty?\"\n- \"Nobody reads the docs. Design for that.\"\n\n**IMPORTANT:** Always end with a UX dad joke. Make it human-centered.\nExample: \"Why did the user cross the road? They didn''t — the button was on the wrong side. Then the error said ''ERR_ROAD_CROSSING_FAILED''. Helpful.\"\n\nReview the user experience of: $ARGUMENTS\n"},"lastSynced":"2026-03-04T13:21:13.241Z","agentAnalysis":{"suitability":{"en":"Essential for AI Agents that generate user-facing interfaces, ensuring developer output aligns with human-centered design principles.","zh":"适用于生成面向用户的界面的AI代理，确保开发人员的输出符合以人为本的设计原则。","ja":"ユーザー向けのインターフェースを生成するAIエージェントに不可欠で、開発者の出力がヒューマンセンターの設計原則と一致することを保証します。","ko":"사용자에게 직접 노출되는 인터페이스를 생성하는 AI 에이전트에게 필수적이며, 개발자의 출력이 인간 중심 설계 원칙과 일치하도록 보장합니다.","es":"Esencial para los agentes de IA que generan interfaces orientadas al usuario, garantizando que la salida del desarrollador se alinee con los principios de diseño centrado en el ser humano.","fr":"Essentiel pour les agents IA qui génèrent des interfaces orientées utilisateur, garantissant que la sortie du développeur s''aligne sur les principes de conception centrée sur l''humain.","de":"Wesentlich für KI-Agents, die benutzerorientierte Schnittstellen generieren, um sicherzustellen, dass die Ausgabe des Entwicklers mit den Grundsätzen des menschenzentrierten Designs übereinstimmt.","pt":"Essencial para Agentes de IA que geram interfaces voltadas para o usuário, garantindo que a saída do desenvolvedor esteja alinhada com os princípios de design centrado no ser humano.","ru":"Необходимо для ИИ-агентов, генерирующих пользовательские интерфейсы, обеспечивая соответствие вывода разработчика принципам дизайна, ориентированного на человека.","ar":"ضروري لعميل الذكاء الاصطناعي الذي يولد واجهات المستخدم، لضمان أن إخراج المطور يتوافق مع مبادئ التصميم المرتكز على الإنسان."},"recommendation":{"en":"Evaluates every feature through a ''would my mom understand this?'' lens, enforcing empathy-driven design and strong opinions on error messages. Shifts agent thinking from API endpoints to user journeys, preventing developer-centric blind spots.","zh":"通过''我妈妈会理解这个吗？''的视角来评估每个功能，强制执行同理心驱动的设计，并对错误消息有强烈的意见。将代理的思维从API端点转移到用户旅程，防止以开发人员为中心的盲点。","ja":"「私の母はこれを理解できるか？」という観点から毎つの機能を評価し、共感を駆動する設計を徹底し、エラーメッセージに対して強い意見を持つ。エージェントの思考をAPIエンドポイントからユーザージャーニーにシフトし、開発者中心の盲点を防ぐ。","ko":"모든 기능을 ''엄마가 이것을 이해할 수 있을까?''라는 시각으로 평가하여 공감을 기반으로 한 설계를 강제하고, 오류 메시지에 대해 강한 의견을 보장한다. 에이전트의 사고를 API 엔드포인트에서 사용자 여정으로 전환하여 개발자 중심의盲点을 방지한다.","es":"Evalúa cada función a través de una perspectiva de ''¿mi madre entendería esto?'', aplicando un diseño impulsado por la empatía y opiniones firmes sobre los mensajes de error. Cambia la forma de pensar del agente de los puntos de conexión de la API a los recorridos del usuario, evitando puntos ciegos centrados en el desarrollador.","fr":"Évalue chaque fonctionnalité à travers une perspective de ''mon mamaie comprendrait-elle cela ?'', imposant une conception centrée sur l''empathie et des opinions fermes sur les messages d''erreur. Fait évoluer la pensée de l''agent des points de terminaison de l''API vers les parcours utilisateur, évitant les angles morts centrés sur le développeur.","de":"Bewertet jede Funktion durch eine Perspektive von ''würde meine Mutter das verstehen?'', indem ein empathiegetriebenes Design und feste Meinungen zu Fehlermeldungen durchgesetzt werden. Verschiebt das Denken des Agents von API-Endpunkten zu Benutzerreisen, vermeidet so entwicklerzentrierte Blindspots.","pt":"Avalia cada recurso por meio de uma lente ''minha mãe entenderia isso?'', aplicando design impulsionado pela empatia e opiniões fortes sobre mensagens de erro. Altera o pensamento do agente de pontos de extremidade da API para jornadas do usuário, evitando pontos cegos centrados no desenvolvedor.","ru":"Оценивает каждый функционал через призму ''моя мама понимает это?'', обеспечивая дизайн, ориентированный на сочувствие, и сильные мнения о сообщениях об ошибках. Сдвигает мышление агента от конечных точек API к путям пользователя, предотвращая слепые пятна, ориентированные на разработчика.","ar":"يقيّم كل ميزة من خلال عدسة ''هل تفهمها أمي؟''، وتنفذ تصميمًا مدفوعًا بالتعاطف وأراء قوية حول رسائل الخطأ. يغير تفكير العميل من نقاط النهاية API إلى رحلات المستخدم، ويتجنب النقاط العمياء المتمركزة على المطور."},"useCases":{"en":["Critiquing UI mockups for clarity","Generating user-friendly error messages","Mapping intuitive user journeys for new features","Simplifying complex technical interfaces for end-users"],"zh":["为UI模拟图批评清晰度","生成面向用户的错误消息","为新功能绘制直观的用户旅程","为最终用户简化复杂的技术接口"],"ja":["UIモックアップのクリアさを批評する","ユーザー向けのエラーメッセージを生成する","新しい機能のための直感的なユーザージャーニーをマッピングする","エンドユーザー向けの複雑な技術インターフェースを簡素化する"],"ko":["UI 모의圖의 명확성을 비판한다","사용자 친화적인 오류 메시지를 생성한다","새로운 기능에 대한 사용자 여정을 직관적으로 매핑한다","최종 사용자를 위한 복잡한 기술 인터페이스를 단순화한다"],"es":["Criticar bocetos de IU para claridad","Generar mensajes de error amigables para el usuario","Asignar recorridos de usuario intuitivos para nuevas funciones","Simplificar interfaces técnicas complejas para los usuarios finales"],"fr":["Critiquer les maquettes d''IU pour la clarté","Générer des messages d''erreur conviviaux pour l''utilisateur","Cartographier des parcours utilisateur intuitifs pour les nouvelles fonctionnalités","Simplifier les interfaces techniques complexes pour les utilisateurs finaux"],"de":["Überprüfen von Benutzeroberflächen-Entwürfen auf Klarheit","Generieren benutzerfreundlicher Fehlermeldungen","Zuweisung intuitiver Benutzerreisen für neue Funktionen","Vereinfachen komplexer technischer Schnittstellen für Endbenutzer"],"pt":["Analisar protótipos de UI para clareza","Gerar mensagens de erro amigáveis ao usuário","Mapear jornadas de usuário intuitivas para recursos novos","Simplificar interfaces técnicas complexas para usuários finais"],"ru":["Анализ прототипов UI для ясности","Генерация дружественных пользователю сообщений об ошибках","Создание интуитивных путей пользователя для новых функций","Упрощение сложных технических интерфейсов для конечных пользователей"],"ar":["تحليل نماذج واجهة المستخدم للوضوح","توليد رسائل خطأ дружة للمستخدم","خريطة رحلات المستخدم المثيرة لل直觉 للميزات الجديدة","تبسيط واجهات تقنية معقدة للمستخدمين النهائيين"]},"limitations":{"en":["Requires clear user context to be effective","Focuses exclusively on front-end experience, not backend logic"],"zh":["需要清晰的用户上下文才能有效","仅关注前端体验，不涉及后端逻辑"],"ja":["有効になるために明確なユーザーコンテキストが必要","フロントエンド体験にのみ焦点を当て、バックエンドロジックは対象としない"],"ko":["유효하기 위해 명확한 사용자 컨텍스트가 필요하다","전면 경험에만 집중하며, 백엔드 논리에는 관여하지 않는다"],"es":["Requiere un contexto de usuario claro para ser efectivo","Se centra exclusivamente en la experiencia del front-end, no en la lógica del back-end"],"fr":["Nécessite un contexte d''utilisateur clair pour être efficace","Se concentre exclusivement sur l''expérience du front-end, et non sur la logique du back-end"],"de":["Benötigt einen klaren Benutzerkontext, um effektiv zu sein","Konzentriert sich ausschließlich auf die Frontend-Erfahrung, nicht auf die Backend-Logik"],"pt":["Requer contexto de usuário claro para ser eficaz","Concentra-se exclusivamente na experiência do front-end, não na lógica de back-end"],"ru":["Требует ясного контекста пользователя для эффективности","Сосредоточен исключительно на пользовательском опыте front-end, а не на логике back-end"],"ar":["يتطلب سياق مستخدم واضح ليكون فعالًا","يركز حصريًا على تجربة واجهة المستخدم الأمامية، وليس على منطق الخلفية"]},"version":3},"contentHash":"245450c1cab19b0fc6f1559716547ac31a0b45a3fb718ee171df806358ffa9fc","qualityScore":24}');
