INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HoangNguyen0403/agent-skills-standard/Android Dependency Injection (Hilt)', 'community', 'HoangNguyen0403', 'agent-skills-standard', 'HoangNguyen0403/agent-skills-standard', 'Android Dependency Injection (Hilt)', 0, 0, 23, '2026-03-04T13:07:01.663Z', '2026-03-04T13:21:01.201Z', 'bdd7edb332382e0fbc3adb087a356c682f7b77dd348735b50de26b068b1fabb6', '{"id":"HoangNguyen0403/agent-skills-standard/Android Dependency Injection (Hilt)","name":"Android Dependency Injection (Hilt)","description":{"zh":"Android 依赖注入（Hilt）是一种用于管理 Android 应用依赖关系的技术，通过提供最佳实践和实现指南来帮助开发者优化应用开发","ja":"Android 依存性注入（Hilt）は、Android アプリの依存関係を管理する技術で、ベストプラクティスと実装ガイドラインを提供して、アプリ開発を最適化します","ko":"Android 의존성 주입(Hilt)은 Android 앱의 의존 관계를 관리하는 기술로, 모범 사례와 구현 지침을 제공하여 앱 개발을 최적화합니다","es":"Hilt es un framework de inyección de dependencias para Android que simplifica la gestión de dependencias en tus aplicaciones","fr":"Hilt est un framework d''injection de dépendances pour Android qui simplifie la gestion des dépendances dans vos applications","de":"Hilt ist ein Framework für die Abhängigkeitsinjektion in Android, das die Verwaltung von Abhängigkeiten in Ihren Anwendungen vereinfacht","pt":"A injeção de dependência Android com Hilt é uma técnica para gerenciar dependências entre componentes, melhorando a manutenção e escalabilidade do aplicativo","ru":"Внедрение зависимостей Android с Hilt - это техника для управления зависимостями между компонентами, улучшая поддержку и масштабируемость приложения","ar":"حقن الاعتماديات أندرويد مع هيلت هو تقنية لإدارة الاعتماديات بين المكونات، وتحسين صيانة وتوسيع التطبيق","en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and programming laguages"},"seo":{"title":{"zh":"Android 依赖注入（Hilt）","ja":"Android 依存性注入（Hilt）","ko":"Android 의존성 주입(Hilt)","es":"Inyección de Dependencias Android con Hilt","fr":"Injection de Dépendances Android avec Hilt","de":"Android-Abhängigkeitsinjektion mit Hilt","pt":"Injeção de Dependência Android com Hilt","ru":"Внедрение зависимостей Android с Hilt","ar":"حقن الاعتماديات أندرويد مع هيلت","en":"Android Dependency Injection (Hilt)"},"description":{"zh":"Android 依赖注入（Hilt）是一种用于管理 Android 应用依赖关系的技术，通过提供最佳实践和实现指南来帮助开发者优化应用开发","ja":"Android 依存性注入（Hilt）は、Android アプリの依存関係を管理する技術で、ベストプラクティスと実装ガイドラインを提供して、アプリ開発を最適化します","ko":"Android 의존성 주입(Hilt)은 Android 앱의 의존 관계를 관리하는 기술로, 모범 사례와 구현 지침을 제공하여 앱 개발을 최적화합니다","es":"Hilt es un framework de inyección de dependencias para Android que simplifica la gestión de dependencias en tus aplicaciones","fr":"Hilt est un framework d''injection de dépendances pour Android qui simplifie la gestion des dépendances dans vos applications","de":"Hilt ist ein Framework für die Abhängigkeitsinjektion in Android, das die Verwaltung von Abhängigkeiten in Ihren Anwendungen vereinfacht","pt":"A injeção de dependência Android com Hilt é uma técnica para gerenciar dependências entre componentes, melhorando a manutenção e escalabilidade do aplicativo","ru":"Внедрение зависимостей Android с Hilt - это техника для управления зависимостями между компонентами, улучшая поддержку и масштабируемость приложения","ar":"حقن الاعتماديات أندرويد مع هيلت هو تقنية لإدارة الاعتماديات بين المكونات، وتحسين صيانة وتوسيع التطبيق","en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and p..."},"definition":{"en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and programming laguages"},"features":{"zh":["使用 @HiltAndroidApp 注解 Application 类","使用 @AndroidEntryPoint 注解 Activity 和 Fragment","使用 @Binds 代替 @Provides","显式指定 InstallIn","优先使用构造函数注入"],"ja":["Application クラスに @HiltAndroidApp アノテーションを使用","Activity と Fragment に @AndroidEntryPoint アノテーションを使用"," @Provides の代わりに @Binds を使用","InstallIn を明示的に指定","コンストラクタ注入を優先する"],"ko":["Application 클래스에 @HiltAndroidApp 注解 사용","Activity 및 Fragment에 @AndroidEntryPoint 注解 사용"," @Provides 대신 @Binds 사용","InstallIn을 명시적으로 지정","생성자 주입을 우선 사용"],"es":["Simplifica la gestión de dependencias","Mejora la calidad del código","Reduce la complejidad","Soporte para la inyección de dependencias en Activities y Fragments","Uso de anotaciones para la configuración"],"fr":["Simplifie la gestion des dépendances","Améliore la qualité du code","Réduit la complexité","Prise en charge de l''injection de dépendances dans les Activities et les Fragments","Utilisation d''annotations pour la configuration"],"de":["Vereinfacht die Verwaltung von Abhängigkeiten","Verbessert die Code-Qualität","Reduziert die Komplexität","Unterstützung für die Abhängigkeitsinjektion in Activities und Fragments","Verwendung von Annotationen für die Konfiguration"],"pt":["Setup com @HiltAndroidApp","Uso de @AndroidEntryPoint","Módulos com @Binds e @Provides","Injeção de construtor","Suporte a SingletonComponent e ViewModelComponent"],"ru":["Настройка с @HiltAndroidApp","Использование @AndroidEntryPoint","Модули с @Binds и @Provides","Внедрение конструктора","Поддержка SingletonComponent и ViewModelComponent"],"ar":["إعداد مع @HiltAndroidApp","استخدام @AndroidEntryPoint","وحدات مع @Binds و @Provides","حقن البناء","دعم SingletonComponent و ViewModelComponent"]},"keywords":{"zh":["Android 依赖注入","Hilt","依赖关系管理","Android 应用开发","最佳实践","实现指南"],"ja":["Android 依存性注入","Hilt","依存関係管理","Android アプリ開発","ベストプラクティス","実装ガイドライン"],"ko":["Android 의존성 주입","Hilt","의존 관계 관리","Android 앱 개발","모범 사례","구현 지침"],"es":["inyección de dependencias","Hilt","Android","desarrollo de aplicaciones","patrones de diseño","calidad del código","complejidad","Activities","Fragments"],"fr":["injection de dépendances","Hilt","Android","développement d''applications","patrons de conception","qualité du code","complexité","Activities","Fragments"],"de":["Abhängigkeitsinjektion","Hilt","Android","Anwendungsentwicklung","Entwurfsmuster","Code-Qualität","Komplexität","Activities","Fragments"],"pt":["injeção de dependência android","hilt android","dependência android","injeção de construtor","singletoncomponent","viewmodelcomponent","desenvolvimento android","programação android"],"ru":["внедрение зависимостей android","hilt android","зависимость android","внедрение конструктора","singletoncomponent","viewmodelcomponent","разработка android","программирование android"],"ar":["حقن الاعتماديات أندرويد","هيلت أندرويد","اعتماديات أندرويد","حقن البناء","singletoncomponent","viewmodelcomponent","تطوير أندرويد","برمجة أندرويد"]}},"owner":"HoangNguyen0403","repo":"agent-skills-standard","repoPath":"HoangNguyen0403/agent-skills-standard","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.663Z","topics":[],"category":"community","skillMd":{"name":"Android Dependency Injection (Hilt)","description":"Standards for Hilt Setup, Scoping, and Modules","bodyPreview":"# Android Dependency Injection (Hilt)\n\n## **Priority: P0**\n\n## Implementation Guidelines\n\n### Setup\n\n- **App**: Must annotate `Application` class with `@HiltAndroidApp`.\n- **Entries**: Annotate Activities/Fragments with `@AndroidEntryPoint`.\n\n### Modules\n\n- **Binding**: Use `@Binds` (abstract class) over `@Provides` when possible (smaller generated code).\n- **InstallIn**: Be explicit (`SingletonComponent`, `ViewModelComponent`).\n\n### Construction\n\n- **Constructor Injection**: Prefer over Field I","body":"# Android Dependency Injection (Hilt)\n\n## **Priority: P0**\n\n## Implementation Guidelines\n\n### Setup\n\n- **App**: Must annotate `Application` class with `@HiltAndroidApp`.\n- **Entries**: Annotate Activities/Fragments with `@AndroidEntryPoint`.\n\n### Modules\n\n- **Binding**: Use `@Binds` (abstract class) over `@Provides` when possible (smaller generated code).\n- **InstallIn**: Be explicit (`SingletonComponent`, `ViewModelComponent`).\n\n### Construction\n\n- **Constructor Injection**: Prefer over Field Injection (`@Inject constructor(...)`).\n- **Assisted Injection**: Use for runtime parameters (`@AssistedInject`).\n\n## Anti-Patterns\n\n- **Component Manual Creation**: `**No Manual Dagger**: Use Hilt Standard.`\n- **Field Inject in Logic**: `**No Field Inject**: Only in Android Components.`\n\n## References\n\n- [Module Templates](references/files.md)\n"},"lastSynced":"2026-03-04T13:21:01.201Z","agentAnalysis":{"suitability":{"en":"Ideal for Android Development Agents requiring efficient dependency management using Hilt.","zh":"适用于需要使用Hilt进行高效依赖管理的Android开发代理。","ja":"Hiltを使用した依存関係管理が効率的なAndroid開発エージェントに適しています。","ko":"Hilt를 사용하여 효율적인 종속성 관리가 필요한 Android 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo de Android que requieren un manejo de dependencias eficiente utilizando Hilt.","fr":"Idéal pour les agents de développement Android nécessitant une gestion de dépendances efficace à l''aide de Hilt.","de":"Ideal für Android-Entwicklungsagenten, die eine effiziente Abhängigkeitsverwaltung mit Hilt erfordern.","pt":"Ideal para Agentes de Desenvolvimento Android que requerem gerenciamento de dependência eficiente usando Hilt.","ru":"Идеально для агентов разработки Android, требующих эффективного управления зависимостями с помощью Hilt.","ar":"مثالي لعميل التطوير الأندرويد الذي يتطلب إدارة التبعيات الفعالة باستخدام Hilt."},"recommendation":{"en":"Empowers agents to implement modular and scalable Android applications by leveraging Hilt''s dependency injection capabilities, utilizing @HiltAndroidApp, @AndroidEntryPoint, and @Binds for optimized module binding, and preferring constructor injection over field injection for better testability.","zh":"通过利用Hilt的依赖注入功能，使用@HiltAndroidApp、@AndroidEntryPoint和@Binds进行优化的模块绑定，并且更喜欢构造函数注入而不是字段注入以获得更好的测试性，从而使代理能够实现模块化和可扩展的Android应用程序。","ja":"Hiltの依存関係注入機能を活用し、@HiltAndroidApp、@AndroidEntryPoint、@Bindsを使用して最適化されたモジュールバインディングを行い、フィールド注入よりもコンストラクタ注入を優先してテスト性を高めることで、モジュラーでスケーラブルなAndroidアプリケーションの実装をエージェントに可能にします。","ko":"Hilt의 종속성 주입 기능을 활용하여 @HiltAndroidApp, @AndroidEntryPoint 및 @Binds를 사용하여 최적화된 모듈 바인딩을 수행하고 필드 주입보다 생성자 주입을 선호하여 테스트 가능성을 개선함으로써 에이전트가 모듈화되고 확장 가능한 Android 애플리케이션을 구현할 수 있도록 합니다.","es":"Habilita a los agentes a implementar aplicaciones Android modulares y escalables aprovechando las capacidades de inyección de dependencias de Hilt, utilizando @HiltAndroidApp, @AndroidEntryPoint y @Binds para una vinculación de módulos optimizada, y prefiriendo la inyección de constructores sobre la inyección de campos para una mejor capacidad de prueba.","fr":"Permet aux agents de mettre en œuvre des applications Android modulaires et évolutives en exploitant les capacités d''injection de dépendances de Hilt, en utilisant @HiltAndroidApp, @AndroidEntryPoint et @Binds pour un lien de module optimisé, et en préférant l''injection de constructeurs à l''injection de champs pour une meilleure testabilité.","de":"Ermächtigt Agenten, modulare und skalierbare Android-Anwendungen zu implementieren, indem sie die Abhängigkeitsinjektionsfunktionen von Hilt nutzen, @HiltAndroidApp, @AndroidEntryPoint und @Binds für eine optimierte Modulbindung verwenden und die Konstruktorinjektion der Feldinjektion für eine bessere Testbarkeit vorziehen.","pt":"Habilita os agentes a implementar aplicações Android modulares e escaláveis, aproveitando as capacidades de injeção de dependência do Hilt, utilizando @HiltAndroidApp, @AndroidEntryPoint e @Binds para vinculação de módulos otimizados, e preferindo injeção de construtor em vez de injeção de campo para melhor testabilidade.","ru":"Наделяет агентов возможностью реализовывать модульные и масштабируемые приложения Android, используя возможности внедрения зависимостей Hilt, используя @HiltAndroidApp, @AndroidEntryPoint и @Binds для оптимизированного связывания модулей, и предпочитая конструкторное внедрение вместо внедрения полей для лучшей тестируемости.","ar":"تمكين الوكيل من تنفيذ تطبيقات الأندرويد القابلة للتحديث ومتعددة الحجم من خلال الاستفادة من قابليات حقن التبعيات الخاصة bằng Hilt، باستخدام @HiltAndroidApp و @AndroidEntryPoint و @Binds من أجل ربط الوحدات الأمثل، وتفضيل حقن البناء على حقن الحقل من أجل قابلية الاختبار الأفضل."},"useCases":{"en":["Configuring Hilt for Android applications","Implementing modular dependencies using @Binds and @Provides","Optimizing application performance through singleton and view model components"],"zh":["为Android应用程序配置Hilt","使用@Binds和@Provides实现模块化依赖","通过单例和视图模型组件优化应用程序性能"],"ja":["Androidアプリケーション用にHiltを構成する","@Bindsと@Providesを使用してモジュラーな依存関係を実装する","シングルトンとビューモデルコンポーネントを使用してアプリケーションのパフォーマンスを最適化する"],"ko":["Android 애플리케이션에 Hilt를 구성하는 것","@Binds 및 @Provides를 사용하여 모듈화된 종속성을 구현하는 것","싱글톤 및 뷰 모델 컴포넌트를 사용하여 애플리케이션 성능을 최적화하는 것"],"es":["Configuración de Hilt para aplicaciones Android","Implementación de dependencias modulares utilizando @Binds y @Provides","Optimización del rendimiento de la aplicación a través de componentes singleton y de modelo de vista"],"fr":["Configuration de Hilt pour les applications Android","Mise en œuvre de dépendances modulaires à l''aide de @Binds et @Provides","Optimisation des performances de l''application via des composants singleton et de modèle de vue"],"de":["Konfiguration von Hilt für Android-Anwendungen","Implementierung modularer Abhängigkeiten mit @Binds und @Provides","Optimierung der Anwendungsleistung durch Singleton- und View-Model-Komponenten"],"pt":["Configurando Hilt para aplicações Android","Implementando dependências modulares usando @Binds e @Provides","Otimizando o desempenho da aplicação por meio de componentes singleton e view model"],"ru":["Настройка Hilt для приложений Android","Реализация модульных зависимостей с помощью @Binds и @Provides","Оптимизация производительности приложения с помощью компонентов singleton и view model"],"ar":["تكوين Hilt للتطبيقات الأندرويد","تنفيذ التبعيات القابلة للتحديث باستخدام @Binds و @Provides","تحسين أداء التطبيق من خلال المكونات الفردي والنموذج العارض"]},"limitations":{"en":["Requires Android development environment","Hilt-specific annotations and configuration","Android-specific implementation guidelines"],"zh":["需要Android开发环境","Hilt特定的注释和配置","Android特定的实现指南"],"ja":["Android開発環境が必要","Hilt固有のアノテーションと構成","Android固有の実装ガイドライン"],"ko":["Android 개발 환경이 필요함","Hilt 특정 어노테이션 및 구성","Android 특정 구현 가이드라인"],"es":["Requiere un entorno de desarrollo de Android","Annotaciones y configuración específicas de Hilt","Directrices de implementación específicas de Android"],"fr":["Nécessite un environnement de développement Android","Annotations et configuration spécifiques à Hilt","Lignes directrices d''implémentation spécifiques à Android"],"de":["Benötigt eine Android-Entwicklungsumgebung","Hilt-spezifische Annotationen und Konfiguration","Android-spezifische Implementierungsrichtlinien"],"pt":["Requer ambiente de desenvolvimento Android","Anotações e configuração específicas do Hilt","Diretrizes de implementação específicas do Android"],"ru":["Требуется среда разработки Android","Hilt-специфические аннотации и конфигурация","Android-специфические рекомендации по реализации"],"ar":["يتطلب بيئة تطوير الأندرويد","تعليقات وضبط خاص بالهيلت","إرشادات تنفيذ خاصة بالأندرويد"]},"version":3},"contentHash":"bdd7edb332382e0fbc3adb087a356c682f7b77dd348735b50de26b068b1fabb6","qualityScore":23}');
