INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('workadventure/workadventure/translate', 'translate', 'workadventure', 'workadventure', 'community', 'translate workadventure workadventure community AI智能翻译工具是一个协作web应用，采用16-bit RPG视频游戏风格，实现虚拟办公协作 AIエージェントの翻訳機能は、16ビットRPG風のコラボレーションを提供するウェブアプリケーション AI 에이전트 번역 기능은 16비트 RPG 스타일의 협업 플랫폼을 제공하는 웹 애플리케이션 La herramienta de traducción es una aplicación web colaborativa presentada como un juego de RPG de 16 bits, ideal para desarrolladores que buscan innovar en la colaboración en línea L''outil de traduction est une application web collaborative présentée comme un jeu de RPG 16 bits, idéal pour les développeurs qui cherchent à innover dans la collaboration en ligne Das Übersetzungstool ist eine kollaborative Webanwendung, die als 16-bit-RPG-Spiel präsentiert wird, ideal für Entwickler, die die Online-Kollaboration innovativ gestalten möchten Uma aplicação web colaborativa apresentada como um jogo de RPG de 16 bits, com capacidades de tradução avançadas Совместное веб-приложение, представленное как 16-битная RPG игра, с возможностями перевода تطبيق ويب تعاوني مقدم كلعبة RPG بنظام 16 بت، مع قدرات ترجمة متقدمة A collaborative web application (virtual office) presented as a 16-bit RPG video game AI智能翻译工具 虚拟办公协作平台 16-bit RPG视频游戏风格 如何使用AI翻译工具 AI翻译工具安装 AI翻译工具设置指南 AI翻译工具替代品 AI翻译工具与其他工具的比较 A collaborative web application (virtual office) presented as a 16-bit RPG video game');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zylos-ai/zylos-core/scheduler', 'community', 'zylos-ai', 'zylos-core', 'zylos-ai/zylos-core', 'scheduler', 0, 0, 23, '2026-03-04T13:07:01.760Z', '2026-03-04T14:15:22.869Z', 'a377be3231b1212f1afdc367c0dd0bcffc57ed969ef350ceca775da8b4ea576c', '{"id":"zylos-ai/zylos-core/scheduler","name":"scheduler","description":{"zh":"开源基础设施，用于构建持久自维护的AI伴侣。由Claude Code驱动","ja":"自己維持型AIコンパニオンを構築するためのオープンソースインフラストラクチャ。Claude Codeによって提供","ko":"지속적 自己유지 AI 동행자를 구축하기 위한 오픈소스 인프라스트럭처입니다. Claude Code에 의해 구동됩니다","es":"El agendador de agentes de IA es una infraestructura de código abierto para crear compañeros de IA autónomos y persistentes","fr":"Le planificateur d''agents d''IA est une infrastructure open-source pour créer des compagnons d''IA autonomes et persistants","de":"Der AI-Agent-Terminplaner ist eine Open-Source-Infrastruktur für die Erstellung autarker und persistenter AI-Komponenten","pt":"O agendador de IA é uma infraestrutura de código aberto para criar companheiros de IA persistentes e auto-mantidos, impulsionados pelo Claude Code","ru":"Планировщик ИИ Агентов - это открытая инфраструктура для создания самообслуживающихся ИИ компаньонов, работающих на Claude Code","ar":"مقرر جدول أعمال الإيمان العصبي هو بنية مفتوحة المصدر لإنشاء رفاق الذكاء الاصطناعي المستدامين والذين ي維عون أنفسهم، مدعومة بواسطة Claude Code","en":"Give your AI a life — open-source infrastructure for persistent, self-maintaining AI companions. Powered by Claude Code."},"seo":{"title":{"zh":"AI智能调度器 - 持久自维护AI伴侣","ja":"AIエージェントスケジューラー - 自己維持型AIコンパニオン","ko":"AI 스케줄러 - 지속적 自己유지 AI 동행자","es":"Agendador de Agentes de IA - Infraestructura de código ab...","fr":"Planificateur d''Agents d''IA - Infrastructure open-source","de":"AI-Agent-Terminplaner - Open-Source-Infrastruktur","pt":"Agendador de IA: Infraestrutura de código aberto para com...","ru":"Планиров