INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zylos-ai/zylos-core/scheduler', 'scheduler', 'zylos-ai', 'zylos-core', 'community', 'scheduler zylos-ai zylos-core community 开源基础设施，用于构建持久自维护的AI伴侣。由Claude Code驱动 自己維持型AIコンパニオンを構築するためのオープンソースインフラストラクチャ。Claude Codeによって提供 지속적 自己유지 AI 동행자를 구축하기 위한 오픈소스 인프라스트럭처입니다. Claude Code에 의해 구동됩니다 El agendador de agentes de IA es una infraestructura de código abierto para crear compañeros de IA autónomos y persistentes Le planificateur d''agents d''IA est une infrastructure open-source pour créer des compagnons d''IA autonomes et persistants Der AI-Agent-Terminplaner ist eine Open-Source-Infrastruktur für die Erstellung autarker und persistenter AI-Komponenten O agendador de IA é uma infraestrutura de código aberto para criar companheiros de IA persistentes e auto-mantidos, impulsionados pelo Claude Code Планировщик ИИ Агентов - это открытая инфраструктура для создания самообслуживающихся ИИ компаньонов, работающих на Claude Code مقرر جدول أعمال الإيمان العصبي هو بنية مفتوحة المصدر لإنشاء رفاق الذكاء الاصطناعي المستدامين والذين ي維عون أنفسهم، مدعومة بواسطة Claude Code Give your AI a life — open-source infrastructure for persistent, self-maintaining AI companions. Powered by Claude Code. AI调度器 开源基础设施 持久自维护AI伴侣 Claude Code 自己维护AI AI工具 AIエージェント 如何使用AI调度器 AI调度器安装 Give your AI a life — open-source infrastructure for persistent, self-maintaining AI companions. Powered by Claude Code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('evanfang0054/cc-system-creator-scripts/doc-learner', 'community', 'evanfang0054', 'cc-system-creator-scripts', 'evanfang0054/cc-system-creator-scripts', 'doc-learner', 0, 0, 23, '2026-03-04T13:07:01.765Z', '2026-03-04T14:17:09.731Z', '88f83f870c79b2a98a1216b872815788072950b1e89c5b3b957bc92d187f4737', '{"id":"evanfang0054/cc-system-creator-scripts/doc-learner","name":"doc-learner","description":{"zh":"doc-learner技能是一个元框架，用于增强Claude Code的功能，通过模块化和自动化工作流创建专业级AI技能","ja":"doc-learnerスキルはメタフレームワークで、Claude Codeの機能を強化し、モジュール化と自動化されたワークフローでプロフェッショナルなAIスキルを作成します","ko":"doc-learner 기술은 메타 프레임워크로서 Claude Code의 기능을 강화하고, 모듈화와 자동화된 워크플로우로 전문가급 AI 기술을 생성합니다","es":"doc-learner es un sistema de creación de scripts para Claude Code que permite crear habilidades de IA de nivel profesional y gestionar flujos de trabajo complejos","fr":"doc-learner est un système de création de scripts pour Claude Code qui permet de créer des compétences d''IA de niveau professionnel et de gérer des flux de travail complexes","de":"doc-learner ist ein System zur Erstellung von Skripten für Claude Code, das die Erstellung von KI-Fähigkeiten auf professionellem Niveau und die Verwaltung komplexer Workflows ermöglicht","pt":"O doc-learner é um metquadro de trabalho para Claude Code que permite criar agentes de IA profissionais","ru":"ИИ Агент doc-learner - мета-фреймворк для создания профессиональных AI-навыков и управления агентами","ar":"أداة الذكاء الاصطناعي doc-learner هي إطار عمل لإنشاء وكلاء كلود كود المحترفين","en":"CC System Creator Scripts是一个专门为 Claude Code 设计的元框架，通过模块化、可重用的组件和自动化工作流来增强其功能。该系统让您能够创建专业级 AI 技能、管理专业化的代理，并编排复杂的多代理工作流"},"seo":{"title":{"zh":"AI智能代理doc-learner技能","ja":"AIエージェントdoc-learnerスキル","ko":"AI 에이전트doc-learner 기술","es":"Herramientas de Agente de IA: doc-learner","fr":"Outils d''Agent IA: doc-learner","de":"KI-Agent-Tool