INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('liqiongyu/agentpack/agentpack-dev', 'agentpack-dev', 'liqiongyu', 'agentpack', 'community', 'agentpack-dev liqiongyu agentpack community Agentpack-dev是一个声明式的、安全的控制平面，用于跨工具部署编码代理资产 Agentpack-devは、ツール間でコードエージェント資産をデプロイするための宣言的かつ安全なコントロールプレーンです Agentpack-dev는 코드 에이전트 자산을 도구 간에 배포하기 위한 선언적이고 안전한 제어 평면입니다 Agentpack-dev es una plataforma de control declarativa y segura para implementar activos de agentes de código en herramientas Agentpack-dev est un plan de contrôle déclaratif et sûr pour déployer des actifs d''agents de codage dans les outils Agentpack-dev ist eine declarative und sichere Steuerungsebene für die Bereitstellung von Codierungs-Agents-Assets in Tools O AgentPack-Dev é uma plataforma de controle declarativa e segura para implantar ativos de codificação em ferramentas de desenvolvimento. ИИ Агенты AgentPack-Dev - это декларативная, безопасная система управления для развертывания активов кодирования в инструментах разработки. AgentPack-Dev هو طائرة تحكم إعلانية وآمنة لنشر أدوات البرمجة عبر أدوات التطوير. A declarative, safe control plane for deploying coding-agent assets across tools. AI代理开发 Agentpack-dev教程 代码代理资产部署 安全控制平面 跨工具部署 开发效率提升 Agentpack-dev安装 Agentpack-dev设置指南 A declarative, safe control plane for deploying coding-agent assets across tools.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('duplojs/utils/writeJsDoc', 'community', 'duplojs', 'utils', 'duplojs/utils', 'writeJsDoc', 0, 0, 23, '2026-03-04T13:07:01.793Z', '2026-03-04T14:27:40.283Z', '53138168575820c00a4a1c9387ea4274228653deabcf7a5eb74fe1e4eaa12e81', '{"id":"duplojs/utils/writeJsDoc","name":"writeJsDoc","description":{"zh":"writeJsDoc是DuploJS生态系统的TypeScript工具箱，专注于强大的类型定义和小型可组合的原语","ja":"writeJsDocはDuploJSエコシステムのTypeScriptユーティリティボックスで、強い型定義と小さな組み合わせ可能なプリミティブに焦点を当てています","ko":"writeJsDoc는 DuploJS 생태계의 TypeScript 유틸리티 툴박스로서, 강력한 타입 정의와 작은 구성 가능한 원시 값을 제공합니다","es":"writeJsDoc es una herramienta de AI que utiliza @duplojs/utils para mejorar la documentación de JavaScript con una fuerte tipificación y buen DX","fr":"writeJsDoc est un outil d''IA qui utilise @duplojs/utils pour améliorer la documentation JavaScript avec une forte typification et un bon DX","de":"writeJsDoc ist ein KI-Tool, das @duplojs/utils verwendet, um die JavaScript-Dokumentation mit starker Typisierung und gutem DX zu verbessern","pt":"O writeJsDoc é uma ferramenta de IA que utiliza @duplojs/utils para melhorar a documentação de código JavaScript, focando em tipagem forte e DX.","ru":"ИИ Агент writeJsDoc использует @duplojs/utils для улучшения документации кода JavaScript, фокусируясь на сильной типизации и DX.","ar":"أداة الذكاء الاصطناعي writeJsDoc تستخدم @duplojs/utils لتحسين توثيق код جافاسكريبت، مع التركيز على التصنيف القوي و DX.","en":"@duplojs/utils is the TypeScript utility toolbox used across the DuploJS ecosystem. It focuses on strong typing, good DX, and small composable primitives that scale from simple helpers to full validation pipelines."},"seo":{"title":{"zh":"AI工具：writeJsDoc - DuploJS生态系统的TypeScript工具箱","ja":"AIエージェント：writeJsDoc - DuploJSエコシステムのTypeScriptユーティリティボックス","ko":"AI 에이전트: writeJsDoc - DuploJS 생태계의 TypeScript 유틸리티 툴박스","es":"Herramientas de A