INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('duplojs/utils/writeJsDoc', 'writeJsDoc', 'duplojs', 'utils', 'community', 'writeJsDoc duplojs utils community writeJsDoc是DuploJS生态系统的TypeScript工具箱，专注于强大的类型定义和小型可组合的原语 writeJsDocはDuploJSエコシステムのTypeScriptユーティリティボックスで、強い型定義と小さな組み合わせ可能なプリミティブに焦点を当てています writeJsDoc는 DuploJS 생태계의 TypeScript 유틸리티 툴박스로서, 강력한 타입 정의와 작은 구성 가능한 원시 값을 제공합니다 writeJsDoc es una herramienta de AI que utiliza @duplojs/utils para mejorar la documentación de JavaScript con una fuerte tipificación y buen DX writeJsDoc est un outil d''IA qui utilise @duplojs/utils pour améliorer la documentation JavaScript avec une forte typification et un bon DX writeJsDoc ist ein KI-Tool, das @duplojs/utils verwendet, um die JavaScript-Dokumentation mit starker Typisierung und gutem DX zu verbessern O writeJsDoc é uma ferramenta de IA que utiliza @duplojs/utils para melhorar a documentação de código JavaScript, focando em tipagem forte e DX. ИИ Агент writeJsDoc использует @duplojs/utils для улучшения документации кода JavaScript, фокусируясь на сильной типизации и DX. أداة الذكاء الاصطناعي writeJsDoc تستخدم @duplojs/utils لتحسين توثيق код جافاسكريبت، مع التركيز على التصنيف القوي و DX. @duplojs/utils is the TypeScript utility toolbox used across the DuploJS ecosystem. It focuses on strong typing, good DX, and small composable primitives that scale from simple helpers to full validation pipelines. 如何使用writeJsDoc 什么是TypeScript工具箱 writeJsDoc替代品 writeJsDoc vs TypeScript writeJsDoc安装 writeJsDoc设置指南 TypeScript工具箱比较 DuploJS生态系统工具 @duplojs/utils is the TypeScript utility toolbox used across the DuploJS ecosystem. It focuses on strong typing, good DX, and small composable primitives that scale from simple helpers to full validation pipelines.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ShapeCrawler/ShapeCrawler/class', 'community', 'ShapeCrawler', 'ShapeCrawler', 'ShapeCrawler/ShapeCrawler', 'class', 0, 0, 23, '2026-03-04T13:07:01.795Z', '2026-03-04T14:27:53.547Z', '1610371248a55f56dae07bbfeeac79c3e4c0dfdd678498d68b3d2414301d6ed7', '{"id":"ShapeCrawler/ShapeCrawler/class","name":"class","description":{"zh":"PowerPoint .NET库，用于读取、修改和生成PPTX演示文稿，无需Microsoft Office。","ja":"PowerPoint .NETライブラリを使用してPPTXプレゼンテーションを読み取り、変更、生成する。","ko":"PowerPoint .NET 라이브러리를 사용하여 PPTX 프레젠테이션을 읽고, 수정하고, 생성합니다.","es":"Clase es una biblioteca .NET que permite leer, modificar y generar presentaciones PPTX sin Microsoft Office. Permite crear y editar presentaciones de forma programática.","fr":"Classe est une bibliothèque .NET qui permet de lire, modifier et générer des présentations PPTX sans Microsoft Office. Elle permet de créer et d''éditer des présentations de forma programmatique.","de":"Klasse ist eine .NET-Bibliothek, die das Lesen, Modifizieren und Generieren von Präsentationen PPTX ohne Microsoft Office ermöglicht. Sie ermöglicht die Erstellung und Bearbeitung von Präsentationen in programmatischer Form.","pt":"Biblioteca .NET para ler, modificar e gerar apresentações PPTX sem Microsoft Office","ru":".NET библиотека для чтения, модификации и генерации презентаций PPTX без Microsoft Office","ar":"مكتبة .NET لقراءة وتعديل وتوليد عروض تقديمية PPTX بدون Microsoft Office","en":"PowerPoint .NET library for reading, modifying, and generating PPTX presentations without Microsoft Office"},"seo":{"title":{"zh":"AIエージェント：PowerPoint .NET库","ja":"AIエージェント：PowerPoint .NETライブラリ","ko":"AI 에이전트: PowerPoint .NET 라이브러리","es":"Clase - Biblioteca .NET para PowerPoint","fr":"Classe - Bibliothèque .NET pour PowerPoint","de":"Klasse - .NET-Bibliothek für PowerPoint","pt":"Ferramentas de IA: Biblioteca .NET para PowerPoint","ru":"И