INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cggonzal/monolith/monolith-websocket-pubsub', 'monolith-websocket-pubsub', 'cggonzal', 'monolith', 'community', 'monolith-websocket-pubsub cggonzal monolith community monolith-websocket-pubsub是一款Go框架，用于构建全栈Web应用，内置代码生成、认证、ORM等功能，灵感来自Rails monolith-websocket-pubsubは、フルスタックWebアプリケーションを構築するためのGoフレームワークです。コード生成、認証、ORMなどを内蔵しています。Railsにインスパイアされています monolith-websocket-pubsub는 풀스택 웹 애플리케이션을 구축하기 위한 Go 프레임워크입니다. 코드 생성, 인증, ORM 등을 내장하고 있으며, Rails에서 영감을 받았습니다 monolith-websocket-pubsub es un framework Go para aplicaciones web full stack con características como generación de código, autenticación y ORM monolith-websocket-pubsub est un framework Go pour applications web full stack avec des fonctionnalités telles que la génération de code, l''authentification et l''ORM monolith-websocket-pubsub ist ein Go-Framework für Full-Stack-Webanwendungen mit Funktionen wie Codegenerierung, Authentifizierung und ORM O monolith-websocket-pubsub é um framework Go para aplicativos web full stack com recursos como geração de código e autenticação monolith-websocket-pubsub - фреймворк Go для веб-приложений с функциями кодогенерации и аутентификации monolith-websocket-pubsub هو إطار عمل Go لتطبيقات الويب الكاملة مع ميزات مثل генерація コード و المصادقة A Go framework for full stack web apps. Has built-in support for code generation, authentication, ORM (gorm), sessions, deployments, job queue, pub/sub (via web sockets), and lots more. Inspired by Rails. Go框架 全栈开发 monolith-websocket-pubsub教程 Go语言开发 Web应用开发 代码生成工具 认证和权限管理 ORM框架 部署和作业队列 pub/sub消息队列 A Go framework for full stack web apps. Has built-in support for code generation, authentication, ORM (gorm), sessions, deployments, job queue, pub/sub (via web sockets), and lots more. Inspired by Rails.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gglessner/hack3270/tn3270-pentest', 'community', 'gglessner', 'hack3270', 'gglessner/hack3270', 'tn3270-pentest', 0, 0, 23, '2026-03-04T13:07:01.908Z', '2026-03-04T14:59:46.356Z', 'b880f7c7d38d328c4e605911204c53082139e228627e6b4c1a59e80cabbf79f9', '{"id":"gglessner/hack3270/tn3270-pentest","name":"tn3270-pentest","description":{"zh":"hack3270是一款基於Python3的工具，專門用於操作TN3270數據流，執行主機CICS應用程式的應用層滲透測試。它幫助安全研究人員識別大型主機應用程式中的潛在漏洞。","ja":"hack3270はPython3ベースのツールで、TN3270データストリームを操作し、メインフレームCICSアプリケーションのアプリケーション侵入テストを実行するために設計されています。","ko":"hack3270는 Python3 기반 도구로 TN3270 데이터 스트림을 조작하고 메인프레임 CICS 애플리케이션의 애플리케이션 침투 테스트를 수행하도록 설계되었습니다.","es":"hack3270 es una herramienta basada en Python para manipular flujos de datos tn3270 y realizar pruebas de penetración en aplicaciones CICS de mainframe","fr":"hack3270 est un outil basé sur Python pour manipuler les flux de données tn3270 et effectuer des tests de pénétration sur les applications CICS de mainframe","de":"hack3270 ist ein Python-Tool zur Manipulation von tn3270-Datenströmen und Durchführung von Penetrationstests auf Mainframe-CICS-Anwendungen","pt":"O tn3270-pentest é uma ferramenta de teste de penetração em Python para aplicações CICS de mainframe, permitindo a manipulação de fluxos de dados tn3270","ru":"tn3270-pentest - это инструмент для тестирования проникновения на Python для приложений CICS основного фреймворка, позволяющий манипулировать потоками данных tn3270","ar":"tn3270-pentest هي أداة اختبار الاختراق بالبايثون لتطبيقات CICS للكمبيوتر الرئيسي، مما يسمح بتحكم في تدفقات البيانات tn3270","en":"hack3270 is a python3 based tool to manipulate tn3270 data streams, specifically to perform application penetration testing of mainframe CICS applications. "},"seo":{"title":{"zh":"AI代理工具：tn3270-pentest - Python3主機滲透測試工具","ja":"AIエージェントツール：tn3270-pentest - Python3メインフレーム