INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('future3OOO/agentic-cockpit/cockpit-continuity-ledger', 'cockpit-continuity-ledger', 'future3OOO', 'agentic-cockpit', 'community', 'cockpit-continuity-ledger future3OOO agentic-cockpit community Cockpit Continuity Ledger是一个使用Fapple codex的AI智能工具，用于提高开发效率 Cockpit Continuity LedgerはFapple codexを使用したAIエージェントで、開発効率を向上させます Cockpit Continuity Ledger는 Fapple codex를 사용하는 AI 에이전트로 개발 효율성을 높입니다 cockpit-continuity-ledger es un componente clave para desarrolladores que buscan mejorar la continuidad y el registro en sus proyectos cockpit-continuity-ledger est un composant clé pour les développeurs qui cherchent à améliorer la continuité et l''enregistrement dans leurs projets cockpit-continuity-ledger ist ein wichtiger Bestandteil für Entwickler, die die Kontinuität und das Protokoll in ihren Projekten verbessern möchten O cockpit-continuity-ledger é uma ferramenta de IA baseada no Fapple codex, projetada para desenvolvedores. Cockpit-continuity-ledger - это инструмент ИИ, основанный на Fapple codex, предназначенный для разработчиков. أداة cockpit-continuity-ledger هي أداة ذكاء اصطناعي مبنية على Fapple codex، مصممة لملحقي التطوير. Fapple codex AI智能工具 Cockpit Continuity Ledger Fapple codex 开发自动化 数据管理 React Python CLI 如何使用Cockpit Continuity Ledger Fapple codex');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('t-kuni/relavue-er/tasks-make-task-list', 'community', 't-kuni', 'relavue-er', 't-kuni/relavue-er', 'tasks-make-task-list', 0, 0, 23, '2026-02-27T01:51:08.697Z', '2026-02-27T03:52:48.259Z', 'b122a02f6899b6587b1f7d1591e8eab85bc9bc4d9b05c65a5e76b5d6cef3d248', '{"id":"t-kuni/relavue-er/tasks-make-task-list","name":"tasks-make-task-list","description":{"zh":"RelavueER 是一个工具，用于逆向 ER 图表从数据库，并允许您在浏览器中交互式地查看它们。它可以帮助您更好地理解数据库结构。","ja":"RelavueER は、データベースから ER 図を逆にし、ブラウザで交互的に表示するためのツールです。データベースの構造を理解するのに役立ちます。","ko":"RelavueER 는 데이터베이스에서 ER 图를逆으로하고 브라우저에서 상호작용적으로 표시하는 도구입니다. 데이터베이스의 구조를 이해하는 데 도움이 됩니다.","es":"RelavueER es una herramienta que invierte diagramas ER desde bases de datos y los muestra interactivamente en tu navegador con facilidad","fr":"RelavueER est un outil qui inverse les diagrammes ER à partir de bases de données et les affiche de manière interactive dans votre navigateur avec facilité","de":"RelavueER ist ein Tool, das ER-Diagramme aus Datenbanken umkehrt und sie interaktiv in Ihrem Browser mit Leichtigkeit anzeigt","pt":"RelavueER é uma ferramenta que reverte diagramas ER de bancos de dados e os exibe interativamente no navegador com facilidade","ru":"RelavueER - это инструмент, который обращает ER-диаграммы баз данных и отображает их интерактивно в браузере с легкостью","ar":"RelavueER هي أداة تعكس الرسوم البيانية ER للقواعد وتعرضها بشكل تفاعلي في المتصفح بسهولة","en":"RelavueER is a tool that reverses ER diagrams from databases and allows you to view them interactively in your browser with ease."},"seo":{"title":{"zh":"RelavueER AI Agent - 任务列表工具","ja":"RelavueER AIエージェント - タスクリストを作成","ko":"RelavueER AI Agent - タスク 리스트 생성 도구","es":"Herramientas de AI: tasks-make-task-list con RelavueER","fr":"Outils d''IA: tasks-make-task-list avec RelavueER","de":"KI-Tools: tasks-make-task-list mit RelavueER","pt":"Ferramentas de IA: tasks-make-task-list com RelavueER","ru":"ИИ Агенты: tasks-make-task-list с RelavueER","ar":"أدوات الذكاء الاصطناعي: tasks-make-task-list مع RelavueER","en":"tasks-make-task-list"},"description":{"zh":"RelavueER 是一个工具，用于逆向 ER 图表从数据库，并允许您在浏览器中交互式地查看它们。它可以帮助您更好地理解数据库结构。","ja":"RelavueER は、データベースから ER 図を逆にし、ブラウザで交互的に表示するためのツールです。データベースの構造を理解するのに役立ちます。","ko":"RelavueER 는 데이터베이스에서 ER 图를逆으로하고 브라우저에서 상호작용적으로 표시하는 도구입니다. 데이터베이스의 구조를 이해하는 데 도움이 됩니다.","es":"RelavueER es una herramienta que invierte diagramas ER desde bases de datos y los muestra interactivamente en tu navegador con facilidad","fr":"RelavueER est un outil qui inverse les diagrammes ER à partir de bases de données et les affiche de manière interactive dans votre navigateur avec facilité","de":"RelavueER ist ein Tool, das ER-Diagramme aus Datenbanken umkehrt und sie interaktiv in Ihrem Browser mit Leichtigkeit anzeigt","pt":"RelavueER é uma ferramenta que reverte diagramas ER de bancos de dados e os exibe interativamente no navegador com facilidade","ru":"RelavueER - это инструмент, который обращает ER-диаграммы баз данных и отображает их интерактивно в браузере с легкостью","ar":"RelavueER هي أداة تعكس الرسوم البيانية ER للقواعد وتعرضها بشكل تفاعلي في المتصفح بسهولة","en":"RelavueER is a tool that reverses ER diagrams from databases and allows you to view them interactively in your browser with ease."},"definition":{"en":"RelavueER is a tool that reverses ER diagrams from databases and allows you to view them interactively in your browser with ease."},"features":{"zh":["逆向 ER 图表从数据库","交互式地查看 ER 图表在浏览器中","帮助您更好地理解数据库结构"],"ja":["データベースから ER 図を逆にし","ブラウザで交互的に表示する","データベースの構造を理解するのに役立ちます"],"ko":["데이터베이스에서 ER 图를逆으로하고","브라우저에서 상호작용적으로 표시","데이터베이스의 구조를 이해하는 데 도움이 됩니다"],"es":["Reversión de diagramas ER desde bases de datos","Visualización interactiva en el navegador","Integración con bases de datos","Interfaz de usuario fácil de usar","Compatibilidad con varios formatos de diagramas"],"fr":["Inversion des diagrammes ER à partir de bases de données","Visualisation interactive dans le navigateur","Intégration avec les bases de données","Interface utilisateur facile à utiliser","Compatibilité avec plusieurs formats de diagrammes"],"de":["Umkehrung von ER-Diagrammen aus Datenbanken","Interaktive Visualisierung im Browser","Integration mit Datenbanken","Benutzerfreundliche Oberfläche","Kompatibilität mit verschiedenen Diagrammformaten"],"pt":["Reversão de diagramas ER de bancos de dados","Exibição interativa no navegador","Gerenciamento de tarefas com tasks-make-task-list","Integração com ferramentas de desenvolvimento","Suporte a múltiplos bancos de dados"],"ru":["Обращение ER-диаграмм баз данных","Интерактивное отображение в браузере","Управление задачами с tasks-make-task-list","Интеграция с инструментами разработки","Поддержка нескольких баз данных"],"ar":["عكس الرسوم البيانية ER للقواعد","العرض التفاعلي في المتصفح","إدارة المهام مع tasks-make-task-list","التكامل مع أدوات التطوير","دعم قواعد بيانات متعددة"]},"keywords":{"zh":["RelavueER","AI 工具","ER 图表逆向","数据库结构理解","how to use RelavueER","what is RelavueER"],"ja":["RelavueER","AI エージェント","ER 図逆向","データベースの構造を理解する","how to use RelavueER","what is RelavueER"],"ko":["RelavueER","AI 도구","ER 图逆向","데이터베이스의 구조를 이해하는 데 도움이 됩니다","how to use RelavueER","what is RelavueER"],"es":["cómo usar RelavueER","herramientas de AI para bases de datos","RelavueER alternativa","RelavueER vs otros herramientas","instalación de RelavueER","guía de configuración de RelavueER","visualización de diagramas ER"],"fr":["comment utiliser RelavueER","outils d''IA pour bases de données","RelavueER alternative","RelavueER vs autres outils","installation de RelavueER","guide de configuration de RelavueER","visualisation de diagrammes ER"],"de":["wie man RelavueER verwendet","KI-Tools für Datenbanken","RelavueER Alternative","RelavueER vs andere Tools","Installation von RelavueER","Konfigurationsanleitung für RelavueER","Visualisierung von ER-Diagrammen"],"pt":["ferramentas de ia","tasks-make-task-list","relavueer","diagramas er","bancos de dados","desenvolvimento de software","gerenciamento de tarefas","integração com ferramentas de desenvolvimento","suporte a múltiplos bancos de dados"],"ru":["ИИ агенты","tasks-make-task-list","relavueer","er-диаграммы","базы данных","разработка программного обеспечения","управление задачами","интеграция с инструментами разработки","поддержка нескольких баз данных"],"ar":["أدوات الذكاء الاصطناعي","tasks-make-task-list","relavueer","الرسوم البيانية er","قواعد البيانات","تطوير البرمجيات","إدارة المهام","التكامل مع أدوات التطوير","دعم قواعد بيانات متعددة"]}},"owner":"t-kuni","repo":"relavue-er","repoPath":"t-kuni/relavue-er","stars":0,"forks":0,"updatedAt":"2026-02-27T01:51:08.697Z","topics":[],"category":"community","skillMd":{"name":"tasks-make-task-list","description":"タスク洗い出しルール　参照条件：タスクの洗い出しを依頼された時","bodyPreview":"* 時間がかかってもいいので関係のある実装や仕様(spec)を確認した上でタスクを洗い出す\n* 仕様の矛盾や実現不可能なものを見つけたら報告して作業を完了してください\n* 洗い出した結果をタスクに分解し./TASK.mdを作成する\n  * 先に既存ファイルを削除する。`rm -f /workspace/TASK.md`\n* 仕様書は書き換えない\n* 本タスクより先に実装・リファクタリングしたほうが良いものがあれば遂行障害リストに記載する\n\n* 洗い出し対象のタスク\n  * 対象のタスク\n    * 実装\n    * テストコード作成\n    * ビルドの確認\n    * テストの実行\n  * 対象外のタスク\n    * 指示していない修正\n    * 実際にアプリを起動して動作確認\n\n* タスク分解ルール\n  * 修正対象が膨大な場合はフェーズ分けを考える\n    * ファイルの更新が10ファイル以上、ファイルの新規作成が5ファイル以上、あたりからフェーズ分けを検討する\n    * １フェーズあたり更新10ファイル、新規作成5ファイル程度になるようにフェーズ分けする\n    * 可能な","body":"* 時間がかかってもいいので関係のある実装や仕様(spec)を確認した上でタスクを洗い出す\n* 仕様の矛盾や実現不可能なものを見つけたら報告して作業を完了してください\n* 洗い出した結果をタスクに分解し./TASK.mdを作成する\n  * 先に既存ファイルを削除する。`rm -f /workspace/TASK.md`\n* 仕様書は書き換えない\n* 本タスクより先に実装・リファクタリングしたほうが良いものがあれば遂行障害リストに記載する\n\n* 洗い出し対象のタスク\n  * 対象のタスク\n    * 実装\n    * テストコード作成\n    * ビルドの確認\n    * テストの実行\n  * 対象外のタスク\n    * 指示していない修正\n    * 実際にアプリを起動して動作確認\n\n* タスク分解ルール\n  * 修正対象が膨大な場合はフェーズ分けを考える\n    * ファイルの更新が10ファイル以上、ファイルの新規作成が5ファイル以上、あたりからフェーズ分けを検討する\n    * １フェーズあたり更新10ファイル、新規作成5ファイル程度になるようにフェーズ分けする\n    * 可能な限り、ビルド・テスト可能な単位でフェーズ分けする。\n      * 例えば「バックエンドの修正〜ビルド確認・テスト実行」で１フェーズ、「フロントエンドの修正〜ビルド確認」で１フェーズの合計２フェーズなど\n    * 各フェーズの最後にビルド・テストを行う\n\n併せて [タスク一覧(TASK.md)作成ガイドライン](.cursor/rules/guideline-tasks.mdc) も参照すること\n"},"lastSynced":"2026-02-27T03:52:48.259Z","agentAnalysis":{"suitability":{"en":"Ideal for Task Management Agents requiring detailed task breakdown and specification analysis.","zh":"适合需要详细任务分解和规格分析的任务管理代理。","ja":"タスク管理エージェントに詳細なタスク分解と仕様分析が必要な場合に最適です。","ko":"詳細한 작업 분해 및 사양 분석이 필요한 작업 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Gestión de Tareas que requieren una descomposición y análisis de especificaciones detalladas.","fr":"Idéal pour les Agents de Gestion de Tâches nécessitant une décomposition et une analyse de spécifications détaillées.","de":"Ideal für Task-Management-Agents, die eine detaillierte Aufgabenzerlegung und Spezifikationsanalyse erfordern.","pt":"Ideal para Agentes de Gerenciamento de Tarefas que exigem quebra detalhada de tarefas e análise de especificação.","ru":"Идеально подходит для агентов управления задачами, требующих подробного разбиения задач и анализа спецификации.","ar":"مثالية للوكلاء إدارة المهام التي تتطلب تحليل مفصل للمهام وتحليل المواصفات."},"recommendation":{"en":"Empowers agents to create comprehensive task lists from complex specifications, utilizing file management protocols like rm -f and markdown file creation, ensuring efficient task decomposition and reporting of implementation obstacles.","zh":"赋予代理创建全面任务列表的能力，从复杂的规格中利用文件管理协议，如 rm -f 和 markdown 文件创建，确保高效的任务分解和实现障碍的报告。","ja":"エージェントが複雑な仕様から包括的なタスクリストを作成する能力を与え、ファイル管理プロトコル such as rm -f と markdown ファイル作成を利用し、タスクの分解と実装の障害の報告を効率化します。","ko":"에이전트가 복잡한 사양에서 포괄적인 작업 목록을 생성할 수 있는 능력을 부여하여 파일 관리 프로토콜 such as rm -f 및 markdown 파일 생성을 활용하여 작업 분해 및 구현 장애 보고를 효율적으로 수행합니다.","es":"Permite a los agentes crear listas de tareas comprehensivas a partir de especificaciones complejas, utilizando protocolos de gestión de archivos como rm -f y creación de archivos markdown, lo que garantiza una descomposición eficiente de tareas y la notificación de obstáculos de implementación.","fr":"Permet aux agents de créer des listes de tâches complètes à partir de spécifications complexes, en utilisant des protocoles de gestion de fichiers tels que rm -f et la création de fichiers markdown, garantissant ainsi une décomposition efficace des tâches et la notification des obstacles d''implémentation.","de":"Ermöglicht es Agenten, umfassende Aufgabenlisten aus komplexen Spezifikationen zu erstellen, indem sie Dateimanagement-Protokolle wie rm -f und die Erstellung von Markdown-Dateien nutzen, was eine effiziente Aufgabenzerlegung und die Meldung von Implementierungshindernissen gewährleistet.","pt":"Permite que os agentes criem listas de tarefas abrangentes a partir de especificações complexas, utilizando protocolos de gerenciamento de arquivos como rm -f e criação de arquivos markdown, garantindo decomposição eficiente de tarefas e relatórios de obstáculos de implementação.","ru":"Позволяет агентам создавать всесторонние списки задач из сложных спецификаций, используя протоколы управления файлами, такие как rm -f и создание файлов markdown, обеспечивая эффективное разбиение задач и отчетность о препятствиях реализации.","ar":"تمكن الوكلاء من إنشاء قوائم شاملة للمهام من المواصفات المعقدة، باستخدام بروتوكولات إدارة الملفات مثل rm -f وإنشاء ملفات markdown، مما يضمن تحليل كفء للمهام وتقارير عقبات التنفيذ."},"useCases":{"en":["Decomposing large projects into manageable tasks with interactive ER diagram analysis","Generating TASK.md files for clear task tracking and progress monitoring","Identifying and reporting specification contradictions and implementation impossibilities"],"zh":["使用交互式 ER 图分析将大型项目分解为可管理的任务","生成 TASK.md 文件以实现清晰的任务跟踪和进度监控","识别和报告规格矛盾和实现不可能性"],"ja":["インタラクティブな ER 図分析を使用して大規模なプロジェクトを管理可能なタスクに分解する","TASK.md ファイルを生成してタスクの追跡と進度モニタリングを明確にします","仕様の矛盾と実装の不可能性を識別して報告する"],"ko":["대화형 ER 다이어그램 분석을 사용하여 대규모 프로젝트를 관리 가능한 작업으로 분해한다","TASK.md 파일을 생성하여 작업 추적 및 진행 상황 모니터링을 명확하게 한다","사양의 모순과 구현의 불가능성을 식별하고 보고한다"],"es":["Descomponer grandes proyectos en tareas manejables con análisis de diagramas ER interactivos","Generar archivos TASK.md para un seguimiento claro de tareas y monitoreo de progreso","Identificar y notificar contradicciones de especificaciones y imposibilidades de implementación"],"fr":["Décomposer de grands projets en tâches gérables avec analyse de diagrammes ER interactifs","Générer des fichiers TASK.md pour un suivi clair des tâches et un suivi des progrès","Identifier et notifier les contradictions de spécifications et les impossibilités d''implémentation"],"de":["Große Projekte in handhabbare Aufgaben mit interaktiver ER-Diagrammanalyse zerlegen","TASK.md-Dateien generieren, um eine klare Aufgabenverfolgung und Fortschrittsüberwachung zu ermöglichen","Spezifikationswidersprüche und Implementierungsunmöglichkeiten identifizieren und melden"],"pt":["Decompor projetos grandes em tarefas gerenciáveis com análise de diagrama ER interativo","Gerar arquivos TASK.md para acompanhamento claro de tarefas e monitoramento de progresso","Identificar e relatar contradições de especificação e impossibilidades de implementação"],"ru":["Разбить крупные проекты на управляемые задачи с помощью интерактивного анализа диаграммы сущность-связь","Генерировать файлы TASK.md для ясного отслеживания задач и мониторинга прогресса","Определить и сообщить о противоречиях в спецификации и невозможностях реализации"],"ar":["تحليل المشاريع الكبيرة إلى مهام قابلة للإدارة مع تحليل مخطط كيانات العلاقات التفاعلية","إنشاء ملفات TASK.md لمراقبة واضحة للمهام ومراقبة التقدم","تحديد وتقرير تناقضات المواصفات واستحالات التنفيذ"]},"limitations":{"en":["Requires existing specification documents for analysis","Does not support actual application deployment or dynamic testing","Limited to task breakdown and does not modify original specification documents"],"zh":["需要现有的规格文档进行分析","不支持实际应用部署或动态测试","仅限任务分解，不修改原始规格文档"],"ja":["分析のために既存の仕様書が必要です","実際のアプリケーションのデプロイまたは動的テストはサポートされません","タスクの分解のみに限定され、元の仕様書は変更されません"],"ko":["분석을 위해 기존의 사양 문서가 필요합니다","실제 애플리케이션 배포 또는 동적 테스트는 지원되지 않습니다","작업 분해만으로 제한되며 원래의 사양 문서는 수정되지 않습니다"],"es":["Requiere documentos de especificaciones existentes para el análisis","No admite la implementación real de aplicaciones o pruebas dinámicas","Se limita a la descomposición de tareas y no modifica los documentos de especificaciones originales"],"fr":["Nécessite des documents de spécifications existants pour l''analyse","Ne prend pas en charge le déploiement réel d''applications ou les tests dynamiques","Se limite à la décomposition des tâches et ne modifie pas les documents de spécifications originaux"],"de":["Benötigt vorhandene Spezifikationsdokumente für die Analyse","Unterstützt keine tatsächliche Anwendungsbereitstellung oder dynamische Tests","Begrenzt sich auf die Aufgabenzerlegung und ändert nicht die ursprünglichen Spezifikationsdokumente"],"pt":["Exige documentos de especificação existentes para análise","Não suporta implantação real de aplicações ou testes dinâmicos","Limitado à quebra de tarefas e não modifica os documentos de especificação originais"],"ru":["Требует существующих документов спецификации для анализа","Не поддерживает фактическую развертку приложений или динамическое тестирование","Ограничен разбиением задач и не изменяет исходные документы спецификации"],"ar":["يتطلب وثائق مواصفات موجودة للتحليل","لا يدعم نشر التطبيقات الفعلي أو الاختبار الديناميكي","محدود بتحليل المهام ولا يعدل على وثائق المواصفات الأصلية"]},"version":3},"contentHash":"b122a02f6899b6587b1f7d1591e8eab85bc9bc4d9b05c65a5e76b5d6cef3d248","qualityScore":23}');
