INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tvararu/tuicraft/tuicraft', 'tuicraft', 'tvararu', 'tuicraft', 'community', 'tuicraft tvararu tuicraft community tuicraft是一款允许您从终端聊天 WoW 3.3.5a的AI工具，使用简单的CLI命令 tuicraftはターミナルからWoW 3.3.5aをチャットできるAIエージェントで、シンプルなCLIコマンドを使用 tuicraft는 터미널에서 WoW 3.3.5a 채팅할 수 있는 AI 에이전트로, 간단한 CLI 명령어를 사용 tuicraft es una herramienta de AI que permite chatear en WoW 3.3.5a desde la terminal. Es una solución CLI para comunicarse con otros jugadores. tuicraft est un outil d''IA qui permet de chatter sur WoW 3.3.5a depuis le terminal. Il s''agit d''une solution en ligne de commande pour communiquer avec d''autres joueurs. tuicraft ist ein KI-Tool, das das Chatten im WoW-Chat 3.3.5a aus der Konsole ermöglicht. Es handelt sich um eine CLI-Lösung für die Kommunikation mit anderen Spielern. O tuicraft é uma ferramenta de IA que permite chats WoW 3.3.5a diretamente no terminal. É uma solução inovadora para desenvolvedores. Tuicraft - это ИИ агент, который позволяет чатить в WoW 3.3.5a прямо из терминала. Это инновационное решение для разработчиков. tuicraft هو أداة ذكاء اصطناعي تمكنك من الدردشة في WoW 3.3.5a مباشرة من الطرفية. وهي حل مبتكر للمطورين. Chat in WoW 3.3.5a from your terminal tuicraft AI工具 WoW 3.3.5a终端聊天 如何使用tuicraft tuicraft安装指南 tuicraft与其他AI工具的比较 WoW 3.3.5a游戏辅助工具 终端聊天工具 AI驱动的聊天功能 Chat in WoW 3.3.5a from your terminal');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cwilliams5/Alt-Tabby/review-tool-coverage', 'community', 'cwilliams5', 'Alt-Tabby', 'cwilliams5/Alt-Tabby', 'review-tool-coverage', 1, 0, 21, '2026-02-25T02:02:59Z', '2026-02-26T08:43:11.042Z', '1e73ebaf48415347d7ec9714594bf48c792c06bddd8ac3fa3d693640798e1d41', '{"id":"cwilliams5/Alt-Tabby/review-tool-coverage","name":"review-tool-coverage","description":{"zh":"快速、响应式的Alt-Tab替代工具，支持Komorebi集成，提高Windows生产力","ja":"高速でレスポンシブなAlt-Tab代替ツール。Komorebiと統合してWindowsの生産性を向上させます","ko":"빠르고 반응성이 좋은 Alt-Tab 대체 도구입니다. Komorebi와 통합하여 Windows 생산성을 향상시킵니다","es":"Una herramienta de revisión de cobertura es una herramienta de productividad que mejora la experiencia del usuario en Windows","fr":"Un outil d''examen de couverture est un outil de productivité qui améliore l''expérience utilisateur sur Windows","de":"Ein AI-Tool zur Überprüfung von Werkzeugabdeckung ist ein Produktivitätstool, das die Benutzererfahrung in Windows verbessert","pt":"Nossa ferramenta de revisão de cobertura de ferramentas é uma alternativa rápida e responsiva para Alt-Tab no Windows, com integração Komorebi para melhorar a produtividade","ru":"Наш ИИ Агент для просмотра инструментов - быстрый и отзывчивый替ACEMENT для Alt-Tab в Windows с интеграцией Komorebi для повышения производительности","ar":"أداة مراجعة تغطية الأدوات هي بديل سريع ومتجاوب لAlt-Tab على نظام ويندوز مع دمج Komorebi لتحسين الإنتاجية","en":"Fast, responsive Alt-Tab replacement for Windows with Komorebi integration"},"seo":{"title":{"zh":"AI工具：快速Alt-Tab替代工具","ja":"AIエージェント：高速Alt-Tab代替ツール","ko":"AI 에이전트: 빠른 Alt-Tab 대체 도구","es":"Herramientas de reseña de cobertura de herramientas de re...","fr":"Outils d''examen de couverture des outils d''examen","de":"AI-Tools zur Überprüfung von Werkzeugabdeckung","pt":"Ferramenta de Revisão de Cobertura de Ferramentas - Ferra...","ru":"ИИ Агент для Пр