INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Renkunzhao/motion_viewer/commit', 'commit', 'Renkunzhao', 'motion_viewer', 'community', 'commit Renkunzhao motion_viewer community robotics visualization Commit是一款用于机器人模型和运动数据的可视化工具，帮助开发者更好地理解和优化机器人性能 Commitはロボットモデルとモーションデータの可視化ツールで、開発者がロボットのパフォーマンスをよりよく理解して最適化できるようにします Commit는 로봇 모델 및 모션 데이터를 시각화하는 도구로 개발자가 로봇의 성능을 더 잘 이해하고 최적화할 수 있도록 도와줍니다 Commit es una herramienta de visualización web para modelos de robots y datos de movimiento, ideal para desarrolladores de robotics Commit est un outil de visualisation web pour les modèles de robots et les données de mouvement, idéal pour les développeurs de robotique Commit ist ein Web-Visualisierungstool für Robotermodelle und Bewegungsdaten, ideal für Entwickler im Bereich Robotik O Commit é uma ferramenta de visualização web para modelos de robótica e dados de movimento, permitindo aos desenvolvedores visualizar e analisar dados de robótica de forma eficaz Commit - это веб-инструмент для визуализации моделей роботов и данных движения, позволяющий разработчикам эффективно визуализировать и анализировать данные роботов كميت هي أداة تعليم روبوتية على الويب لتصور نماذج الروبوتات وبيانات الحركة، مما يسمح للمطورين بتصور وتنظيم بيانات الروبوتات بفعالية A web-based visualization tool for robot models and motion data 如何使用Commit 什么是机器人模型可视化 Commit替代工具 Commit安装 机器人模型可视化工具 Commit教程 机器人开发工具 Commit功能 A web-based visualization tool for robot models and motion data');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vativa/WeatherForecast/Favourite Location', 'community', 'vativa', 'WeatherForecast', 'vativa/WeatherForecast', 'Favourite Location', 0, 0, 21, '2026-01-29T14:40:58Z', '2026-02-27T04:05:30.030Z', 'b6e95d3b1239156f6c205a104877ece1c0007a629970c61a0617995625cc70f4', '{"id":"vativa/WeatherForecast/Favourite Location","name":"Favourite Location","description":{"zh":"Favourite Location是JavaScript软件开发工程师的AI-First练习，用于提高开发技能","ja":"Favourite LocationはJavaScriptソフトウェア開発エンジニアのAI-Firstの練習であり、開発スキルを向上させるために使用されます","ko":"Favourite Location는 JavaScript 소프트웨어 개발 엔지니어를 위한 AI-First 연습으로 개발 실력을 향상시키는 데 사용됩니다","es":"El agente de AI Favorito Localización es un ejercicio de desarrollo de software en JavaScript para desarrolladores. Aprende a crear herramientas de AI con tecnologías como React y Node.js.","fr":"L''agent d''IA Emplacement Favori est un exercice de développement de logiciel en JavaScript pour les développeurs. Apprenez à créer des outils d''IA avec des technologies comme React et Node.js.","de":"Der AI-Agent Favorit Ort ist ein Entwicklungsübung für Softwareentwickler in JavaScript. Lernen Sie, wie Sie AI-Tools mit Technologien wie React und Node.js erstellen.","pt":"Favourite Location é um exercício de desenvolvimento de software em JavaScript para engenheiros de software, com foco em agente de IA","ru":"Favourite Location - это упражнение по разработке программного обеспечения на JavaScript для инженеров-программистов, с фокусом на ИИ Агентах","ar":"موقع مفضل هو تمرين لتطوير البرمجيات بلغة جافاسكريبت لمهندسي البرمجيات، مع التركيز على وكلاء الذكاء الاصطناعي","en":"JavaScript Software Development Engineer Exercise (AI-First)"},"seo":{"title":{"zh":"AI智能体-Favourite Location","ja":"AIエージェントのFavourite Location","ko":"AI 에이전트-좋아하는 위치","es":"Herramientas de AI: Favorito Localización con JavaScript","fr":"Outils d''IA: