INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('angular/angular/reference-core', 'reference-core', 'angular', 'angular', 'community', 'reference-core angular angular community reference-core是一个AI智能工具，帮助开发者打造高性能、可靠的Web应用 reference-coreはAIエージェントであり、開発者が信頼性の高いWebアプリを実現することを支援します reference-core는 AI 에이전트로서 개발자가 안정적인 웹 애플리케이션을 구축하도록 지원합니다 Entrega aplicaciones web con confianza utilizando herramientas de referencia-core. Desarrolla con tecnologías como React, Python y Node.js Livrez des applications web avec confiance en utilisant des outils de référence-core. Développez avec des technologies comme React, Python et Node.js Liefern Sie Webanwendungen mit Vertrauen mithilfe von Referenz-Core-Tools. Entwickeln Sie mit Technologien wie React, Python und Node.js O reference-core é uma solução de confiança para entrega de aplicações web escaláveis e seguras ИИ Агент reference-core является надежным решением для доставки веб-приложений с высокой масштабируемостью и безопасностью reference-core هو حل موثوق به لتقديم تطبيقات الوب القابلة للتوسع والأمنة Deliver web apps with confidence 🚀 如何使用reference-core 什么是AI智能工具 reference-core替代品 reference-core与竞争对手的比较 reference-core安装 reference-core设置指南 Web应用开发 AI智能优化 Deliver web apps with confidence 🚀');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('flutter/flutter-intellij/triage-helper', 'community', 'flutter', 'flutter-intellij', 'flutter/flutter-intellij', 'triage-helper', 0, 0, 21, '2026-03-04T13:07:01.889Z', '2026-03-04T14:54:25.848Z', '1e680800adb1a9e060dfd749d2652e3721183ff60afac59329e8ec01b70bf884', '{"id":"flutter/flutter-intellij/triage-helper","name":"triage-helper","description":{"zh":"triage-helper是为IntelliJ开发的Flutter插件，用于提高开发效率","ja":"triage-helperはIntelliJ用のFlutterプラグインで、開発効率を向上させる","ko":"triage-helper는 IntelliJ용 플러터 플러그인으로 개발 효율을 향상시킵니다","es":"El plugin de triage para IntelliJ es una herramienta para desarrolladores de Flutter que ayuda a simplificar el proceso de depuración y solución de problemas.","fr":"Le plugin de triage pour IntelliJ est un outil pour les développeurs Flutter qui aide à simplifier le processus de débogage et de résolution de problèmes.","de":"Das Triage-Plugin für IntelliJ ist ein Tool für Flutter-Entwickler, das dabei hilft, den Prozess der Fehlersuche und -behebung zu vereinfachen.","pt":"O Triage-Helper é um plugin para IntelliJ que facilita o desenvolvimento de aplicativos Flutter","ru":"Triage-Helper - плагин для IntelliJ, упрощающий разработку приложений Flutter с помощью ИИ Агентов","ar":"Triage-Helper هو إضافة لIntelliJ تسهل تطوير تطبيقات Flutter","en":"Flutter Plugin for IntelliJ"},"seo":{"title":{"zh":"AI智能工具：triage-helper Flutter插件","ja":"AIエージェント：triage-helper Flutterプラグイン","ko":"AI 에이전트: triage-helper 플러터 플러그인","es":"Herramienta de triage para Flutter - Ayuda para desarroll...","fr":"Outil de triage pour Flutter - Aide pour les développeurs","de":"Triage-Tool für Flutter - Hilfe für Entwickler","pt":"Ferramenta de Triagem para Flutter - Triage-Helper","ru":"ИИ Агент для Flutter - Triage-Helper","ar":"أداة فحص مسبق لFlutter - Triage-Helper","en":"triage-helper"},"description":{"zh":"triage-helper是为IntelliJ开发的Flutter插件，用于提高开发效率","ja":"triage-helperはIntelliJ用のFlutterプラグインで、開発効率を向上させる","ko":"triage-helper는 IntelliJ용 플러터 플러그인으로 개발 효율을 향상시킵니다","es":"El plugin de triage para IntelliJ es una herramienta para desarrolladores de Flutter que ayuda a simplificar el proceso de depuración y solución de problemas.","fr":"Le plugin de triage pour IntelliJ est un outil pour les développeurs Flutter qui aide à simplifier le processus de débogage et de résolution de problèmes.","de":"Das Triage-Plugin für IntelliJ ist ein Tool für Flutter-Entwickler, das dabei hilft, den Prozess der Fehlersuche und -behebung zu vereinfachen.","pt":"O Triage-Helper é um plugin para IntelliJ que facilita o desenvolvimento de aplicativos Flutter","ru":"Triage-Helper - плагин для IntelliJ, упрощающий разработку приложений Flutter с помощью ИИ Агентов","ar":"Triage-Helper هو إضافة لIntelliJ تسهل تطوير تطبيقات Flutter","en":"Flutter Plugin for IntelliJ"},"definition":{"en":"Flutter Plugin for IntelliJ"},"features":{"zh":["提高代码质量","提高开发效率","支持IntelliJ","Flutter插件","AI智能辅助","简化开发流程"],"ja":["コード品質の向上","開発効率の向上","IntelliJ対応","Flutterプラグイン","AIエージェントによる支援","開発プロセスの簡素化"],"ko":["코드 품질 향상","개발 효율 향상","IntelliJ 지원","플러터 플러그인","AI 에이전트 지원","개발 프로세스 단순화"],"es":["Integración con IntelliJ","Análisis de código automatizado","Priorización de problemas","Informes detallados","Personalización de reglas de triage"],"fr":["Intégration avec IntelliJ","Analyse de code automatisée","Priorisation des problèmes","Rapports détaillés","Personnalisation des règles de triage"],"de":["Integration mit IntelliJ","Automatisierte Code-Analyse","Priorisierung von Problemen","Detaillierte Berichte","Anpassung von Triage-Regeln"],"pt":["Plugin para IntelliJ","Desenvolvimento de aplicativos Flutter","Ferramenta de triagem para identificar problemas","Integração com o ecossistema Flutter","Melhoria da produtividade do desenvolvedor"],"ru":["Плагин для IntelliJ","Разработка приложений Flutter с помощью ИИ Агентов","Инструмент для выявления проблем","Интеграция с экосистемой Flutter","Повышение производительности разработчика"],"ar":["إضافة لIntelliJ","تطوير تطبيقات Flutter","أداة فحص مسبق لتحديد المشاكل","التكامل مع نظام Flutter","تحسين إنتاجية المطور"]},"keywords":{"zh":["如何使用triage-helper","什么是triage-helper","triage-helper替代品","triage-helper与其他工具的比较","triage-helper安装","triage-helper设置指南","Flutter开发工具","IntelliJ插件"],"ja":["triage-helperの使い方","triage-helperとは","triage-helperの代替","triage-helperと他のツールの比較","triage-helperのインストール","triage-helperの設定ガイド","Flutter開発ツール","IntelliJプラグイン"],"ko":["triage-helper 사용법","triage-helper란","triage-helper 대체","triage-helper와 다른 도구의 비교","triage-helper 설치","triage-helper 설정 가이드","플러터 개발 도구","IntelliJ 플러그인"],"es":["herramienta de triage","plugin de triage para IntelliJ","desarrollo de Flutter","depuración de código","solución de problemas","cómo usar el plugin de triage","alternativas al plugin de triage"],"fr":["outil de triage","plugin de triage pour IntelliJ","développement Flutter","débogage de code","résolution de problèmes","comment utiliser le plugin de triage","alternatives au plugin de triage"],"de":["Triage-Tool","Triage-Plugin für IntelliJ","Flutter-Entwicklung","Fehlersuche im Code","Problembehebung","wie man das Triage-Plugin verwendet","Alternativen zum Triage-Plugin"],"pt":["como usar Triage-Helper","o que é Triage-Helper","Triage-Helper alternativa","Triage-Helper vs outros plugins","instalar Triage-Helper","guia de configuração do Triage-Helper","desenvolvimento de aplicativos Flutter","plugin para IntelliJ"],"ru":["как использовать Triage-Helper","что такое Triage-Helper","Triage-Helper альтернатива","Triage-Helper vs другие плагины","установить Triage-Helper","руководство по настройке Triage-Helper","разработка приложений Flutter с помощью ИИ Агентов","плагин для IntelliJ"],"ar":["كيفية استخدام Triage-Helper","ما هو Triage-Helper","بديل Triage-Helper","Triage-Helper مقابل إضافات أخرى","تثبيت Triage-Helper","دليل إعداد Triage-Helper","تطوير تطبيقات Flutter","إضافة لIntelliJ"]}},"owner":"flutter","repo":"flutter-intellij","repoPath":"flutter/flutter-intellij","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.889Z","topics":[],"category":"community","skillMd":{"name":"triage-helper","description":"Assistance with triage of unprioritized issues. Use when the user asks for help with triage.","bodyPreview":"When a user asks for help in the CLI:\n- Find the latest open issues in the https://github.com/flutter/flutter-intellij/ repo that don''t have a priority label.\n- If you encounter authentication issues, guide the user to check their `github-mcp-server` setup or `gh auth status` depending on available tools.\n- Reference `docs/Triaging.md` for detailed setup instructions.\n- Consider the most recently updated issues first. Start presenting issues one at a time to the user, with the issue URL and othe","body":"When a user asks for help in the CLI:\n- Find the latest open issues in the https://github.com/flutter/flutter-intellij/ repo that don''t have a priority label.\n- If you encounter authentication issues, guide the user to check their `github-mcp-server` setup or `gh auth status` depending on available tools.\n- Reference `docs/Triaging.md` for detailed setup instructions.\n- Consider the most recently updated issues first. Start presenting issues one at a time to the user, with the issue URL and other relevant information.\n- For each issue, give suggestions such as:\n    - Close the issue if it''s not relevant anymore (e.g. it''s been fixed, the code it''s referencing is outdated, etc.)\n    - Suggest how to reproduce if it looks like it may be easy to reproduce locally\n    - Ask for a reproduction with a small project if reproduction may be hard locally\n    - Ask for more information and apply a waiting for response label\n    - Note a code pointer for the issue if it could be a good first issue for an external contributor\n    - Suggest a priority and other labels that may be relevant along with reasoning for the priority\n- Then wait for user feedback before continuing on to the next issue.\n\nAvoid executing tasks on GitHub directly, such as making comments, applying labels, or closing issues.\n\nThere is additional context on our issue triage process in docs/Triaging.md."},"lastSynced":"2026-03-04T14:54:25.848Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Analysis Agents needing advanced issue triage capabilities.","zh":"适用于需要高级问题诊断功能的Python分析代理。","ja":"Python分析エージェントが高度な問題のトリアージ機能を必要とする場合に適しています。","ko":"고급 문제 진단 기능이 필요한 Python 분석 에이전트에 적합합니다.","es":"Ideal para agentes de análisis de Python que necesitan capacidades de triage de problemas avanzadas.","fr":"Parfait pour les agents d''analyse Python nécessitant des capacités de triage de problèmes avancées.","de":"Ideal für Python-Analyse-Agents, die erweiterte Fähigkeiten zur Problemtriage benötigen.","pt":"Perfeito para Agentes de Análise Python que necessitam de capacidades avançadas de triagem de problemas.","ru":"Идеально для агентов анализа Python, которым необходимы расширенные возможности триажа проблем.","ar":"مثالي لعميل تحليل بايثون الذي يحتاج إلى إمكانيات متقدمة لترياق المشكلات."},"recommendation":{"en":"Empowers agents to analyze and prioritize open issues in the Flutter plugin for IntelliJ repository using GitHub API, without requiring manual authentication checks or priority label management. It provides issue filtering and prioritization.","zh":"赋予代理分析和优先处理GitHub API中的Flutter插件IntelliJ存储库中的打开问题的能力，而无需手动身份验证检查或优先级标签管理。它提供问题过滤和优先级排序。","ja":"GitHub APIを使用して、Flutterプラグインfor IntelliJリポジトリ内のオープン問題を分析および優先順位付けするエージェントを可能にします。手動での認証チェックや優先順位付けラベルの管理は不要です。問題のフィルタリングや優先順位付けが提供されます。","ko":"GitHub API를 사용하여 Flutter 플러그인 for IntelliJ 저장소의 열린 문제를 분석 및 우선순위 지정할 수 있는 에이전트를 가능하게 합니다. 수동 인증 확인 또는 우선순위 지정 레이블 관리가 필요 없습니다. 문제 필터링 및 우선순위 지정이 제공됩니다.","es":"Habilita a los agentes para analizar y priorizar problemas abiertos en el repositorio del plugin de Flutter para IntelliJ utilizando GitHub API, sin requerir comprobaciones de autenticación manuales o gestión de etiquetas de prioridad. Proporciona filtrado y priorización de problemas.","fr":"Permet aux agents d''analyser et de prioriser les problèmes ouverts dans le référentiel du plugin Flutter pour IntelliJ en utilisant l''API GitHub, sans nécessiter de vérifications d''authentification manuelles ou de gestion d''étiquettes de priorité. Il fournit un filtrage et une priorisation des problèmes.","de":"Ermöglicht es Agenten, offene Probleme im Flutter-Plugin-Repository für IntelliJ mithilfe von GitHub API zu analysieren und zu priorisieren, ohne manuelle Authentifizierungsprüfungen oder Prioritätslabelverwaltung zu erfordern. Es bietet Problemfilterung und -priorisierung.","pt":"Habilita os agentes a analisar e priorizar problemas abertos no repositório do plugin Flutter para IntelliJ usando a API do GitHub, sem exigir verificações de autenticação manuais ou gerenciamento de rótulos de prioridade. Ele fornece filtragem e priorização de problemas.","ru":"Наделяет агентов возможностью анализировать и расставлять приоритеты открытых проблем в репозитории плагина Flutter для IntelliJ с помощью API GitHub, не требуя ручных проверок аутентификации или управления метками приоритета. Он обеспечивает фильтрацию и расстановку приоритетов проблем.","ar":"يتمكن العملاء من خلالها من تحليل ومتابعة المشكلات المفتوحة في مستودع ملحقات Flutter لبرنامج IntelliJ باستخدام واجهة برمجة تطبيقات GitHub، دون الحاجة إلى عمليات التحقق اليدوية أو إدارة علامات الأولوية. كما يوفر تصفية وتحديد أولويات المشكلات."},"useCases":{"en":["Automating issue triage for newly reported issues","Generating issue reports for recently updated issues","Debugging authentication issues in the GitHub API"],"zh":["自动执行新报告问题的问题诊断","生成最近更新问题的问题报告","调试GitHub API中的身份验证问题"],"ja":["新しく報告された問題の問題トリアージを自動化する","最近更新された問題の問題レポートを生成する","GitHub API内の認証問題をデバッグする"],"ko":["신규 보고된 문제의 문제 진단을 자동화하는 것","최근 업데이트된 문제의 문제 보고서를 생성하는 것","GitHub API 내의 인증 문제를 디버깅하는 것"],"es":["Automatización del triage de problemas para problemas informados recientemente","Generación de informes de problemas para problemas actualizados recientemente","Depuración de problemas de autenticación en la API de GitHub"],"fr":["Automatisation du triage des problèmes pour les problèmes signalés récemment","Génération de rapports de problèmes pour les problèmes mis à jour récemment","Débogage des problèmes d''authentification dans l''API GitHub"],"de":["Automatisierung des Problem-Triags für neu gemeldete Probleme","Erstellung von Problemberichten für kürzlich aktualisierte Probleme","Fehlerbehebung bei Authentifizierungsproblemen in der GitHub-API"],"pt":["Automatizar a triagem de problemas para problemas recém-relatados","Gerar relatórios de problemas para problemas atualizados recentemente","Depurar problemas de autenticação na API do GitHub"],"ru":["Автоматизировать триаж проблем для новооткрытых проблем","Генерировать отчеты о проблемах для недавно обновленных проблем","Отлаживать проблемы аутентификации в API GitHub"],"ar":["الاستفادة من آليّة ترياق المشكلات لأولئك الذين تم الإبلاغ عنهم مؤخرا","إنتاج تقارير عن المشكلات التي تم تحديثها مؤخرا","تصحيح مشاكل المصادقة في واجهة برمجة تطبيقات GitHub"]},"limitations":{"en":["Requires GitHub API access","Limited to issues in the Flutter plugin for IntelliJ repository"],"zh":["需要GitHub API访问","仅限于Flutter插件for IntelliJ存储库中的问题"],"ja":["GitHub APIへのアクセスが必要","Flutterプラグインfor IntelliJリポジトリ内の問題のみ"],"ko":["GitHub API 액세스가 필요함","Flutter 플러그인 for IntelliJ 저장소의 문제에만 محدود"],"es":["Requiere acceso a la API de GitHub","Limitado a problemas en el repositorio del plugin de Flutter para IntelliJ"],"fr":["Nécessite un accès à l''API GitHub","Limité aux problèmes dans le référentiel du plugin Flutter pour IntelliJ"],"de":["Benötigt Zugriff auf die GitHub-API","Begrenzt auf Probleme im Flutter-Plugin-Repository für IntelliJ"],"pt":["Exige acesso à API do GitHub","Limitado a problemas no repositório do plugin Flutter para IntelliJ"],"ru":["Требует доступа к API GitHub","Ограничен проблемами в репозитории плагина Flutter для IntelliJ"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات GitHub","محدود بالمشكلات في مستودع ملحقات Flutter لبرنامج IntelliJ"]},"version":3},"contentHash":"1e680800adb1a9e060dfd749d2652e3721183ff60afac59329e8ec01b70bf884","qualityScore":21}');
