INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('flutter/flutter-intellij/triage-helper', 'triage-helper', 'flutter', 'flutter-intellij', 'community', 'triage-helper flutter flutter-intellij community triage-helper是为IntelliJ开发的Flutter插件，用于提高开发效率 triage-helperはIntelliJ用のFlutterプラグインで、開発効率を向上させる triage-helper는 IntelliJ용 플러터 플러그인으로 개발 효율을 향상시킵니다 El plugin de triage para IntelliJ es una herramienta para desarrolladores de Flutter que ayuda a simplificar el proceso de depuración y solución de problemas. Le plugin de triage pour IntelliJ est un outil pour les développeurs Flutter qui aide à simplifier le processus de débogage et de résolution de problèmes. Das Triage-Plugin für IntelliJ ist ein Tool für Flutter-Entwickler, das dabei hilft, den Prozess der Fehlersuche und -behebung zu vereinfachen. O Triage-Helper é um plugin para IntelliJ que facilita o desenvolvimento de aplicativos Flutter Triage-Helper - плагин для IntelliJ, упрощающий разработку приложений Flutter с помощью ИИ Агентов Triage-Helper هو إضافة لIntelliJ تسهل تطوير تطبيقات Flutter Flutter Plugin for IntelliJ 如何使用triage-helper 什么是triage-helper triage-helper替代品 triage-helper与其他工具的比较 triage-helper安装 triage-helper设置指南 Flutter开发工具 IntelliJ插件 Flutter Plugin for IntelliJ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shvydak/yshvydak-test-dashboard/coverage-master', 'community', 'shvydak', 'yshvydak-test-dashboard', 'shvydak/yshvydak-test-dashboard', 'coverage-master', 0, 0, 21, '2026-03-04T13:07:01.898Z', '2026-03-04T14:56:24.556Z', '8720692d8833859f021dab15bf61b0edf5a801cb5131e17e107a354e34ed8d90', '{"id":"shvydak/yshvydak-test-dashboard/coverage-master","name":"coverage-master","description":{"zh":"Coverage Master是用于提高代码测试效率的AI智能工具，基于playwright-test-dashboard","ja":"Coverage Masterはコードテストの効率を向上させるAIエージェントで、playwright-test-dashboardをベースに開発","ko":"Coverage Master는 코드 테스트 효율성을 향상시키는 AI 에이전트로 playwright-test-dashboard 기반으로 개발","es":"Coverage-master es una herramienta que utiliza playwright-test-dashboard para mejorar la cobertura de tus pruebas","fr":"Coverage-master est un outil qui utilise playwright-test-dashboard pour améliorer la couverture de vos tests","de":"Coverage-master ist ein Tool, das playwright-test-dashboard verwendet, um die Abdeckung Ihrer Tests zu verbessern","pt":"O coverage-master é uma ferramenta de teste avançada para playwright-test-dashboard, oferecendo recursos de teste automatizado","ru":"coverage-master — это продвинутый инструмент тестирования для playwright-test-dashboard, предлагающий функции автоматизированного тестирования","ar":"coverage-master هو أداة اختبار متقدمة لplaywright-test-dashboard، تقدم ميزات اختبار آلي","en":"playwright-test-dashboard"},"seo":{"title":{"zh":"AI智能工具Coverage Master","ja":"AIエージェント Coverage Master","ko":"AI 에이전트 Coverage Master","es":"Herramientas de coverage-master para desarrolladores","fr":"Outils coverage-master pour les développeurs","de":"Coverage-master Tools für Entwickler","pt":"Ferramentas de AI: coverage-master para playwright-test-d...","ru":"ИИ Агенты: coverage-master для playwright-test-dashboard","ar":"أدوات الذكاء الاصطناعي: coverage-master لplaywright-test-...","en":"coverage-master"},"description":{"zh":"Coverage Master是用于提高代码测试效率的AI智能工具，基于playwright-test-dashboard","ja":"Coverage Masterはコードテストの効率を向上させるAIエージェントで、playwright-test-dashboardをベースに開発","ko":"Coverage Master는 코드 테스트 효율성을 향상시키는 AI 에이전트로 playwright-test-dashboard 기반으로 개발","es":"Coverage-master es una herramienta que utiliza playwright-test-dashboard para mejorar la cobertura de tus pruebas","fr":"Coverage-master est un outil qui utilise playwright-test-dashboard pour améliorer la couverture de vos tests","de":"Coverage-master ist ein Tool, das playwright-test-dashboard verwendet, um die Abdeckung Ihrer Tests zu verbessern","pt":"O coverage-master é uma ferramenta de teste avançada para playwright-test-dashboard, oferecendo recursos de teste automatizado","ru":"coverage-master — это продвинутый инструмент тестирования для playwright-test-dashboard, предлагающий функции автоматизированного тестирования","ar":"coverage-master هو أداة اختبار متقدمة لplaywright-test-dashboard، تقدم ميزات اختبار آلي","en":"playwright-test-dashboard"},"definition":{"en":"playwright-test-dashboard"},"features":{"zh":["基于playwright-test-dashboard","提高代码测试效率","支持多种测试框架","提供详细的测试报告","易于集成和使用","支持CLI命令"],"ja":["playwright-test-dashboardをベースに開発","コードテストの効率を向上させる","複数のテストフレームワークをサポート","詳細なテストレポートを提供","簡単に統合および使用可能","CLIコマンドをサポート"],"ko":["playwright-test-dashboard 기반으로 개발","코드 테스트 효율성을 향상시킵니다","다수의 테스트 프레임워크를 지원","상세한 테스트 보고서를 제공","쉽게 통합 및 사용 가능","CLI 명령어를 지원"],"es":["Integración con playwright-test-dashboard","Análisis de cobertura de código","Informes detallados de pruebas","Optimización de pruebas automatizadas","Soporte para múltiples frameworks de testing"],"fr":["Intégration avec playwright-test-dashboard","Analyse de la couverture de code","Rapports détaillés de tests","Optimisation des tests automatisés","Prise en charge de plusieurs frameworks de testing"],"de":["Integration mit playwright-test-dashboard","Analyse der Codeabdeckung","Detaillierte Testberichte","Optimierung von automatisierten Tests","Unterstützung für mehrere Testing-Frameworks"],"pt":["Recursos de teste automatizado","Integração com playwright-test-dashboard","Relatórios de teste detalhados","Suporte a múltiplos ambientes de teste","Otimização de desempenho de teste"],"ru":["Функции автоматизированного тестирования","Интеграция с playwright-test-dashboard","Детальные отчеты о тестировании","Поддержка нескольких тестовых сред","Оптимизация производительности тестирования"],"ar":["ميزات اختبار آلي","التكامل مع playwright-test-dashboard","تقارير اختبار مفصلة","دعم بيئات اختبار متعددة","تحسين أداء الاختبار"]},"keywords":{"zh":["如何使用Coverage Master","什么是AI智能工具","Coverage Master替代品","Coverage Master vs Jest","Coverage Master安装","Coverage Master设置指南","playwright-test-dashboard教程","代码测试效率优化"],"ja":["Coverage Masterの使い方","AIエージェントとは","Coverage Masterの代替","Coverage Master vs Jest","Coverage Masterのインストール","Coverage Masterの設定ガイド","playwright-test-dashboardのチュートリアル","コードテストの効率化"],"ko":["Coverage Master 사용법","AI 에이전트란","Coverage Master 대안","Coverage Master vs Jest","Coverage Master 설치","Coverage Master 설정 가이드","playwright-test-dashboard 튜토리얼","코드 테스트 효율성 향상"],"es":["cómo usar coverage-master","herramientas de testing","playwright-test-dashboard","alternativas a coverage-master","instalación de coverage-master","guía de configuración de coverage-master"],"fr":["comment utiliser coverage-master","outils de testing","playwright-test-dashboard","alternatives à coverage-master","installation de coverage-master","guide de configuration de coverage-master"],"de":["wie man coverage-master verwendet","Testing-Tools","playwright-test-dashboard","Alternativen zu coverage-master","Installation von coverage-master","Konfigurationsanleitung für coverage-master"],"pt":["como usar coverage-master","o que é coverage-master","coverage-master vs playwright","instalar coverage-master","guia de configuração do coverage-master","alternativas ao coverage-master"],"ru":["как использовать coverage-master","что такое coverage-master","coverage-master vs playwright","установить coverage-master","руководство по настройке coverage-master","альтернативы coverage-master"],"ar":["كيفية استخدام coverage-master","ما هو coverage-master","coverage-master مقابل playwright","تثبيت coverage-master","دليل إعداد coverage-master","بديل coverage-master"]}},"owner":"shvydak","repo":"yshvydak-test-dashboard","repoPath":"shvydak/yshvydak-test-dashboard","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.898Z","topics":[],"category":"community","skillMd":{"name":"coverage-master","description":"Test Coverage Analyst. Enforces testing standards and identifies gaps.","bodyPreview":"# Coverage Master Protocol\n\nYou are the **Test Enforcer**. Your goal is to ensure no code goes untested.\n\n## 🎯 Targets\n\n- **Reporter:** 90% (Critical - Test ID generation)\n- **Server:** 80%\n- **Web:** 70%\n\n## 🔄 Workflow\n\n1.  **Analyze Context:**\n    - Look at the files created/modified in the last turn (or by `git diff`).\n    - Identify: Did we add a new Service? A new Endpoint? A new Utility?\n\n2.  **Gap Detection:**\n    - For every `*.service.ts`, check if `__tests__/*.service.test.ts` exists","body":"# Coverage Master Protocol\n\nYou are the **Test Enforcer**. Your goal is to ensure no code goes untested.\n\n## 🎯 Targets\n\n- **Reporter:** 90% (Critical - Test ID generation)\n- **Server:** 80%\n- **Web:** 70%\n\n## 🔄 Workflow\n\n1.  **Analyze Context:**\n    - Look at the files created/modified in the last turn (or by `git diff`).\n    - Identify: Did we add a new Service? A new Endpoint? A new Utility?\n\n2.  **Gap Detection:**\n    - For every `*.service.ts`, check if `__tests__/*.service.test.ts` exists.\n    - For every `*.controller.ts`, check if an integration test exists.\n    - Use `run_shell_command(\"ls ...\")` to verify file existence.\n\n3.  **Coverage Check (Optional):**\n    - If requested, run `npm run test:coverage` (Warning: this is slow).\n    - Prefer targetted testing: `npm test -- related_file.ts`.\n\n4.  **Action:**\n    - **Missing Test?** -> \"⚠️ Created `UserService` but found no test. Creating test skeleton...\"\n    - **Write Test:** Use `write_file` to create the missing test following the patterns in `packages/*/src/__tests__/`.\n\n## 🧪 Best Practices\n\n- Mock external dependencies (Database, WebSocket).\n- Test edge cases (null, empty arrays, errors).\n"},"lastSynced":"2026-03-04T14:56:24.556Z","agentAnalysis":{"suitability":{"en":"Ideal for Test Automation Agents requiring comprehensive code coverage analysis and enforcement","zh":"适用于需要全面代码覆盖分析和执行的测试自动化代理","ja":"包括React、Pythonなどのコードの包括的なカバレッジ分析と適用が必要なテスト自動化エージェントに適しています","ko":"전체 코드 커버리지 분석 및 적용이 필요한 테스트 자동화 에이전트에 적합합니다","es":"Ideal para Test Automation Agents que requieren análisis y aplicación exhaustiva de la cobertura de código","fr":"Idéal pour les Test Automation Agents nécessitant une analyse et une application complètes de la couverture de code","de":"Ideal für Test Automation Agents, die eine umfassende Analyse und Durchsetzung der Codeabdeckung benötigen","pt":"Ideal para Agentes de Automação de Testes que exigem análise e aplicação abrangentes de cobertura de código","ru":"Идеально для агентов автоматизации тестирования, требующих всестороннего анализа и обеспечения покрытия кода","ar":"مثالي لعميل تلقيم اختبار التلقائي الذي يتطلب تحليل وتطبيق شاملي لتغطية الشفرة"},"recommendation":{"en":"Empowers agents to enforce 90% test coverage for critical components like Reporter, utilizing protocols such as the Coverage Master Protocol, and integrating with tools like playwright-test-dashboard to ensure thorough testing of Services, Endpoints, and Utilities, via gap detection in __tests__ directories","zh":"赋予代理执行关键组件（如Reporter）90%的测试覆盖率，利用Coverage Master Protocol等协议，并集成playwright-test-dashboard等工具，以确保对Services、Endpoints和Utilities进行彻底的测试，通过在__tests__目录中检测缺口","ja":"エージェントに、レポーターなどの重要なコンポーネントに対して90%のテストカバレッジを適用させることができます。Coverage Master Protocolなどのプロトコルを利用し、playwright-test-dashboardなどのツールと統合して、Services、Endpoints、Utilitiesなどのテストを徹底的に行い、__tests__ディレクトリ内のギャップを検出します","ko":"에이전트에 Reporter와 같은 중요한 구성 요소에 대해 90%의 테스트 커버리지 적용을 가능하게 함으로써 Coverage Master Protocol과 같은 프로토콜을 사용하고 playwright-test-dashboard와 같은 도구와 통합하여 서비스, 엔드ポイント 및 유틸리티에 대한 철저한 테스트를 보장하며 __tests__ 디렉토리에서 격차를 감지함","es":"Permite a los agents aplicar una cobertura de pruebas del 90% para componentes críticos como Reporter, utilizando protocolos como el Coverage Master Protocol e integrando con herramientas como playwright-test-dashboard para garantizar pruebas exhaustivas de Services, Endpoints y Utilities, mediante la detección de brechas en directorios __tests__","fr":"Permet aux agents d''appliquer une couverture de tests de 90 % pour les composants critiques comme Reporter, en utilisant des protocoles tels que le Coverage Master Protocol et en s''intégrant à des outils comme playwright-test-dashboard pour assurer des tests approfondis des Services, Endpoints et Utilities, via la détection des lacunes dans les répertoires __tests__","de":"Ermöglicht Agents die Durchsetzung einer Testabdeckung von 90 % für kritische Komponenten wie Reporter unter Verwendung von Protokollen wie dem Coverage Master Protocol und der Integration mit Tools wie playwright-test-dashboard, um gründliche Tests von Services, Endpoints und Utilities durch Erkennung von Lücken in __tests__-Verzeichnissen sicherzustellen","pt":"Habilita agentes a aplicar 90% de cobertura de testes para componentes críticos como Reporter, utilizando protocolos como o Coverage Master Protocol, e integrando com ferramentas como playwright-test-dashboard para garantir testes abrangentes de Serviços, Endpoints e Utilitários, via detecção de lacunas em diretórios __tests__","ru":"Наделяет агентов возможностью обеспечить 90% покрытия тестов для критических компонентов, таких как Reporter, используя протоколы, такие как Coverage Master Protocol, и интегрируя с инструментами, такими как playwright-test-dashboard, для обеспечения тщательного тестирования Служб, Конечных точек и Утилит, посредством обнаружения пробелов в директориях __tests__","ar":"يتمكن العملاء من تطبيق 90% من تغطية الاختبار للعناصر الحيوية مثل Reporter، باستخدام بروتوكولات مثل بروتوكول Coverage Master ، ودمجها مع أدوات مثل playwright-test-dashboard لضمان اختبار شامل للخدمات والنقاط النهائية والمرافق، من خلال اكتشاف الفجوات في مجلدات __tests__"},"useCases":{"en":["Enforcing test coverage thresholds for new Services and Endpoints","Automating gap detection in test suites for Utilities and Servers","Analyzing code modifications to ensure adequate test coverage"],"zh":["执行新服务和端点的测试覆盖率阈值","自动检测测试套件中的Utilities和Servers的缺口","分析代码修改以确保足够的测试覆盖率"],"ja":["新しいサービスやエンドポイントのテストカバレッジのしきい値を適用する","テストスイートのUtilitiesやServersのギャップを自動で検出する","コードの変更を分析して十分なテストカバレッジを確保する"],"ko":["新的 서비스 및 엔드ポイント에 대한 테스트 커버리지 임계값 적용","테스트 스위트에서 유틸리티 및 서버의 격차 자동 감지","코드 변경 분석을 통해 충분한 테스트 커버리지 보장"],"es":["Aplicación de umbrales de cobertura de pruebas para nuevos Services y Endpoints","Automatización de la detección de brechas en suites de pruebas para Utilities y Servers","Análisis de modificaciones de código para garantizar una cobertura de pruebas adecuada"],"fr":["Application des seuils de couverture de tests pour les nouveaux Services et Endpoints","Automatisation de la détection des lacunes dans les suites de tests pour les Utilities et Servers","Analyse des modifications de code pour assurer une couverture de tests adéquate"],"de":["Durchsetzung von Testabdeckungs-Schwellenwerten für neue Services und Endpoints","Automatisierung der Lückenerkennung in Testsuites für Utilities und Servers","Analyse von Codeänderungen zur Sicherstellung einer angemessenen Testabdeckung"],"pt":["Aplicar limites de cobertura de testes para novos Serviços e Endpoints","Automatizar detecção de lacunas em conjuntos de testes para Utilitários e Servidores","Analisar modificações de código para garantir cobertura de testes adequada"],"ru":["Обеспечить пороги покрытия тестов для новых Служб и Конечных точек","Автоматизировать обнаружение пробелов в наборах тестов для Утилит и Серверов","Анализировать изменения кода для обеспечения достаточного покрытия тестов"],"ar":["تطبيق حدود تغطية الاختبار للخدمات والنقاط النهائية الجديدة","تحسين اكتشاف الفجوات في مجموعات الاختبار للبرامج والخادم","تحليل تعديلات الشفرة لضمان تغطية اختبار كافية"]},"limitations":{"en":["Requires access to code repositories and version control systems like git","Limited to specific test coverage targets (e.g., 90% for Reporter, 80% for Server)"],"zh":["需要访问代码仓库和版本控制系统，如git","仅限于特定的测试覆盖率目标（例如，Reporter为90%，Server为80%）"],"ja":["コードリポジトリやgitなどのバージョン管理システムへのアクセスが必要","特定のテストカバレッジの目標（例：レポーターは90%、サーバーは80%）に限定される"],"ko":["코드 저장소 및 버전 관리 시스템인 git와 같은 시스템에 대한 액세스가 필요합니다.","특정 테스트 커버리지 목표(예: Reporter는 90%, Server는 80%)에 한정됨"],"es":["Requiere acceso a repositorios de código y sistemas de control de versiones como git","Limitado a objetivos de cobertura de pruebas específicos (por ejemplo, 90 % para Reporter, 80 % para Server)"],"fr":["Nécessite un accès aux dépôts de code et aux systèmes de contrôle de version comme git","Limité à des objectifs de couverture de tests spécifiques (par exemple, 90 % pour Reporter, 80 % pour Server)"],"de":["Erfordert Zugriff auf Code-Repositories und Versionskontrollsysteme wie git","Beschränkt auf spezifische Testabdeckungsziele (z. B. 90 % für Reporter, 80 % für Server)"],"pt":["Exige acesso a repositórios de código e sistemas de controle de versão como git","Limitado a objetivos de cobertura de testes específicos (por exemplo, 90% para Reporter, 80% para Servidor)"],"ru":["Требует доступа к хранилищам кода и системам контроля версий, таким как git","Ограничен конкретными целями покрытия тестов (например, 90% для Reporter, 80% для Сервера)"],"ar":["يتطلب الوصول إلى مستودعات الشفرة وأنظمة التحكم في الإصدار مثل جيت","محدود بأهداف تغطية الاختبار المحددة (على سبيل المثال 90% لمُبلّغ، 80% للخادم)"]},"version":3},"contentHash":"8720692d8833859f021dab15bf61b0edf5a801cb5131e17e107a354e34ed8d90","qualityScore":21}');
