INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shvydak/yshvydak-test-dashboard/coverage-master', 'coverage-master', 'shvydak', 'yshvydak-test-dashboard', 'community', 'coverage-master shvydak yshvydak-test-dashboard community Coverage Master是用于提高代码测试效率的AI智能工具，基于playwright-test-dashboard Coverage Masterはコードテストの効率を向上させるAIエージェントで、playwright-test-dashboardをベースに開発 Coverage Master는 코드 테스트 효율성을 향상시키는 AI 에이전트로 playwright-test-dashboard 기반으로 개발 Coverage-master es una herramienta que utiliza playwright-test-dashboard para mejorar la cobertura de tus pruebas Coverage-master est un outil qui utilise playwright-test-dashboard pour améliorer la couverture de vos tests Coverage-master ist ein Tool, das playwright-test-dashboard verwendet, um die Abdeckung Ihrer Tests zu verbessern O coverage-master é uma ferramenta de teste avançada para playwright-test-dashboard, oferecendo recursos de teste automatizado coverage-master — это продвинутый инструмент тестирования для playwright-test-dashboard, предлагающий функции автоматизированного тестирования coverage-master هو أداة اختبار متقدمة لplaywright-test-dashboard، تقدم ميزات اختبار آلي playwright-test-dashboard 如何使用Coverage Master 什么是AI智能工具 Coverage Master替代品 Coverage Master vs Jest Coverage Master安装 Coverage Master设置指南 playwright-test-dashboard教程 代码测试效率优化 playwright-test-dashboard');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sf-bcca/Kith/kith-ux-polisher', 'community', 'sf-bcca', 'Kith', 'sf-bcca/Kith', 'kith-ux-polisher', 0, 0, 21, '2026-03-04T13:07:01.899Z', '2026-03-04T14:56:40.541Z', '4936dd91d11dc69c2995d6b623aa11d07722c8fbcb32c8d568f7ac793f9c17d0', '{"id":"sf-bcca/Kith/kith-ux-polisher","name":"kith-ux-polisher","description":{"zh":"Kith-ux-polisher是一个现代、用户友好的家族树应用，使用React和Python构建。它提供了直观的界面和强大的功能","ja":"Kith-ux-polisherは、AIエージェントを使用した家族樹アプリです。Node.jsとCLIをサポートし、開発者向けのツールとして最適化","ko":"Kith-ux-polisher는 최신의 가족 나무 애플리케이션으로 Python 및 React를 사용하여 개발되었습니다. 사용자 친화적인 인터페이스와 강력한 기능을 제공","es":"Kith es una aplicación de árbol genealógico moderna y fácil de usar, diseñada para ayudar a las familias a organizar su historia","fr":"Kith est une application d''arbre généalogique moderne et conviviale, conçue pour aider les familles à organiser leur histoire","de":"Kith ist eine moderne und benutzerfreundliche Genealogie-Anwendung, die dazu dient, Familien bei der Organisation ihrer Geschichte zu unterstützen","pt":"Kith é uma aplicação de árvore genealógica moderna e amigável. Melhore a experiência do usuário com Kith-UX-Polisher","ru":"Kith - современное и удобное приложение для создания дерева рода. Улучшите пользовательский опыт с помощью Kith-UX-Polisher","ar":"Kith هو تطبيق شجرة عائلة حديث وسهل الاستخدام. تحسين تجربة المستخدم مع Kith-UX-Polisher","en":"Kith is a modern, user friendly, family tree application."},"seo":{"title":{"zh":"Kith-ux-polisher：人工智能家族树应用","ja":"Kith-ux-polisher：AIエージェントによる家族樹アプリ","ko":"Kith-ux-polisher：AI 에이전트를 사용한 가족 나무 애플리케이션","es":"Herramienta de árbol genealógico Kith-ux-polisher","fr":"Outil d''arbre généalogique Kith-ux-polisher","de":"Kith-ux-polisher Genealogie-Tool","pt":"Kith-UX-Polisher: Ferramenta de Árvore Genealógica com IA","ru":"Kith-UX-Polisher: ИИ Агент для Создания Дерева Рода","ar":"Kith-UX-