INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sf-bcca/Kith/kith-ux-polisher', 'kith-ux-polisher', 'sf-bcca', 'Kith', 'community', 'kith-ux-polisher sf-bcca Kith community Kith-ux-polisher是一个现代、用户友好的家族树应用，使用React和Python构建。它提供了直观的界面和强大的功能 Kith-ux-polisherは、AIエージェントを使用した家族樹アプリです。Node.jsとCLIをサポートし、開発者向けのツールとして最適化 Kith-ux-polisher는 최신의 가족 나무 애플리케이션으로 Python 및 React를 사용하여 개발되었습니다. 사용자 친화적인 인터페이스와 강력한 기능을 제공 Kith es una aplicación de árbol genealógico moderna y fácil de usar, diseñada para ayudar a las familias a organizar su historia Kith est une application d''arbre généalogique moderne et conviviale, conçue pour aider les familles à organiser leur histoire Kith ist eine moderne und benutzerfreundliche Genealogie-Anwendung, die dazu dient, Familien bei der Organisation ihrer Geschichte zu unterstützen Kith é uma aplicação de árvore genealógica moderna e amigável. Melhore a experiência do usuário com Kith-UX-Polisher Kith - современное и удобное приложение для создания дерева рода. Улучшите пользовательский опыт с помощью Kith-UX-Polisher Kith هو تطبيق شجرة عائلة حديث وسهل الاستخدام. تحسين تجربة المستخدم مع Kith-UX-Polisher Kith is a modern, user friendly, family tree application. 如何使用Kith-ux-polisher 什么是家族树应用 Kith-ux-polisher安装 Kith-ux-polisher设置指南 Kith-ux-polisher替代品 Kith-ux-polisher vs 其他家族树应用 Kith is a modern, user friendly, family tree application.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sphildreth/decentdb/nim', 'community', 'sphildreth', 'decentdb', 'sphildreth/decentdb', 'nim', 0, 0, 21, '2026-03-04T13:07:01.911Z', '2026-03-04T15:00:55.320Z', 'bbbb3a7cdc46fffe321239ab8a8882561ae6670a6fd9e03be7530164041fbb16', '{"id":"sphildreth/decentdb/nim","name":"nim","description":{"zh":"Nim AI智能代理以ACID为首要任务，其他功能也在不断开发中","ja":"Nim AIエージェントはACIDを第一にし，その他の機能も順次開発中","ko":"Nim AI 에이전트는 ACID를 우선하고 다른 기능도 점진적으로 개발 중","es":"Nim es una herramienta de AI que prioriza ACID, permitiendo a los desarrolladores crear soluciones escalables","fr":"Nim est un outil d''IA qui donne la priorité à ACID, permettant aux développeurs de créer des solutions évolutives","de":"Nim ist ein KI-Tool, das ACID priorisiert, damit Entwickler skalierbare Lösungen erstellen können","pt":"O Nim é uma ferramenta de IA que prioriza a consistência ACID, garantindo a integridade dos dados em seus projetos","ru":"Nim - это ИИ Агент, который отдаёт приоритет согласованности ACID, обеспечивая целостность данных в ваших проектах","ar":"نم هو أداة ذكاء اصطناعي تركز على الاتساق ACID، مما يضمن سلامة البيانات في مشاريعك","en":"ACID first. Everything else… eventually."},"seo":{"title":{"zh":"Nim AI智能代理：ACID优先","ja":"Nim AIエージェント：ACIDを優先","ko":"Nim AI 에이전트: ACID 우선","es":"Herramientas de AI: Nim prioriza ACID","fr":"Outils d''IA : Nim donne la priorité à ACID","de":"KI-Tools: Nim priorisiert ACID","pt":"Ferramentas de IA: O que é Nim?","ru":"ИИ Агенты: Nim - основа ACID","ar":"أدوات الذكاء الاصطناعي: نم - أولاً وقبل كل شيء","en":"nim"},"description":{"zh":"Nim AI智能代理以ACID为首要任务，其他功能也在不断开发中","ja":"Nim AIエージェントはACIDを第一にし，その他の機能も順次開発中","ko":"Nim AI 에이전트는 ACID를 우선하고 다른 기능도 점진적으로 개발 중","es":"Nim es una herramienta de AI que prioriza ACID, permitiendo a los desarrolladores crear soluciones escalables","fr":"Nim est un outil d''IA qui donne la priorité à ACID, permettant aux développeurs de créer des solutions évolutives","de":"Nim ist ein KI-Tool, das ACID priorisiert, damit Entwickler skalierbare Lösungen erstellen können","pt":"O Nim é uma ferramenta de IA que prioriza a consistência ACID, garantindo a integridade dos dados em seus projetos","ru":"Nim - это ИИ Агент, который отдаёт приоритет согласованности ACID, обеспечивая целостность данных в ваших проектах","ar":"نم هو أداة ذكاء اصطناعي تركز على الاتساق ACID، مما يضمن سلامة البيانات في مشاريعك","en":"ACID first. Everything else… eventually."},"definition":{"en":"ACID first. Everything else… eventually."},"features":{"zh":["ACID优先的开发","高性能的AI处理","多功能的开发工具","简单易用的CLI接口","支持多种编程语言"],"ja":["ACIDを優先した開発","高性能のAI処理","多機能の開発ツール","シンプルで使いやすいCLIインターフェース","多くのプログラミング言語をサポート"],"ko":["ACID 우선의 개발","고성능의 AI 처리","다기능의 개발 도구","간단하고 쉬운 CLI 인터페이스","多くの 프로그래밍 언어를 지원"],"es":["Priorización de ACID","Escalabilidad","Consistencia de datos","Flexibilidad para desarrolladores","Integración con herramientas de desarrollo"],"fr":["Priorité à ACID","Évolutivité","Cohérence des données","Flexibilité pour les développeurs","Intégration avec les outils de développement"],"de":["Priorisierung von ACID","Skalierbarkeit","Datenkonsistenz","Flexibilität für Entwickler","Integration mit Entwicklungstools"],"pt":["Priorização da consistência ACID","Garantia da integridade dos dados","Desenvolvimento de projetos confiáveis","Integração com tecnologias de IA","Suporte a desenvolvedores"],"ru":["Приоритет согласованности ACID","Обеспечение целостности данных","Разработка надёжных проектов","Интеграция с технологиями ИИ","Поддержка разработчиков"],"ar":["أولوية الاتساق ACID","ضمان سلامة البيانات","تطوير مشاريع موثوقة","التكامل مع تكنولوجيا الذكاء الاصطناعي","دعم المطورين"]},"keywords":{"zh":["Nim AI智能代理","ACID优先的开发工具","AI工具安装","Nim AI智能代理教程","如何使用Nim AI智能代理","Nim AI智能代理与其他AI工具的比较"],"ja":["Nim AIエージェント","ACIDを優先する開発ツール","AIエージェントのインストール","Nim AIエージェントのチュートリアル","Nim AIエージェントの使い方","Nim AIエージェントと他のAIエージェントの比較"],"ko":["Nim AI 에이전트","ACID 우선의 개발 도구","AI 에이전트 설치","Nim AI 에이전트 튜토리얼","Nim AI 에이전트 사용법","Nim AI 에이전트와 다른 AI 에이전트의 비교"],"es":["herramientas de AI","Nim","ACID","desarrollo de software","escalabilidad","consistencia de datos","cómo usar Nim","alternativas a Nim"],"fr":["outils d''IA","Nim","ACID","développement de logiciels","évolutivité","cohérence des données","comment utiliser Nim","alternatives à Nim"],"de":["KI-Tools","Nim","ACID","Softwareentwicklung","Skalierbarkeit","Datenkonsistenz","wie man Nim verwendet","Alternativen zu Nim"],"pt":["ferramentas de ia","o que é nim","como usar nim","nim vs outros agentes","guia de instalação do nim","desenvolvimento de projetos com nim","ia e acide","nim e desenvolvedores"],"ru":["ИИ агенты","что такое nim","как использовать nim","nim vs другие агенты","руководство по установке nim","разработка проектов с nim","ИИ и acid","nim и разработчики"],"ar":["أدوات الذكاء الاصطناعي","ما هو نم","كيفية استخدام نم","نم مقابل أدوات أخرى","دليل تثبيت نم","تطوير مشاريع مع نم","الذكاء الاصطناعي والاتساق","نم والمطورون"]}},"owner":"sphildreth","repo":"decentdb","repoPath":"sphildreth/decentdb","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.911Z","topics":[],"category":"community","skillMd":{"name":"nim","description":"Guidance for making safe, minimal-diff Nim changes in DecentDB with tests and durability/isolation rules.","bodyPreview":"# Skill: Nim Specialist (DecentDB)\n\nYou are an expert Nim coding agent working in the DecentDB repository.\n\n## Mission\n\nImplement the user’s requested change in Nim with minimal diffs, preserving ACID durability and Snapshot Isolation semantics.\n\n## Hard constraints (must follow)\n\n- Read `AGENTS.md` first; follow its workflow and Definition of Done.\n- If the change could affect:\n  - persistent formats (db header/page layout/WAL frame format/postings format)\n  - checkpoint/truncation rules\n  - lo","body":"# Skill: Nim Specialist (DecentDB)\n\nYou are an expert Nim coding agent working in the DecentDB repository.\n\n## Mission\n\nImplement the user’s requested change in Nim with minimal diffs, preserving ACID durability and Snapshot Isolation semantics.\n\n## Hard constraints (must follow)\n\n- Read `AGENTS.md` first; follow its workflow and Definition of Done.\n- If the change could affect:\n  - persistent formats (db header/page layout/WAL frame format/postings format)\n  - checkpoint/truncation rules\n  - locking/concurrency semantics\n  - isolation guarantees\n  - SQL grammar/dialect behavior\n  then **STOP** and propose an ADR in `design/adr/` before implementing.\n- Do not add dependencies unless explicitly requested/approved.\n- No drive-by refactors. Keep diffs small and targeted.\n\n## Method (Nim-specific)\n\n1. **Orient**\n   - Find the existing entrypoints and patterns in `src/` and `tests/`.\n   - Prefer extending existing modules over introducing new utility modules.\n\n2. **Implement explicitly**\n   - Prefer straightforward procedures and data structures over macro-heavy solutions.\n   - Keep error handling consistent with repo strategy (see `design/adr/0010-error-handling-strategy.md`).\n\n3. **Performance discipline**\n   - Avoid accidental allocations in hot paths.\n     - Avoid repeated string concatenation in loops.\n     - Reuse buffers/sequences where appropriate.\n   - Avoid logging overhead unless gated and zero-cost when disabled.\n\n4. **Testing (required)**\n   - Add/adjust unit tests for main behavior + edge cases.\n   - If a change impacts durability/correctness invariants, add relevant crash/differential/property tests per `design/TESTING_STRATEGY.md`.\n\n5. **Validate**\n   - Run the narrowest relevant compile/test commands first.\n   - Do not ignore failing tests; fix failures caused by your change.\n\n## FFI / C ABI rules (only when applicable)\n\n- Use `{.exportc, cdecl, dynlib.}` for exported functions.\n- Prefer inputs as `(cstring, length)` for text/blob payloads.\n- Never return unstable pointers without clear lifetime rules; define ownership and invalidation points.\n- Assume statement handles are not safe for concurrent use across threads.\n\n## Deliverables\n\n- Code changes in Nim\n- Tests covering the new behavior\n- A brief report:\n  - files/symbols changed\n  - commands run\n  - any remaining risks or follow-ups\n"},"lastSynced":"2026-03-04T15:00:55.320Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Generation Agents specializing in systems programming with Nim, requiring expertise in ACID durability and Snapshot Isolation semantics.","zh":"适用于专门从事Nim系统编程的代码生成代理，需要在ACID耐用性和快照隔离语义方面具有专业知识。","ja":"Nimを用いたシステムプログラミングを専門とするコード生成エージェントに適しています。ACID耐久性とスナップショット分離セマンティクスに精通している必要があります。","ko":"Nim을 사용한 시스템 프로그래밍을 전문으로 하는 코드 생성 에이전트에 적합합니다. ACID 내구성 및 스냅샷 분리 의미론에 대한 전문 지식이 필요합니다.","es":"Ideal para agentes de generación de código que se especializan en programación de sistemas con Nim, que requieren experiencia en durabilidad ACID y semántica de aislamiento de instantáneas.","fr":"Idéal pour les agents de génération de code spécialisés dans la programmation système avec Nim, nécessitant une expertise dans la durabilité ACID et la sémantique d''isolement d''instantané.","de":"Ideal für Code-Generierungsagenten, die sich auf Systemprogrammierung mit Nim spezialisieren und Erfahrung in ACID-Haltbarkeit und Snapshot-Isolationssemantik erfordern.","pt":"Ideal para Agentes de Geração de Código especializados em programação de sistemas com Nim, que exigem conhecimento em durabilidade ACID e semântica de Isolamento de Instantâneo.","ru":"Идеально подходит для агентов генерации кода, специализирующихся на системном программировании с помощью Nim, требующих знаний в области долговечности ACID и семантики изоляции снимка.","ar":"مثالي للوكلاء مولدون للرمز المتخصصون في برمجة الأنظمة باستخدام Nim ، والذين يتطلبون الخبرة في متانة ACID و семантика عزل اللقطة."},"recommendation":{"en":"Empowers agents to implement user-requested changes in Nim with minimal diffs, preserving ACID durability and Snapshot Isolation semantics, while working within the DecentDB repository and adhering to AGENTS.md workflow and Definition of Done, utilizing persistent formats like db header/page layout/WAL frame format/postings format.","zh":"赋予代理在Nim中实施用户请求的更改的能力，尽量减少diff，同时保持ACID耐用性和快照隔离语义，在DecentDB存储库中工作并遵循AGENTS.md工作流和完成定义，使用诸如db头/页布局/WAL帧格式/帖子格式等持久格式。","ja":"エージェントに、Nimでユーザー要求の変更を実装する能力を与え、diffを最小限に抑えながら、ACID耐久性とスナップショット分離セマンティクスを保持します。DecentDBリポジトリ内で作業し、AGENTS.mdワークフローと完了の定義に従い、dbヘッダ/ページレイアウト/WALフレーム形式/投稿形式などの持続的な形式を使用します。","ko":"에이전트가 Nim에서 사용자 요청의 변경 사항을 구현할 수 있는 능력을 부여하여 diff를 최소화하면서 ACID 내구성 및 스냅샷 분리 의미론을 유지합니다. DecentDB 저장소에서 작업하며 AGENTS.md 워크플로 및 완료 정의를 따라 규칙을 최적화하고 db 헤더/페이지 레이아웃/WAL 프레임 형식/게시물 형식과 같은 지속 가능한 형식을 사용합니다.","es":"Permite a los agentes implementar cambios solicitados por el usuario en Nim con difuminaciones mínimas, preservando la durabilidad ACID y la semántica de aislamiento de instantáneas, mientras trabajan dentro del repositorio DecentDB y se adhieren al flujo de trabajo AGENTS.md y la definición de Done, utilizando formatos persistentes como formato de encabezado de base de datos/página/diseño de cuadro WAL/formato de publicaciones.","fr":"Permet aux agents de mettre en œuvre les modifications demandées par l''utilisateur dans Nim avec des diffusions minimales, en préservant la durabilité ACID et la sémantique d''isolement d''instantané, tout en travaillant dans le référentiel DecentDB et en respectant le flux de travail AGENTS.md et la définition de Done, en utilisant des formats persistants tels que le format d''en-tête de base de données/disposition de page/cadre WAL/format de publications.","de":"Ermöglicht es Agenten, Benutzeranforderungen in Nim mit minimalen Diffs umzusetzen, während die ACID-Haltbarkeit und die Snapshot-Isolationssemantik erhalten bleiben, und zwar innerhalb des DecentDB-Repositorys und unter Einhaltung des AGENTS.md-Workflows und der Definition von Done, unter Verwendung von persistenten Formaten wie Datenbank-Header-/Seiten-/WAL-Rahmen-/Veröffentlichungsformat.","pt":"Habilita os agentes a implementar alterações solicitadas pelo usuário em Nim com diferenças mínimas, preservando a durabilidade ACID e a semântica de Isolamento de Instantâneo, trabalhando dentro do repositório DecentDB e aderindo ao fluxo de trabalho AGENTS.md e Definição de Concluído, utilizando formatos persistentes como formato de cabeçalho de banco de dados / layout de página / formato de frame WAL / formato de postagens.","ru":"Наделяет агентов возможностью реализовывать изменения, запрошенные пользователем в Nim, с минимальными изменениями, сохраняя долговечность ACID и семантику изоляции снимка, работая в рамках репозитория DecentDB и придерживаясь рабочего процесса AGENTS.md и определения готовности, используя постоянные форматы, такие как формат заголовка базы данных / макет страницы / формат кадра WAL / формат публикаций.","ar":"يمكن للوكلاء تنفيذ التغييرات المطلوبة من قبل المستخدم في Nim مع فرق tối thiểu ، مع الحفاظ على متانة ACID و семантика عزل اللقطة ، والعمل داخل مستودع DecentDB و اتباع سير العمل AGENTS.md و تعريف الإنجاز ، باستخدام تنسيقات مستمرة مثل تنسيق رأس قاعدة البيانات / تخطيط الصفحة / تنسيق إطار WAL / تنسيق المنشورات."},"useCases":{"en":["Implementing changes in Nim while maintaining ACID compliance","Preserving Snapshot Isolation semantics in DecentDB","Optimizing database checkpoint/truncation rules for performance"],"zh":["在Nim中实施更改，同时保持ACID兼容性","在DecentDB中保留快照隔离语义","优化数据库检查点/截断规则以提高性能"],"ja":["Nimで変更を実装しながらACID準拠を維持する","DecentDBでスナップショット分離セマンティクスを保持する","データベースのチェックポイント/トランケーションルールを最適化してパフォーマンスを向上させる"],"ko":["Nim에서 변경 사항을 구현하면서 ACID 호환성을 유지하는 것","DecentDB에서 스냅샷 분리 의미론을 유지하는 것","데이터베이스 체크포인트/트렁케이션 규칙을 최적화하여 성능을 향상시키는 것"],"es":["Implementar cambios en Nim mientras se mantiene la conformidad con ACID","Preservar la semántica de aislamiento de instantáneas en DecentDB","Optimizar las reglas de punto de control/truncamiento de la base de datos para el rendimiento"],"fr":["Mettre en œuvre des modifications dans Nim tout en maintenant la conformité avec ACID","Préserver la sémantique d''isolement d''instantané dans DecentDB","Optimiser les règles de point de contrôle/troncature de la base de données pour les performances"],"de":["Änderungen in Nim umsetzen, während die ACID-Konformität aufrechterhalten wird","Die Snapshot-Isolationssemantik in DecentDB erhalten","Datenbank-Checkpoint-/Trunkierungsregeln für die Leistung optimieren"],"pt":["Implementar alterações em Nim enquanto mantém a conformidade ACID","Preservar a semântica de Isolamento de Instantâneo no DecentDB","Otimizar regras de ponto de verificação / truncamento do banco de dados para desempenho"],"ru":["Реализовывать изменения в Nim, сохраняя при этом соответствие ACID","Сохранять семантику изоляции снимка в DecentDB","Оптимизировать правила контрольной точки / обрезки базы данных для производительности"],"ar":["تنفيذ التغييرات في Nim مع الحفاظ على مطابقة ACID","الحفاظ على семантика عزل اللقطة في DecentDB","تحسين قواعد التحقق / القطع من قاعدة البيانات للأداء"]},"limitations":{"en":["Requires adherence to AGENTS.md workflow and Definition of Done","Limited to Nim programming language","Must consider effects on persistent formats and checkpoint/truncation rules"],"zh":["需要遵循AGENTS.md工作流和完成定义","仅限于Nim编程语言","必须考虑对持久格式和检查点/截断规则的影响"],"ja":["AGENTS.mdワークフローと完了の定義に従う必要がある","Nimプログラミング言語のみに限定される","持続的な形式とチェックポイント/トランケーションルールへの影響を考慮する必要がある"],"ko":["AGENTS.md 워크플로 및 완료 정의를 따라야 함","Nim 프로그래밍 언어에만限定됨","지속 가능한 형식 및 체크포인트/트렁케이션 규칙에 대한 영향을 고려해야 함"],"es":["Requiere la adhesión al flujo de trabajo AGENTS.md y la definición de Done","Limitado al lenguaje de programación Nim","Debe considerar los efectos en los formatos persistentes y las reglas de punto de control/truncamiento"],"fr":["Nécessite l''adhésion au flux de travail AGENTS.md et à la définition de Done","Limité au langage de programmation Nim","Doit prendre en compte les effets sur les formats persistants et les règles de point de contrôle/troncature"],"de":["Erfordert die Einhaltung des AGENTS.md-Workflows und der Definition von Done","Begrenzt auf die Programmiersprache Nim","Muss die Auswirkungen auf persistente Formate und Checkpoint-/Trunkierungsregeln berücksichtigen"],"pt":["Exige adesão ao fluxo de trabalho AGENTS.md e Definição de Concluído","Limitado à linguagem de programação Nim","Deve considerar os efeitos nos formatos persistentes e regras de ponto de verificação / truncamento"],"ru":["Требует соблюдения рабочего процесса AGENTS.md и определения готовности","Ограничен языком программирования Nim","Должен учитывать влияние на постоянные форматы и правила контрольной точки / обрезки"],"ar":["يتطلب اتباع سير العمل AGENTS.md و تعريف الإنجاز","محدود بلغة برمجة Nim","يجب مراعاة الآثار على التنسيقات المستمرة و قواعد التحقق / القطع"]},"version":3},"contentHash":"bbbb3a7cdc46fffe321239ab8a8882561ae6670a6fd9e03be7530164041fbb16","qualityScore":21}');
