INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sphildreth/decentdb/nim', 'nim', 'sphildreth', 'decentdb', 'community', 'nim sphildreth decentdb community Nim AI智能代理以ACID为首要任务，其他功能也在不断开发中 Nim AIエージェントはACIDを第一にし，その他の機能も順次開発中 Nim AI 에이전트는 ACID를 우선하고 다른 기능도 점진적으로 개발 중 Nim es una herramienta de AI que prioriza ACID, permitiendo a los desarrolladores crear soluciones escalables Nim est un outil d''IA qui donne la priorité à ACID, permettant aux développeurs de créer des solutions évolutives Nim ist ein KI-Tool, das ACID priorisiert, damit Entwickler skalierbare Lösungen erstellen können O Nim é uma ferramenta de IA que prioriza a consistência ACID, garantindo a integridade dos dados em seus projetos Nim - это ИИ Агент, который отдаёт приоритет согласованности ACID, обеспечивая целостность данных в ваших проектах نم هو أداة ذكاء اصطناعي تركز على الاتساق ACID، مما يضمن سلامة البيانات في مشاريعك ACID first. Everything else… eventually. Nim AI智能代理 ACID优先的开发工具 AI工具安装 Nim AI智能代理教程 如何使用Nim AI智能代理 Nim AI智能代理与其他AI工具的比较 ACID first. Everything else… eventually.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mungus451/starlight_v2/Test Commander', 'community', 'mungus451', 'starlight_v2', 'mungus451/starlight_v2', 'Test Commander', 0, 0, 21, '2026-03-04T13:07:01.917Z', '2026-03-04T15:03:15.816Z', '4406f56412956c1a153af7a2f7610b0c91ea0bcf129b2db5c856b40e7cd79324', '{"id":"mungus451/starlight_v2/Test Commander","name":"Test Commander","description":{"zh":"Test Commander 是一款基于 AI 智能代理的 MMORP Idle 浏览器游戏，提供了独特的游戏体验","ja":"Test Commander は AI エージェントを使用した MMORP Idle ブラウザゲームで、ユニークなゲーム体験を提供します","ko":"Test Commander 는 AI 에이전트를 사용하는 MMORP Idle 브라우저 게임으로 독특한 게임 경험을 제공합니다","es":"El Comandante de Pruebas es una herramienta de juego de navegador para desarrolladores, que ofrece un juego MMORP Idle en el navegador","fr":"Le Commandant de Test est un outil de jeu de navigateur pour les développeurs, qui propose un jeu MMORP Idle dans le navigateur","de":"Der Testkommandant ist ein Browsergame-Tool für Entwickler, das ein MMORP-Idle-Spiel im Browser bietet","pt":"O Test Commander é uma ferramenta de AI para jogos de navegador, permitindo que os desenvolvedores criem experiências de jogo mais complexas.","ru":"ИИ Агент Test Commander предназначен для Idle Browser Games, позволяя разработчикам создавать более сложные игровые trải nghiệm.","ar":"قائد الاختبار هو أداة ذكاء اصطناعي للمتصفح، مما يسمح للمطورين بإنشاء تجارب ألعاب أكثر تعقيدا","en":"A MMORP Idle Browser Game"},"seo":{"title":{"zh":"AI智能代理 Test Commander - 浏览器游戏","ja":"AIエージェント Test Commander - ブラウザゲーム","ko":"AI 에이전트 Test Commander - 브라우저 게임","es":"Comandante de Pruebas: Herramienta de Juego de Navegador","fr":"Commandant de Test: Outil de Jeu de Navigateur","de":"Testkommandant: Browsergame-Tool","pt":"Comandante de Testes: Ferramentas de AI para Jogos de Nav...","ru":"ИИ Агенты: Test Commander для Idle Browser Games","ar":"قائد الاختبار: أدوات الذكاء الاصطناعي للمتصفح"