INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('thongdn-it/react-agent-skills/tailwind', 'tailwind', 'thongdn-it', 'react-agent-skills', 'community', 'tailwind thongdn-it react-agent-skills community Tailwind AI智能代理技能是React开发者的终极解决方案 Tailwind AIエージェントスキルは、React開発者のための究極のコレクション Tailwind AI 에이전트 기술은 React 개발자를 위한 궁극의 솔루션 La colección definitiva de habilidades de AI Agent para el ecosistema React, con Tailwind para una mayor eficiencia La collection ultime de compétences AI Agent pour l''écosystème React, avec Tailwind pour une efficacité accrue Die ultimative Sammlung von AI-Agent-Fähigkeiten für das React-Ökosystem, mit Tailwind für eine höhere Effizienz O Tailwind é uma coleção de habilidades de agente de IA para o ecossistema React, melhorando a produtividade do desenvolvedor. Tailwind - это коллекция навыков ИИ Агентов для экосистемы React, повышающая производительность разработчика. Tailwind هو مجموعة من مهارات عميل الذكاء الاصطناعي للرياكت، مما يحسن إنتاجية المطور. The Ultimate AI Agent Skills Collection for the React Ecosystem Tailwind AI智能代理技能 React开发工具 AI工具 如何使用Tailwind Tailwind与React Tailwind安装 React开发指南 The Ultimate AI Agent Skills Collection for the React Ecosystem');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JDenn0514/surveycore/cran', 'community', 'JDenn0514', 'surveycore', 'JDenn0514/surveycore', 'cran', 0, 0, 21, '2026-03-03T22:22:05Z', '2026-03-04T03:44:45.896Z', '89367a85221e5962ded417719386a23f9b1a7c31173a66a89ee7c90253b62e42', '{"id":"JDenn0514/surveycore/cran","name":"cran","description":{"zh":"cran AIエージェント提供核心调查分析基础设施，支持数据分析和调查研究","ja":"cran AIエージェントは調査分析のための核心インフラストラクチャを提供","ko":"cran AI 에이전트는 설문 분석을 위한 핵심 인프라를 제공","es":"CRAN es una infraestructura de análisis de encuestas para desarrolladores que trabajan con datos y R","fr":"CRAN est une infrastructure d''analyse de sondages pour les développeurs qui travaillent avec des données et R","de":"CRAN ist eine Umfragenanalyse-Infrastruktur für Entwickler, die mit Daten und R arbeiten","pt":"O Cran é uma infraestrutura de análise de pesquisas de código aberto que ajuda a processar e analisar dados de pesquisas","ru":"Cran - это открытая инфраструктура для анализа опросов, которая помогает обрабатывать и анализировать данные опросов","ar":"Cran هي بنية تحتية مفتوحة المصدر لتحليل الاستطلاعات تساعد على معالجة و تحليل بيانات الاستطلاعات","en":"Core Survey Analysis Infrastructure"},"seo":{"title":{"zh":"cran AIエージェント：核心调查分析基础设施","ja":"cran AIエージェント：調査分析インフラストラクチャ","ko":"cran AI 에이전트: 핵심 설문 분석 인프라","es":"Herramientas de Análisis de Encuestas con CRAN","fr":"Outils d''Analyse de Sondages avec CRAN","de":"Umfragenanalyse-Tools mit CRAN","pt":"Ferramentas de Análise de Pesquisa com Cran","ru":"ИИ Агенты для Анализа Опросов с Cran","ar":"أدوات تحليل الاستطلاع مع Cran","en":"cran"},"description":{"zh":"cran AIエージェント提供核心调查分析基础设施，支持数据分析和调查研究","ja":"cran AIエージェントは調査分析のための核心インフラストラクチャを提供","ko":"cran AI 에이전트는 설문 분석을 위한 핵심 인프라를 제공","es":"CRAN es una infraestructura de análisis de encuestas para desarrolladores que trabajan con datos y R","fr":"CRAN est une infrastructure d''analyse de sondages pour les développeurs qui travaillent avec des données et R","de":"CRAN ist eine Umfragenanalyse-Infrastruktur für Entwickler, die mit Daten und R arbeiten","pt":"O Cran é uma infraestrutura de análise de pesquisas de código aberto que ajuda a processar e analisar dados de pesquisas","ru":"Cran - это открытая инфраструктура для анализа опросов, которая помогает обрабатывать и анализировать данные опросов","ar":"Cran هي بنية تحتية مفتوحة المصدر لتحليل الاستطلاعات تساعد على معالجة و تحليل بيانات الاستطلاعات","en":"Core Survey Analysis Infrastructure"},"definition":{"en":"Core Survey Analysis Infrastructure"},"features":{"zh":["核心调查分析基础设施","支持数据分析和调查研究","使用R语言进行数据处理","高效的数据分析和处理","灵活的调查分析功能"],"ja":["調査分析のための核心インフラストラクチャ","データ分析と調査研究のサポート","R言語を使用したデータ処理","効率的なデータ分析と処理","柔軟な調査分析機能"],"ko":["설문 분석을 위한 핵심 인프라","데이터 분석과 조사 연구 지원","R 언어를 사용한 데이터 처리","효율적인 데이터 분석과 처리","유연한 조사 분석 기능"],"es":["Análisis de datos de encuestas","Integración con R","Herramientas de visualización de datos","Infraestructura de análisis de encuestas escalable","Compatibilidad con formatos de datos variados"],"fr":["Analyse de données de sondages","Intégration avec R","Outils de visualisation de données","Infrastructure d''analyse de sondages évolutives","Compatibilité avec divers formats de données"],"de":["Umfragen-Datenanalyse","Integration mit R","Daten-Visualisierungstools","Skalierbare Umfragenanalyse-Infrastruktur","Kompatibilität mit verschiedenen Datenformaten"],"pt":["Análise de dados de pesquisas","Processamento de grandes conjuntos de dados","Integração com o R para análise estatística","Ferramentas de visualização de dados","Suporte a múltiplos formatos de dados"],"ru":["Анализ данных опросов","Обработка больших наборов данных","Интеграция с R для статистического анализа","Инструменты визуализации данных","Поддержка нескольких форматов данных"],"ar":["تحليل بيانات الاستطلاعات","معالجة مجموعات كبيرة من البيانات","التكامل مع R لتحليل إحصائي","أدوات تصور البيانات","دعم عدة صيغ للبيانات"]},"keywords":{"zh":["cran AIエージェント","核心调查分析基础设施","数据分析","调查研究","R语言","如何使用cran AIエージェント","cran AIエージェント安装","cran AIエージェント设置指南"],"ja":["cran AIエージェント","調査分析インフラストラクチャ","データ分析","調査研究","R言語","cran AIエージェントの使い方","cran AIエージェントのインストール","cran AIエージェントの設定ガイド"],"ko":["cran AI 에이전트","설문 분석 인프라","데이터 분석","조사 연구","R 언어","cran AI 에이전트 사용법","cran AI 에이전트 설치","cran AI 에이전트 설정 가이드"],"es":["cómo utilizar CRAN","qué es el análisis de encuestas","alternativas a CRAN","CRAN vs otros herramientas de análisis","instalación de CRAN","guía de configuración de CRAN","análisis de datos con R","herramientas de análisis de encuestas"],"fr":["comment utiliser CRAN","qu''est-ce que l''analyse de sondages","alternatives à CRAN","CRAN vs autres outils d''analyse","installation de CRAN","guide de configuration de CRAN","analyse de données avec R","outils d''analyse de sondages"],"de":["wie man CRAN verwendet","was ist Umfragenanalyse","Alternativen zu CRAN","CRAN vs andere Analyse-Tools","Installation von CRAN","Konfigurationsanleitung für CRAN","Datenanalyse mit R","Umfragenanalyse-Tools"],"pt":["como usar Cran","o que é Cran","Cran vs SPSS","Cran alternative","Cran install","Cran setup guide","análise de dados com R","ferramentas de análise de pesquisas"],"ru":["как использовать Cran","что такое Cran","Cran vs SPSS","альтернатива Cran","установка Cran","руководство по настройке Cran","анализ данных с R","инструменты для анализа опросов"],"ar":["كيفية استخدام Cran","ما هو Cran","Cran vs SPSS","بديل Cran","تثبيت Cran","دليل إعداد Cran","تحليل البيانات مع R","أدوات تحليل الاستطلاعات"]}},"owner":"JDenn0514","repo":"surveycore","repoPath":"JDenn0514/surveycore","stars":0,"forks":0,"updatedAt":"2026-03-03T22:22:05Z","topics":["data","r","resear","survey-analysis"],"category":"community","skillMd":{"name":"cran","description":">","bodyPreview":"# CRAN Submission\n\n> **Surveyverse projects:** R CMD check targets (0 errors, 0 warnings, ≤2 notes),\n> pre-approved notes, and `devtools::check()` cadence are defined in\n> `r-package-conventions.md §3`. Those rules take precedence over generic guidance here.\n\n## The four-stage arc\n\n| Stage | What you''re doing | Reference |\n|-------|-------------------|-----------|\n| **Prepare** | DESCRIPTION, docs, URLs, admin — the things `devtools::check()` won''t catch | [preflight-checklist.md](references/pre","body":"# CRAN Submission\n\n> **Surveyverse projects:** R CMD check targets (0 errors, 0 warnings, ≤2 notes),\n> pre-approved notes, and `devtools::check()` cadence are defined in\n> `r-package-conventions.md §3`. Those rules take precedence over generic guidance here.\n\n## The four-stage arc\n\n| Stage | What you''re doing | Reference |\n|-------|-------------------|-----------|\n| **Prepare** | DESCRIPTION, docs, URLs, admin — the things `devtools::check()` won''t catch | [preflight-checklist.md](references/preflight-checklist.md) |\n| **Check** | `R CMD check --as-cran`, platform testing, NOTE triage | [check-and-triage.md](references/check-and-triage.md) |\n| **Submit** | Build tarball, `devtools::submit_cran()`, write `cran-comments.md` | [submit-and-respond.md](references/submit-and-respond.md) |\n| **Respond** | Point-by-point reviewer responses, resubmission | [submit-and-respond.md](references/submit-and-respond.md) |\n\n## Tool map\n\n| Task | Tool |\n|------|------|\n| Full local check | `devtools::check()` |\n| CRAN-style check (fast iteration) | `devtools::check(args = \"--as-cran\")` |\n| CRAN-style check (submission confidence) | `R CMD build .` then `R CMD check --as-cran pkg_x.y.z.tar.gz` |\n| Docs and examples only | `devtools::check_man()` |\n| Windows + R-devel | `devtools::check_win_devel()` |\n| Multi-platform preflight | `rhub::check_for_cran()` |\n| URL validation | `urlchecker::url_check()` |\n| Submit to CRAN | `devtools::submit_cran()` |\n| Generate release issue checklist | `usethis::use_release_issue()` |\n| Create `cran-comments.md` | `usethis::use_cran_comments()` |\n| Create `NEWS.md` | `usethis::use_news_md()` |\n| Bump version | `usethis::use_version()` |\n\n## The CRAN mindset\n\nCRAN checks run in a **minimal, non-interactive environment** with no hidden\ndependencies. Write code as if:\n\n- There is no network access during checks (examples, tests, vignettes)\n- Nothing is written outside `tempdir()`\n- There are no interactive prompts\n- Examples run in a few seconds each — not minutes\n- No binary executables are bundled in the source package\n\nPrefer fixes that make checks green everywhere over explanations that justify\nfragility.\n\n## ERROR / WARNING / NOTE triage\n\n- **ERRORs**: Always blockers. Fix before submission.\n- **WARNINGs**: Almost always blockers. Very rare contextual exceptions.\n- **NOTEs**: Split into two types:\n  - *Actionable* — fix it (undeclared dependency, broken URL, too-long examples)\n  - *Contextual* — explain in `cran-comments.md` (incoming feasibility NOTE on new submissions)\n\nWhen keeping a NOTE, `cran-comments.md` must answer:\n\n1. What is the NOTE?\n2. Why does it happen?\n3. Why is it safe / expected?\n4. What did you do to minimize it?\n\n## Quality gate (recommended order)\n\n1. `devtools::check()` is clean — 0 errors, 0 warnings\n2. Preflight checklist complete — see [preflight-checklist.md](references/preflight-checklist.md)\n3. Tarball check: `R CMD build .` → `R CMD check --as-cran pkg_x.y.z.tar.gz`\n4. Cross-platform: `devtools::check_win_devel()` at minimum; R-hub for broader coverage\n5. `cran-comments.md` written and reviewed\n6. Ready to respond point-by-point if CRAN asks\n\n## High-frequency failure surfaces\n\n- **DESCRIPTION metadata**: Title case, forbidden phrases, missing `cph` role\n- **Documentation**: Missing `@return` or `@examples` on exported functions\n- **Examples**: network calls, unseeded randomness, writes outside tempdir, commented-out code\n- **URLs**: HTTP instead of HTTPS, redirecting links\n- **Undeclared dependencies**: packages used in code/examples/tests but absent from DESCRIPTION\n- **Package size / runtime**: large embedded data, slow vignettes or examples\n\n## External resources\n\n- CRAN policy: https://cran.r-project.org/web/packages/policies.html\n- CRAN submission checklist: https://cran.r-project.org/web/packages/submission_checklist.html\n- Writing R Extensions (R CMD check): https://cran.r-project.org/doc/manuals/r-release/R-exts.html\n- R Packages (2e) — releasing to CRAN: https://r-pkgs.org/release.html\n- win-builder: https://win-builder.r-project.org/\n- macbuilder: https://mac.r-project.org/macbuilder/submit.html\n"},"lastSynced":"2026-03-04T03:44:45.896Z","agentAnalysis":{"suitability":{"en":"Essential for R Package Developer Agents requiring automated CRAN submission compliance checks.","zh":"适合于需要自动化CRAN提交合规性检查的R包开发代理。","ja":"CRANへの提出に自動化されたコンプライアンスチェックが必要なRパッケージ開発エージェントに不可欠。","ko":"자동화된 CRAN 제출 준수 확인이 필요한 R 패키지 개발 에이전트에 필수입니다.","es":"Esencial para Agentes de Desarrollo de Paquetes R que requieren comprobaciones de cumplimiento automatizadas de envío a CRAN.","fr":"Essentiel pour les Agents de Développement de Packages R nécessitant des vérifications de conformité automatiques de soumission à CRAN.","de":"Wesentlich für R-Paket-Entwickler-Agents, die automatisierte CRAN-Einreichungs-Compliance-Prüfungen erfordern.","pt":"Essencial para Agentes de Desenvolvedores de Pacotes R que exigem verificações de conformidade de submissão automatizada do CRAN.","ru":"Необходимо для Агентов Разработчиков Пакетов R, требующих автоматических проверок соответствия при подаче в CRAN.","ar":"ضروري لموكلات مطورو الحزم R التي تتطلب فحوصات امتثال للتقديم الآلي في CRAN."},"recommendation":{"en":"Enables rigorous R package validation against CRAN''s strict standards through automated `devtools::check()` execution and pre-approved note management. Provides infrastructure for comprehensive survey analysis and ensures adherence to R CMD check targets (0 errors, 0 warnings, ≤2 notes) as defined in r-package-conventions.md.","zh":"通过自动执行`devtools::check()`和预批准的注释管理，能够对R包进行严格的验证，以满足CRAN的严格标准。提供了综合调查分析的基础设施，并确保遵守R CMD检查目标（0个错误，0个警告，≤2个注释），如r-package-conventions.md中定义的。","ja":"自動で`devtools::check()`を実行し、事前に承認された注釈を管理することで、CRANの厳格な基準に従ったRパッケージの検証を厳密に行うことができます。包括的な調査分析のインフラストラクチャを提供し、r-package-conventions.mdで定義されているR CMDチェックのターゲット（0エラー、0警告、≤2注釈）に従っていることを保証します。","ko":"자동으로 `devtools::check()`를 실행하고, 사전 승인된 주석을 관리하여, CRAN의 엄격한 표준에 따라 R 패키지의 유효성을 철저하게 검사할 수 있습니다. 포괄적인 조사 분석을 위한 인프라를 제공하며, r-package-conventions.md에서 정의한 R CMD 확인 대상(0개 오류, 0개 경고, ≤2개 주석)에 따라 규정합니다.","es":"Permite una validación rigurosa de paquetes R contra los estrictos estándares de CRAN a través de la ejecución automatizada de `devtools::check()` y gestión de notas preaprobadas. Proporciona infraestructura para un análisis de encuestas exhaustivo y garantiza el cumplimiento de los objetivos de R CMD check (0 errores, 0 advertencias, ≤2 notas) definidos en r-package-conventions.md.","fr":"Permet une validation rigoureuse des packages R contre les normes strictes de CRAN via l''exécution automatique de `devtools::check()` et la gestion de notes préapprouvées. Fournit une infrastructure pour une analyse d''enquête exhaustive et garantit le respect des cibles de vérification R CMD (0 erreurs, 0 avertissements, ≤2 notes) définies dans r-package-conventions.md.","de":"Ermöglicht eine strengere Überprüfung von R-Paketen gegen die strengen Standards von CRAN durch die automatisierte Ausführung von `devtools::check()` und die Verwaltung vorab genehmigter Notizen. Bietet eine Infrastruktur für eine umfassende Umfrageanalyse und stellt sicher, dass die Ziele von R CMD check (0 Fehler, 0 Warnungen, ≤2 Notizen) wie in r-package-conventions.md definiert eingehalten werden.","pt":"Permite uma validação rigorosa de pacotes R contra os padrões rigorosos do CRAN por meio da execução automatizada de `devtools::check()` e gerenciamento de notas pré-aprovadas. Fornece infraestrutura para análise abrangente de pesquisas e garante a adesão aos alvos de verificação do R CMD (0 erros, 0 avisos, ≤2 notas) conforme definido em r-package-conventions.md.","ru":"Позволяет проводить тщательную проверку пакетов R на соответствие строгим стандартам CRAN посредством автоматического выполнения `devtools::check()` и управления предварительно одобренными заметками. Обеспечивает инфраструктуру для всестороннего анализа опросов и гарантирует соблюдение целей проверки R CMD (0 ошибок, 0 предупреждений, ≤2 заметки), определенных в r-package-conventions.md.","ar":"يمكّن من التحقق الصارم للحزم R ضد المعايير الصارمة ل CRAN من خلال تنفيذ `devtools::check()` الآلي وإدارة الملاحظات المعتمدة مسبقًا. يوفر البنية التحتية للتحليل الشامل للمسوح وضمان الالتزام بأهداف فحص R CMD (0 أخطاء ، 0 تحذيرات ، ≤2 ملاحظات) كما هو محدد في r-package-conventions.md."},"useCases":{"en":["Automating CRAN submission pre-flight checks","Validating R package documentation and DESCRIPTION files","Managing pre-approved CRAN submission notes","Executing comprehensive R CMD check routines"],"zh":["自动化CRAN提交前检查","验证R包文档和DESCRIPTION文件","管理预批准的CRAN提交注释","执行综合R CMD检查例程"],"ja":["CRANへの提出前の自動化されたチェック","RパッケージのドキュメントとDESCRIPTIONファイルの検証","事前に承認されたCRANへの提出注釈の管理","包括的なR CMDチェックルーチンの実行"],"ko":["CRAN 제출 전 자동화된 확인","R 패키지 문서 및 DESCRIPTION 파일의 유효성 검사","사전 승인된 CRAN 제출 주석 관리","포괄적인 R CMD 확인 루틴 실행"],"es":["Automatización de comprobaciones pre-vuelo de envío a CRAN","Validación de la documentación y los archivos DESCRIPTION de paquetes R","Gestión de notas de envío a CRAN preaprobadas","Ejecución de rutinas de comprobación R CMD exhaustivas"],"fr":["Automatisation des vérifications pré-vol de soumission à CRAN","Validation de la documentation et des fichiers DESCRIPTION de packages R","Gestion de notes de soumission à CRAN préapprouvées","Exécution de routines de vérification R CMD exhaustives"],"de":["Automatisierung von Vor-Flug-Prüfungen für die Einreichung bei CRAN","Überprüfung der Dokumentation und der DESCRIPTION-Dateien von R-Paketen","Verwaltung von vorab genehmigten Notizen für die Einreichung bei CRAN","Ausführung umfassender R CMD-Überprüfungs-Routinen"],"pt":["Automatizando verificações pré-voo de submissão do CRAN","Validando documentação e arquivos DESCRIPTION de pacotes R","Gerenciando notas de submissão do CRAN pré-aprovadas","Executando rotinas de verificação abrangentes do R CMD"],"ru":["Автоматизация предварительных проверок подачи в CRAN","Проверка документации и файлов DESCRIPTION пакетов R","Управление предварительно одобренными заметками при подаче в CRAN","Выполнение всесторонних проверок R CMD"],"ar":["تأتمة فحوصات ما قبل الطيران لتقديم CRAN","التحقق من توثيق وملفات DESCRIPTION للحزم R","إدارة الملاحظات المعتمدة مسبقًا لتقديم CRAN","تنفيذ إجراءات فحص شاملة ل R CMD"]},"limitations":{"en":["R-specific ecosystem only","Requires devtools dependency","Follows CRAN-specific conventions from r-package-conventions.md"],"zh":["仅限R特定生态系统","需要devtools依赖","遵循r-package-conventions.md中的CRAN特定约定"],"ja":["R特有のエコシステムのみ","devtoolsの依存関係が必要","r-package-conventions.mdに記載されたCRAN特有の規約に従う"],"ko":["R 특정 생태계만 해당","devtools 종속성 필요","r-package-conventions.md에記載된 CRAN 특정 규약을 따름"],"es":["Ecosistema específico de R solo","Requiere la dependencia de devtools","Sigue las convenciones específicas de CRAN de r-package-conventions.md"],"fr":["Écosystème spécifique à R uniquement","Nécessite la dépendance à devtools","Suit les conventions spécifiques à CRAN de r-package-conventions.md"],"de":["Nur R-spezifisches Ökosystem","Benötigt die Abhängigkeit von devtools","Befolgt die CRAN-spezifischen Konventionen von r-package-conventions.md"],"pt":["Ecossistema específico do R apenas","Exige dependência do devtools","Segue convenções específicas do CRAN de r-package-conventions.md"],"ru":["Только экосистема R","Требует зависимости от devtools","Следует конвенциям CRAN, определенным в r-package-conventions.md"],"ar":["نظام بيئي محدد ل R فقط","يتطلب تبعية ل devtools","يتابع الاتفاقيات المحددة ل CRAN في r-package-conventions.md"]},"version":3},"contentHash":"89367a85221e5962ded417719386a23f9b1a7c31173a66a89ee7c90253b62e42","qualityScore":21}');
