INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('danthegoodman1/netfence/integrity-checks', 'community', 'danthegoodman1', 'netfence', 'danthegoodman1/netfence', 'integrity-checks', 87, 2, 20, '2026-02-22T06:10:53Z', '2026-02-27T13:09:00.137Z', 'ae6cd7539480d3ef45970850fcf9ca448ecead210e81cd60b980dc90e4ea6cd7', '{"id":"danthegoodman1/netfence/integrity-checks","name":"integrity-checks","description":{"zh":"AI智能代理提供了类似Envoy xDS的eBPF过滤器管理功能，帮助开发者高效管理和优化网络流量","ja":"AIエージェントはEnvoy xDSスタイルのeBPFフィルター管理機能を提供し、開発者がネットワークトラフィックを効率的に管理および最適化できるようにします","ko":"AI 에이전트는 Envoy xDS 스타일의 eBPF 필터 관리 기능을 제공하여 개발자가 네트워크 트래픽을 효율적으로 관리하고 최적화할 수 있도록 합니다","es":"Integrity-checks es una herramienta de AI que proporciona verificaciones de integridad para filtros eBPF, similar a Envoy xDS","fr":"Integrity-checks est un outil IA qui fournit des vérifications d''intégrité pour les filtres eBPF, similaire à Envoy xDS","de":"Integrity-checks ist ein KI-Tool, das Integritätsprüfungen für eBPF-Filter bereitstellt, ähnlich wie Envoy xDS","pt":"O integrity-checks é uma ferramenta de IA que funciona como o Envoy xDS, mas para filtros eBPF, garantindo a segurança e desempenho dos aplicativos","ru":"ИИ Агенты integrity-checks - это инструмент, который работает как Envoy xDS, но для фильтров eBPF, обеспечивая безопасность и производительность приложений","ar":"أدوات التحقق من الصحة integrity-checks هي أداة متوافقة تعمل مثل Envoy xDS ولكن لأفلاتر eBPF، مما يضمن أمان وتأثير التطبيقات","en":"Like Envoy xDS, but for eBPF filters"},"seo":{"title":{"zh":"AI智能代理：Envoy xDS风格的eBPF过滤器","ja":"AIエージェント：Envoy xDSスタイルのeBPFフィルター","ko":"AI 에이전트: Envoy xDS 스타일의 eBPF 필터","es":"Herramientas de AI: integrity-checks para filtros eBPF","fr":"Outils IA: integrity-checks pour les filtres eBPF","de":"KI-Tools: integrity-checks für eBPF-Filter","pt":"Ferramentas de Integridade de IAs - integrity-checks","ru":"ИИ Агенты для Проверки Целостности - integrity-checks","ar":"أدوات متوافقة للتحقق من الصحة - integrity-checks","en":"integrity-checks"},"description":{"zh":"AI智能代理提供了类似Envoy xDS的eBPF过滤器管理功能，帮助开发者高效管理和优化网络流量","ja":"AIエージェントはEnvoy xDSスタイルのeBPFフィルター管理機能を提供し、開発者がネットワークトラフィックを効率的に管理および最適化できるようにします","ko":"AI 에이전트는 Envoy xDS 스타일의 eBPF 필터 관리 기능을 제공하여 개발자가 네트워크 트래픽을 효율적으로 관리하고 최적화할 수 있도록 합니다","es":"Integrity-checks es una herramienta de AI que proporciona verificaciones de integridad para filtros eBPF, similar a Envoy xDS","fr":"Integrity-checks est un outil IA qui fournit des vérifications d''intégrité pour les filtres eBPF, similaire à Envoy xDS","de":"Integrity-checks ist ein KI-Tool, das Integritätsprüfungen für eBPF-Filter bereitstellt, ähnlich wie Envoy xDS","pt":"O integrity-checks é uma ferramenta de IA que funciona como o Envoy xDS, mas para filtros eBPF, garantindo a segurança e desempenho dos aplicativos","ru":"ИИ Агенты integrity-checks - это инструмент, который работает как Envoy xDS, но для фильтров eBPF, обеспечивая безопасность и производительность приложений","ar":"أدوات التحقق من الصحة integrity-checks هي أداة متوافقة تعمل مثل Envoy xDS ولكن لأفلاتر eBPF، مما يضمن أمان وتأثير التطبيقات","en":"Like Envoy xDS, but for eBPF filters"},"definition":{"en":"Like Envoy xDS, but for eBPF filters"},"features":{"zh":["支持eBPF过滤器管理","提供高效的网络流量优化","兼容Envoy xDS风格的配置","支持多种网络协议","提供实时的网络流量监控"],"ja":["eBPFフィルター管理のサポート","ネットワークトラフィックの効率的な最適化","Envoy xDSスタイルの構成の互換性","複数のネットワークプロトコルのサポート","リアルタイムのネットワークトラフィックモニタリング"],"ko":["eBPF 필터 관리 지원","네트워크 트래픽의 효율적인 최적화","Envoy xDS 스타일의 구성 호환","다양한 네트워크 프로토콜 지원","실시간 네트워크 트래픽 모니터링"],"es":["Verificaciones de integridad para filtros eBPF","Similar a Envoy xDS","Mejora la seguridad de tus filtros","Compatibilidad con eBPF","Fácil integración"],"fr":["Vérifications d''intégrité pour les filtres eBPF","Similaire à Envoy xDS","Améliore la sécurité de vos filtres","Compatibilité avec eBPF","Intégration facile"],"de":["Integritätsprüfungen für eBPF-Filter","Ähnlich wie Envoy xDS","Verbessert die Sicherheit Ihrer Filter","Kompatibilität mit eBPF","Einfache Integration"],"pt":["Verificação de integridade de filtros eBPF","Melhoria da segurança dos aplicativos","Compatibilidade com Envoy xDS","Otimização do desempenho dos aplicativos","Fácil integração com outras ferramentas de IA"],"ru":["Проверка целостности фильтров eBPF","Повышение безопасности приложений","Совместимость с Envoy xDS","Оптимизация производительности приложений","Легкая интеграция с другими ИИ инструментами"],"ar":["التحقق من صحة أفلاتر eBPF","تحسين أمان التطبيقات","التوافق مع Envoy xDS","تحسين أداء التطبيقات","إمكانية التكامل السهل مع أدوات متوافقة أخرى"]},"keywords":{"zh":["AI智能代理","eBPF过滤器","Envoy xDS","网络流量优化","如何使用AI智能代理","AI智能代理安装","eBPF过滤器配置"],"ja":["AIエージェント","eBPFフィルター","Envoy xDS","ネットワークトラフィック最適化","AIエージェントの使用方法","AIエージェントのインストール","eBPFフィルターの構成"],"ko":["AI 에이전트","eBPF 필터","Envoy xDS","네트워크 트래픽 최적화","AI 에이전트 사용 방법","AI 에이전트 설치","eBPF 필터 구성"],"es":["herramientas de AI para filtros eBPF","cómo usar integrity-checks","qué es integrity-checks","integrity-checks vs Envoy xDS","instalación de integrity-checks","guía de configuración de integrity-checks"],"fr":["outils IA pour les filtres eBPF","comment utiliser integrity-checks","qu''est-ce que integrity-checks","integrity-checks vs Envoy xDS","installation d''integrity-checks","guide de configuration d''integrity-checks"],"de":["KI-Tools für eBPF-Filter","wie man integrity-checks verwendet","was ist integrity-checks","integrity-checks vs Envoy xDS","installation von integrity-checks","konfigurationsanleitung für integrity-checks"],"pt":["como usar integrity-checks","o que é integrity-checks","integrity-checks vs Envoy xDS","integrity-checks instalação","guia de configuração do integrity-checks","ferramentas de IA para segurança","otimização de desempenho de aplicativos","integrity-checks alternative"],"ru":["как использовать ИИ Агенты integrity-checks","что такое ИИ Агенты integrity-checks","ИИ Агенты integrity-checks vs Envoy xDS","установка ИИ Агентов integrity-checks","руководство по настройке ИИ Агентов integrity-checks","ИИ инструменты для безопасности","оптимизация производительности приложений","ИИ Агенты integrity-checks альтернатива"],"ar":["كيفية استخدام أدوات التحقق من الصحة integrity-checks","ما هي أدوات التحقق من الصحة integrity-checks","أدوات التحقق من الصحة integrity-checks مقابل Envoy xDS","تثبيت أدوات التحقق من الصحة integrity-checks","دليل إعداد أدوات التحقق من الصحة integrity-checks","أدوات متوافقة لأمان التطبيقات","تحسين أداء التطبيقات","أدوات التحقق من الصحة integrity-checks بديلة"]}},"owner":"danthegoodman1","repo":"netfence","repoPath":"danthegoodman1/netfence","stars":87,"forks":2,"updatedAt":"2026-02-22T06:10:53Z","topics":[],"category":"community","skillMd":{"name":"integrity-checks","description":"Integrity checks","bodyPreview":"# Integrity checks\n\nAfter edits, ensure that the new code does not introduce any deadlocks or race conditions. Additionally, do not be wasteful with holding locks when something doesn''t need it.","body":"# Integrity checks\n\nAfter edits, ensure that the new code does not introduce any deadlocks or race conditions. Additionally, do not be wasteful with holding locks when something doesn''t need it.\n"},"lastSynced":"2026-02-27T13:09:00.137Z","agentAnalysis":{"suitability":{"en":"Perfect for Systems Programming Agents needing advanced eBPF filter validation and deadlock detection capabilities.","zh":"非常适合需要高级 eBPF 过滤器验证和死锁检测功能的系统编程代理。","ja":"システムプログラミングエージェントが高度な eBPF フィルタ検証およびデッドロック検出機能を必要とする場合に最適です。","ko":"고급 eBPF 필터 유효성 검사 및 데드락 감지 기능이 필요한 시스템 프로그래밍 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Programación de Sistemas que necesitan una validación avanzada de filtros eBPF y capacidades de detección de deadlocks.","fr":"Idéal pour les agents de programmation système nécessitant une validation de filtres eBPF avancée et des capacités de détection de deadlock.","de":"Perfekt für Systemprogrammierungsagenten, die eine erweiterte eBPF-Filtervalidierung und Deadlock-Erkennungsfunktionen benötigen.","pt":"Perfeito para Agentes de Programação de Sistemas que necessitam de validação avançada de filtros eBPF e capacidades de detecção de deadlocks.","ru":"Идеально подходит для агентов системного программирования, которым необходимы расширенные возможности проверки фильтров eBPF и обнаружения тупиков.","ar":"مثالي لعمليات برمجة النظام التي تحتاج إلى التحقق المتقدم من مرشحات eBPF وقدرات الكشف عن تجميدات"},"recommendation":{"en":"Empowers agents to perform comprehensive integrity checks on eBPF filters, preventing deadlocks and race conditions, while optimizing lock management using Envoy xDS-like functionality.","zh":"赋予代理执行 eBPF 过滤器的全面完整性检查的能力，防止死锁和竞态条件，同时使用类似 Envoy xDS 的功能优化锁管理。","ja":"エージェントが eBPF フィルタの包括的な整合性チェックを実行する機能を提供し、デッドロックとレースコンディションを防ぎながら、Envoy xDSのような機能を使用してロック管理を最適化します。","ko":"에이전트가 eBPF 필터에 대한 포괄적인 무결성 검사를 수행할 수 있는 기능을 제공하여 데드락과 경쟁 조건을 방지하며 Envoy xDS와 같은 기능을 사용하여 잠금 관리를 최적화합니다.","es":"Habilita a los agentes a realizar controles de integridad completos en los filtros eBPF, evitando deadlocks y condiciones de carrera, mientras optimiza la gestión de bloqueos utilizando funcionalidad similar a Envoy xDS.","fr":"Permet aux agents d''effectuer des vérifications d''intégrité complètes sur les filtres eBPF, empêchant les deadlocks et les conditions de course, tout en optimisant la gestion des verrous à l''aide de la fonctionnalité Envoy xDS.","de":"Ermächtigt die Agenten, umfassende Integritätsprüfungen auf eBPF-Filtern durchzuführen, Deadlocks und Rennbedingungen zu verhindern, während die Verwaltung von Sperren mit Funktionalität ähnlich wie Envoy xDS optimiert wird.","pt":"Habilita os agentes a realizar verificações de integridade abrangentes em filtros eBPF, prevenindo deadlocks e condições de corrida, ao mesmo tempo em que otimiza o gerenciamento de bloqueio usando funcionalidade semelhante ao Envoy xDS.","ru":"Предоставляет агентам возможность проводить полные проверки целостности фильтров eBPF, предотвращая тупики и гонки, а также оптимизируя управление блокировками с помощью функциональности, аналогичной Envoy xDS.","ar":"يُمكّن الوكلاء من إجراء فحوصات شاملة لمرشحات eBPF، ومنع تجميدات وظروف السباق، في نفس الوقت الذي يتم فيه تحسين إدارة القفل باستخدام وظيفة Envoy xDS"},"useCases":{"en":["Debugging eBPF filter code for potential deadlocks","Validating race condition-free execution of eBPF programs","Optimizing lock usage in eBPF filters for improved performance"],"zh":["调试 eBPF 过滤器代码以检测潜在的死锁","验证 eBPF 程序的无竞态条件执行","优化 eBPF 过滤器中的锁使用以提高性能"],"ja":["潜在的なデッドロックを検出するために eBPF フィルタコードをデバッグする","eBPF プログラムのレースコンディションのない実行を検証する","パフォーマンスの向上のために eBPF フィルタ内のロック使用を最適化する"],"ko":[" 잠재적인 데드락을 감지하기 위해 eBPF 필터 코드를 디버깅하는 것","eBPF 프로그램의 경쟁 조건이 없는 실행을 확인하는 것","성능 향상을 위해 eBPF 필터 내의 잠금 사용을 최적화하는 것"],"es":["Depuración de código de filtros eBPF para deadlocks potenciales","Validación de la ejecución libre de condiciones de carrera de programas eBPF","Optimización del uso de bloqueos en filtros eBPF para un mejor rendimiento"],"fr":["Débogage du code de filtres eBPF pour les deadlocks potentiels","Validation de l''exécution sans conditions de course des programmes eBPF","Optimisation de l''utilisation des verrous dans les filtres eBPF pour améliorer les performances"],"de":["Debuggen von eBPF-Filtercode für potenzielle Deadlocks","Validierung der ausführungsfreien Rennbedingungen von eBPF-Programmen","Optimierung der Verwendung von Sperren in eBPF-Filtern für eine bessere Leistung"],"pt":["Depurar código de filtro eBPF para deadlocks potenciais","Validar execução sem condições de corrida de programas eBPF","Otimizar uso de bloqueio em filtros eBPF para melhor desempenho"],"ru":["Отладка кода фильтра eBPF для потенциальных тупиков","Проверка выполнения программ eBPF без гонок","Оптимизация использования блокировок в фильтрах eBPF для улучшения производительности"],"ar":["تصحيح أخطاء في رمز مرشح eBPF للتعليق المحتمل","التحقق من تشغيل برامج eBPF بدون ظروف السباق","تحسين استخدام القفل في مرشحات eBPF لتحسين الأداء"]},"limitations":{"en":["Requires eBPF filter code access","Limited to preventing deadlocks and race conditions","Needs careful lock management to avoid wasteful holding"],"zh":["需要访问 eBPF 过滤器代码","仅限于防止死锁和竞态条件","需要谨慎的锁管理以避免浪费性持有"],"ja":["eBPF フィルタコードへのアクセスが必要","デッドロックとレースコンディションの防止のみ","無駄な保持を避けるために慎重なロック管理が必要"],"ko":["eBPF 필터 코드에 대한 접근이 필요함","데드락과 경쟁 조건을 방지하는 것만으로 제한됨","무의미한 보유를 피하기 위해 신중한 잠금 관리가 필요함"],"es":["Requiere acceso al código de filtros eBPF","Limitado a la prevención de deadlocks y condiciones de carrera","Necesita una gestión cuidadosa de bloqueos para evitar una retención inútil"],"fr":["Nécessite un accès au code de filtres eBPF","Limité à la prévention des deadlocks et des conditions de course","Nécessite une gestion soigneuse des verrous pour éviter une prise inutile"],"de":["Benötigt Zugriff auf eBPF-Filtercode","Begrenzt auf die Verhinderung von Deadlocks und Rennbedingungen","Benötigt eine sorgfältige Verwaltung von Sperren, um eine nutzlose Blockierung zu vermeiden"],"pt":["Requer acesso ao código de filtro eBPF","Limitado a prevenir deadlocks e condições de corrida","Necessita de gerenciamento de bloqueio cuidadoso para evitar segurar desperdiçado"],"ru":["Требует доступа к коду фильтра eBPF","Ограничен предотвращением тупиков и гонок","Требует тщательного управления блокировками, чтобы избежать расточительного удержания"],"ar":["يتطلب الوصول إلى رمز مرشح eBPF","محدود لمنع التجميدات وظروف السباق","يحتاج إلى إدارة القفل بحذر لتجنب الاحتفاظ بالهدر"]},"version":3},"contentHash":"ae6cd7539480d3ef45970850fcf9ca448ecead210e81cd60b980dc90e4ea6cd7","qualityScore":20}');
